window.psalmsCsCyrillic = {"1": {"number": 1, "title": "Псалом 1. (1)", "subtitle": "", "verses": [{"num": "1.", "text": "Блажен муж, иже не иде на совјет нечестивих, и на пути грјешних не ста, и на сједалишчи губитељеј не сједе:"}, {"num": "2.", "text": "Но в закоње Господњи воља јего, и в закоње Јего поучитсја ден и ношч."}, {"num": "3.", "text": "И будет јако древо насажденоје при исходишчих вод, јеже плод свој даст во времја своје, и лист јего не отпадет: и всја јелика ашче творит, успјејет."}, {"num": "4.", "text": "Не тако нечестивији, не тако: но јако прах, јегоже возметајет вјетар от лица земљи."}, {"num": "5.", "text": "Сего ради не воскреснут нечестивији на суд, ниже грјешници в совјет праведних."}, {"num": "6.", "text": "Јако вјест Господ пут праведних, и пут нечестивих погибнет."}]}, "2": {"number": 2, "title": "Псалом 2. (2)", "subtitle": "", "verses": [{"num": "1.", "text": "Вскују шаташасја јазици, и људије поучишасја тшчетним."}, {"num": "2.", "text": "Предсташа царији земстији, и књази собрашасја вкупје на Господа и на Христа Јего."}, {"num": "3.", "text": "Расторгнем узи их, и отвержем от нас иго их."}, {"num": "4.", "text": "Живиј на Небесјех посмјејетсја им, и Господ поругајетсја им."}, {"num": "5.", "text": "Тогда возглагољет к њим гњевом својим, и јаростију својеју смјатет ја."}, {"num": "6.", "text": "Аз же постављен јесам цар от Њего над Сионом, гороју свјатоју Јего."}, {"num": "7.", "text": "Возвјешчавај повељеније Господње, Господ рече ко Мње: Син Мој јеси Ти, Аз днес родих Тја."}, {"num": "8.", "text": "Проси от Мене, и дам ти јазики достојаније твоје, и одержаније твоје конци Земљи."}, {"num": "9.", "text": "Упасеши ја жезлом жељезним, јако сосуди скудељничи сокрушиши ја."}, {"num": "10.", "text": "И ниње царије разумјејте, накажитесја вси судјашчији земљи."}, {"num": "11.", "text": "Работајте Господеви со страхом, и радујтесја Јему с трепетом."}, {"num": "12.", "text": "Примите наказаније, да не когда прогњевајетсја Господ, и погибнете от пути праведнаго, јегда возгоритсја вскорје јарост Јего, блажени вси надјејушчијисја нањ."}]}, "3": {"number": 3, "title": "Псалом 3. (3)", "subtitle": "", "verses": [{"num": "1.", "text": "Господи, что сја умножиша стужајушчији ми, мнози востајут на мја."}, {"num": "2.", "text": "Мнози глагољут души мојеј: њест спасенија јему в Бозје јего."}, {"num": "3.", "text": "Ти же Господи заступник мој јеси, слава моја, и возносјај главу моју."}, {"num": "4.", "text": "Гласом мојим ко Господу возвах, и услиша мја от гори свјатија својеја."}, {"num": "5.", "text": "Аз уснух, и спах, востах, јако Господ заступит мја."}, {"num": "6.", "text": "Не убојусја от тем људеј, окрест нападајушчих на мја."}, {"num": "7.", "text": "Воскресни Господи, спаси мја Боже мој, јако Ти поразил јеси всја враждујушчија ми всује, зуби грјешников сокрушил јеси."}, {"num": "8.", "text": "Господње јест спасеније, и на људех Твојих благословеније Твоје. Слава:"}]}, "4": {"number": 4, "title": "Псалом 4. (4)", "subtitle": "", "verses": [{"num": "1.", "text": "Внегда, призвати ми, услиша мја Бог правди мојеја, в скорби распространил мја јеси, ушчедри мја, и услиши молитву моју."}, {"num": "2.", "text": "Синове человјечестији, докоље тјажкосердији; вскују љубите сујету, и ишчете лажи;"}, {"num": "3.", "text": "И увједите, јако удиви Господ преподобнаго својего, Господ услишит мја, внегда возвати ми к Њему."}, {"num": "4.", "text": "Гњевајтесја, и не согрјешајте, јаже глагољете в сердцах ваших, на ложах ваших умилитесја."}, {"num": "5.", "text": "Пожрите жертву правди, и уповајте на Господа."}, {"num": "6.", "text": "Мнози глагољут: кто јавит нам благаја: знаменасја на нас свјет лица Твојего, Господи."}, {"num": "7.", "text": "Дал јеси веселије в сердцје мојем: от плода пшеници, вина и јелеја својего умножишасја."}, {"num": "8.", "text": "В мирје вкупје усну и почију, јако Ти Господи јединаго на упованије вселил мја јеси."}]}, "5": {"number": 5, "title": "Псалом 5. (5)", "subtitle": "", "verses": [{"num": "1.", "text": "Глаголи моја внуши Господи, разумјеј званије моје."}, {"num": "2.", "text": "Вонми гласу мољенија мојего, Царју мој и Боже мој, јако к Тебје помољусја Господи."}, {"num": "3.", "text": "Зајутра услиши глас мој: зајутра предстану Ти, и узриши мја."}, {"num": "4.", "text": "Јако Бог не хотјај безаконија, Ти јеси: не приселитсја к Тебје лукавнујај."}, {"num": "5.", "text": "Ниже пребудет безаконици пред очима Твојима: возненавидјел јеси всја дјелајушчија безаконије."}, {"num": "6.", "text": "Погубиши всја глагољушчија лажу: мужа кровеј и лестива гнушајетсја Господ."}, {"num": "7.", "text": "Аз же множеством милости Твојеја, вниду в дом Твој, поклоњусја ко храму свјатому Твојему, во страсје Твојем."}, {"num": "8.", "text": "Господи, настави мја правдоју Твојеју, враг мојих ради исправи пред Тобоју пут мој."}, {"num": "9.", "text": "Јако њест во устјех их истини, сердце их сујетно, гроб отверст гортан их, јазики својими лашчаху."}, {"num": "10.", "text": "Суди им Боже, да отпадут от мислеј својих, по множеству нечестија их изрини ја, јако преогорчиша Тја Господи."}, {"num": "11.", "text": "И да возвесељатсја вси уповајушчији на Тја, во вјек возрадујутсја: и вселишисја в њих, и похваљатсја о Тебје љубјашчији имја Твоје."}, {"num": "12.", "text": "Јако Ти благословиши праведника Господи, јако оружијем благовољенија вјенчал јеси нас."}]}, "6": {"number": 6, "title": "Псалом 6. (6)", "subtitle": "", "verses": [{"num": "1.", "text": "Господи, да не јаростију Твојеју обличиши мене, ниже гњевом Твојим накажеши мене."}, {"num": "2.", "text": "Помилуј мја Господи, јако немошчен јесам: исцјели мја Господи, јако смјатошасја кости моја."}, {"num": "3.", "text": "И душа моја смјатесја зјело, и Ти Господи, докоље."}, {"num": "4.", "text": "Обратисја Господи, избави душу моју: спаси мја ради милости Твојеја."}, {"num": "5.", "text": "Јако њест в смерти поминајај Тебе, во адје же кто исповјестсја Тебје;"}, {"num": "6.", "text": "Утрудихсја воздиханијем мојим, измију на всјаку ношч ложе моје, слезами мојими постељу моју омочу."}, {"num": "7.", "text": "Смјатесја от јарости око моје, обетшах во всјех вразјех мојих."}, {"num": "8.", "text": "Отступите от мене вси дјелајушчији безаконије, јако услуша Господ глас плача мојего:"}, {"num": "9.", "text": "Услиша Господ мољеније моје, Господ молитву моју пријат."}, {"num": "10.", "text": "Да постидјатсја и смјатутсја вси врази моји, да возвратјатсја, и устидјатсја зјело вскорје. Слава:"}]}, "7": {"number": 7, "title": "Псалом 7. (7)", "subtitle": "", "verses": [{"num": "1.", "text": "Господи Боже мој, на Тја уповах, спаси мја от всјех гоњашчих мја, и избави мја."}, {"num": "2.", "text": "Да не когда похитит јако лев душу моју, не сушчу избављајушчу, ниже спасајушчу."}, {"num": "3.", "text": "Господи Боже мој, ашче сотворих сије, ашче јест неправда на руку мојеју:"}, {"num": "4.", "text": "Ашче воздах воздајушчим ми зла, да отпаду убо от враг мојих тошч."}, {"num": "5.", "text": "Да поженет убо враг душу моју, и да постигнет, и поперет в земљу живот мој, и славу моју в перст вселит."}, {"num": "6.", "text": "Воскресни Господи гњевом Твојим, вознесисја в концах враг Твојих, и востани Господи Боже мој повељенијем, имже заповједал јеси."}, {"num": "7.", "text": "И сонм људеј обидет Тја: и о том на висоту обратисја."}, {"num": "8.", "text": "Господ судит људем: суди ми Господи по правдје мојеј, и по незлобје мојеј на мја."}, {"num": "9.", "text": "Да скончајетсја злоба грјешних, и исправиши праведнаго, испитајај сердца и утроби Боже праведно."}, {"num": "10.", "text": "Помошч моја от Бога, спасајушчаго правија сердцем."}, {"num": "11.", "text": "Бог судитељ праведен, и крјепок, и долготерпјељив, и не гњев наводјај на всјак ден."}, {"num": "12.", "text": "Ашче не обратитесја, оружије своје очистити, лук свој напрјаже, и уготова их:"}, {"num": "13.", "text": "И в њем уготова сосуди смертнија, стрјели своја сгарајемим содјела."}, {"num": "14.", "text": "Се боље неправдоју, зачат бољезан, и роди безаконије."}, {"num": "15.", "text": "Ров изри, и ископа их, и падет в јаму, јуже содјела."}, {"num": "16.", "text": "Обратитсја бољезан јего на главу јего, и на верх јего неправда јего снидет."}, {"num": "17.", "text": "Исповемсја Господеви по правдје Јего, и поју имени Господа Вишњаго."}]}, "8": {"number": 8, "title": "Псалом 8. (8)", "subtitle": "", "verses": [{"num": "1.", "text": "Господи Господ наш, јако чудно имја Твоје по всеј земљи, јако взатсја великољепије Твоје превише небес."}, {"num": "2.", "text": "Из уст младенец и сушчих совершил јеси хвалу, враг Твојих ради, јеже разрушити врага и местника."}, {"num": "3.", "text": "Јако узрју небеса, дјела перст Твојих, луну и звјезди, јако Ти основал јеси."}, {"num": "4.", "text": "Что јест человјек, јако помниши јего, или син человјеч, јако посјешчајеши јего;"}, {"num": "5.", "text": "Умалил јеси јего малим чим от ангел, славоју и честију вјенчал јеси јего:"}, {"num": "6.", "text": "И поставил јеси јего над дјели руку Твојеју, всја покорил јеси под нозје јего:"}, {"num": "7.", "text": "Овци и воли всја, јешче же и скоти пољскија:"}, {"num": "8.", "text": "Птици небеснија, и риби морскија, преходјашчија стези морскија."}, {"num": "9.", "text": "Господи Господ наш, јако чудно имја Твоје по всеј земљи. Слава:"}]}, "9": {"number": 9, "title": "Псалом 9. (9)", "subtitle": "", "verses": [{"num": "1.", "text": "Исповјемсја Тебје Господи всјем сердцем мојим, повјем всја чудеса Твоја."}, {"num": "2.", "text": "Возвесељусја и возрадујусја о Тебје, поју имени Твојему, Вишњиј."}, {"num": "3.", "text": "Внегда возвратитисја врагу мојему вспјат, изнемогут, и погибнут от лица Твојего."}, {"num": "4.", "text": "Јако сотворил јеси суд мој, и прју моју: сјел јеси на престоље, судјај правду."}, {"num": "5.", "text": "Запретил јеси јазиком, и погибе нечестивиј, имја јего потребил јеси во вјек, и во вјек вјека."}, {"num": "6.", "text": "Врагу оскудјеша оружија в конец, и гради разрушил јеси, погибе памјат јего с шумом."}, {"num": "7.", "text": "И Господ во вјек пребивајет, уготова на суд престол свој."}, {"num": "8.", "text": "И Тој судити имат всељењеј в правду, судити имат људем в правотје."}, {"num": "9.", "text": "И бист Господ прибјежишче убогом, помошчник во благовременијих в скорбех."}, {"num": "10.", "text": "И да уповајут на Тја знајушчији имја Твоје, јако не оставил јеси взискајушчих Тја Господи."}, {"num": "11.", "text": "Појте Господеви, живушчему в Сиоње: возвјестите во јазицјех начинанија Јего:"}, {"num": "12.", "text": "Јако взискајај крови их помјану, не заби званија убогих."}, {"num": "13.", "text": "Помилуј мја Госполи, вижд смиреније моје от враг мојих, возносјај мја от врат смертних."}, {"num": "14.", "text": "Јако да возвјешчу всја хвали Твоја во вратјех дшчере Сиони: возрадујемсја о спасенији Твојем."}, {"num": "15.", "text": "Угљебоша јазици в пагубје, јуже сотвориша: в сјети сеј, јуже скриша, увјазе нога их."}, {"num": "16.", "text": "Знајем јест Господ судби творјај, в дјељех руку својеју увјазе грјешник."}, {"num": "17.", "text": "Да возвратјатсја грјешници во ад: вси јазици забивајушчији Бога."}, {"num": "18.", "text": "Јако не до конца забвен будет нишчиј, терпјеније убогих не погибнет до конца."}, {"num": "19.", "text": "Воскресни Господи, да не крјепитсја человјек, да судјатсја јазици пред Тобоју."}, {"num": "20.", "text": "Постави Господи законоположитеља над њими, да разумјејут јазици, јако человјеци сут."}, {"num": "21.", "text": "Вскују Господи отстоја далече, презирајеши во благовременијих в скорбех;"}, {"num": "22.", "text": "Внегда гордитисја нечестивому, возгарајетсја нишчији: увјазајут в совјетјех, јаже помишљајут."}, {"num": "23.", "text": "Јако хвалим јест грјешниј в похотех души својеја, и обидјај благословим јест."}, {"num": "24.", "text": "Раздражи Господа грјешниј, по множеству гњева својего не взишчет: њест Бога пред њим."}, {"num": "25.", "text": "Оскверњајутсја путије јего на всјакоје времја: отемљутсја судби Твоја от лица јего, всјеми враги својими обладајет."}, {"num": "26.", "text": "Рече бо в сердцје својем: не подвижусја от рода в род без зла."}, {"num": "27.", "text": "Јегоже кљатви уста јего полна сут, и горести и лести: под јазиком јего труд и бољезан."}, {"num": "28.", "text": "Присједит в ловитељствје с богатими в тајних, јеже убити неповинаго: очи јего на нишчаго призирајетје."}, {"num": "29.", "text": "Ловит в тајње, јако лев во оградје својеј: ловит, јеже восхитити нишчаго, восхитити нишчаго внегда привлешчи их."}, {"num": "30.", "text": "В сјети својеј смирит јего: преклонитсја и падет, внегда јему обладати убогими."}, {"num": "31.", "text": "Рече бо в сердцје својем: заби Бог, отврати лице своје, да не видит до конца."}, {"num": "32.", "text": "Воскресни Господи Боже мој, да вознесетсја рука Твоја, не забуди убогих Твојих до конца."}, {"num": "33.", "text": "Чесо ради прогњева нечестивиј Бога; рече бо в сердцје својем: не взишчет."}, {"num": "34.", "text": "Видиши, јако Ти бољезан и јарост смотрајеши, да предат будет в руцје Твоји: Тебје остављен јест нишчиј, сиру Ти буди помошчник."}, {"num": "35.", "text": "Сокруши мишцу грјешному и лукавому: взишчетсја грјех јего, и не обрјашчетсја."}, {"num": "36.", "text": "Господ Цар во вјек и во вјек вјека: погибнете јазици от земљи Јего."}, {"num": "37.", "text": "Желаније убогих услишал јеси Господи, уготованије сердца их вњат ухо Твоје."}, {"num": "38.", "text": "Суди сиру и смирену, да не приложит ктому величатисја человјек на земљи."}]}, "10": {"number": 10, "title": "Псалом 10. (10)", "subtitle": "", "verses": [{"num": "1.", "text": "На Господа уповах, како речет души мојеј: превитај по горам јако птица;"}, {"num": "2.", "text": "Јако се грјешници наљакоша лук, уготоваша стрјели в туље, сострељати во мрацје правија сердцем."}, {"num": "3.", "text": "Зане јаже ти совершил јеси, они разрушиша: праведник же что сотвори; Господ во храмје свјатјем својем."}, {"num": "4.", "text": "Господ, на небеси престол Јего: очи Јего на нишчаго призирајетје, вјежди Јего испитајет сини человјеческија."}, {"num": "5.", "text": "Господ испитајет праведнаго и нечестиваго: љубјај же неправду, ненавидит своју душу."}, {"num": "6.", "text": "Одождит на грјешники сјети, огањ и жупел, и дух бурен, част чаши их."}, {"num": "7.", "text": "Јако праведен Господ, и правди возљуби, правоти видје лице Јего. Слава:"}]}, "11": {"number": 11, "title": "Псалом 11. (11)", "subtitle": "", "verses": [{"num": "1.", "text": "Спаси мја Господи, јако оскудје преподобниј, јако умалишасја истини от синов человјеческих."}, {"num": "2.", "text": "Сујетнаја глагоља кијждо ко искренему својему: устње лестивија в сердцје, и в сердцје глагољаша злаја."}, {"num": "3.", "text": "Потребит Господ всја устни лестивија, јазик велерјечивиј,"}, {"num": "4.", "text": "Рекшија: јазик наш возвеличим, устни нашја при нас сут: кто нам Господ јест;"}, {"num": "5.", "text": "Страсти ради нишчих, и воздиханија убогих, ниње воскресну, глагољет Господ: положусја во спасеније, не обињусја о њем."}, {"num": "6.", "text": "Словеса Господња, словеса чиста, сребро разжежено, искушено земљи, очишчено седмерицеју."}, {"num": "7.", "text": "Ти Господи сохраниши ни, и собљудеши ни от рода сего и во вјек."}, {"num": "8.", "text": "Окрест нечестивији ходјат: по висотје Твојеј умножил јеси сини человјеческија."}]}, "12": {"number": 12, "title": "Псалом 12. (12)", "subtitle": "", "verses": [{"num": "1.", "text": "Докоље Господи забудеши мја до конца; докоље отврашчајеши лице Твоје от мене;"}, {"num": "2.", "text": "Докоље положу совјети в души мојеј, бољезни в сердцје мојем ден и ношч; докоље вознесетсја враг мој на мја;"}, {"num": "3.", "text": "Призри, услиши мја Господи Боже мој, просвјети очи моји, да не когда усну в смерт."}, {"num": "4.", "text": "Да не когда речет враг мој: укрјепихсја на њего."}, {"num": "5.", "text": "Стужајушчији ми возрадујутсја, ашче подвижусја."}, {"num": "6.", "text": "Аз же на милост Твоју уповах: возрадујутсја сердце моје о спасенији Твојем: воспоју Господеви благодјејавшему мње, и поју имени Господа Вишњаго."}]}, "13": {"number": 13, "title": "Псалом 13. (13)", "subtitle": "", "verses": [{"num": "1.", "text": "Рече безумен в сердцје својем: њест Бог. Растљеша и омерзишасја в начинанијих: њест творјај благостињу."}, {"num": "2.", "text": "Господ с небесе приниче на сини человјеческија, видјети, ашче јест разумјевајај, или взискајај Бога."}, {"num": "3.", "text": "Вси уклонишасја, вкупје некључими биша: њест творјај благостињу, њест до јединаго."}, {"num": "4.", "text": "Ни ли уразумјејут вси дјелајушчији безаконије, снједајушчији људи моја в снјед хљеба; Господа не призваша:"}, {"num": "5.", "text": "Тамо убојашасја страха, идјеже не бје страх, јако Господ в родје праведних."}, {"num": "6.", "text": "Совјет нишчаго посрамисте, Господ же упованије јего јест."}, {"num": "7.", "text": "Кто даст от Сиона спасеније Израиљево."}, {"num": "8.", "text": "Внегда возвратити Господ пљененије људеј својих, возрадујетсја Јаков, и возвеселитсја Израиљ. Слава:"}]}, "14": {"number": 14, "title": "Псалом 14. (14)", "subtitle": "", "verses": [{"num": "1.", "text": "Господи, кто обитајет в жилишчи Твојем; или кто вселитсја во свјатују гору Твоју;"}, {"num": "2.", "text": "Ходјај непорочен, и дјелајај правду, глагољај истину в сердцје својем:"}, {"num": "3.", "text": "Иже не улести јазиком својим, и не сотвори искрснему својему зла, и поношенија не пријат на ближњија своја."}, {"num": "4.", "text": "Уничижен јест пред њим лукавнујај, бојашчијажесја Господа славит; кленијсја искренему својему, и не отметајасја."}, {"num": "5.", "text": "Сребра својего не даде в лихву, и мазди на неповининих не пријат: творјај сија не подвижитсја во вјек."}]}, "15": {"number": 15, "title": "Псалом 15. (15)", "subtitle": "", "verses": [{"num": "1.", "text": "Сохрани мја Господи, јако на Тја уповах."}, {"num": "2.", "text": "Рјех Господеви: Господ мој јеси Ти, јако благих мојих не требујеши."}, {"num": "3.", "text": "Свјатим иже сут на земљи Јего, удиви Господ всја хотјенија своја в њих."}, {"num": "4.", "text": "Умножишасја немошчи их, по сих ускориша, не соберу собори их от кровеј, ни помјану же имен их устнама мојима."}, {"num": "5.", "text": "Господ част достојанија мојего, и чаши мојеја: Ти јеси устројајај достојаније моје мње."}, {"num": "6.", "text": "Ужја нападоша ми в державних мојих: ибо достојаније моје державно јест мње."}, {"num": "7.", "text": "Благословљу Господа вразумившаго мја: јешче же и до ношчи наказаша мја утроби моја."}, {"num": "8.", "text": "Предзрјех Господа предомноју вину, јако одеснују мене јест, да не подвижусја."}, {"num": "9.", "text": "Сего ради возвеселисја сердце моје, и возрадовасја јазик мој: јешче же и плот моја вселитсја на упованији."}, {"num": "10.", "text": "Јако не оставиши душу моју во адје, ниже даси преподобному Твојему видјети истљенија."}, {"num": "11.", "text": "Сказал ми јеси пути живота: исполниши мја веселија с лицем Твојим: красота в десницје Твојеј в конец."}]}, "16": {"number": 16, "title": "Псалом 16. (16)", "subtitle": "", "verses": [{"num": "1.", "text": "Услиши Господи правду моју, вонми мољенију мојему, внуши молитву моју не во устнах лестивих."}, {"num": "2.", "text": "От лица Твојего судба моја изидет: очи моји да видита правоти."}, {"num": "3.", "text": "Искусил јеси сердце моје, посјетил јеси ношчију: искусил мја јеси, и не обрјетесја во мње неправда."}, {"num": "4.", "text": "Јако да не возглагољут уста моја дјел человјеческих, за словеса устен Твојих аз сохраних пути жестоки."}, {"num": "5.", "text": "Соверши стопи моја во стезјах Твојих, да не подвижутсја стопи моја."}, {"num": "6.", "text": "Аз возвах, јако услишал мја јеси Боже: приклони ухо Твоје мње, и услиши глаголи моја."}, {"num": "7.", "text": "Удиви милости Твоја, спасајај уповајушчија на Тја, от противјашчихсја десницје Твојеј:"}, {"num": "8.", "text": "Сохрани мја Господи јако зјеницу ока: в кровје крилу Твојеју покријеши мја."}, {"num": "9.", "text": "От лица нечестивих острастших мја. Врази моји душу моју одержаша,"}, {"num": "10.", "text": "Тук свој затвориша: уста их глагољаша гордињу."}, {"num": "11.", "text": "Изгоњашчији мја ниње обидоша мја, очи своји возложиша уклонити на земљу."}, {"num": "12.", "text": "Објаша мја јако лев готов на лов, и јако скимен, обитајај в тајних."}, {"num": "13.", "text": "Воскресни Господи, предвари ја, и запни им: избави душу моју от нечестиваго, оружије Твоје, от враг руки Твојеја."}, {"num": "14.", "text": "Господи, от малих от земљи раздјели ја в животје их, и сокровенијих Твојих исполнисја чрево их: наситишасја синов, и оставиша останки младенцем својим."}, {"num": "15.", "text": "Аз же правдоју јављусја лицу Твојему, насишчусја, внегда јавитимисја славје Твојеј. Слава:"}]}, "17": {"number": 17, "title": "Псалом 17. (17)", "subtitle": "", "verses": [{"num": "1.", "text": "Возљубљу Тја Господи, крјепосте моја:"}, {"num": "2.", "text": "Господ утвержденије моје, и прибјежишче моје, и избавитељ мој, Бог мој, помошчник мој, и уповају на Њего: зашчититељ мој, и рог спасенија мојего, и заступник мој."}, {"num": "3.", "text": "Хваља призову Господа, и от враг мојих спасусја."}, {"num": "4.", "text": "Одержаша мја бољезни смертнија, и потоци безаконија смјатоша мја:"}, {"num": "5.", "text": "Бољезни адови обидоша мја, предвариша мја сјети смертнија."}, {"num": "6.", "text": "И внегда скорбјети ми, призвах Господа, и к Богу мојему возвах: услиша от храма свјатаго својего глас мој, и вопл мој пред Њим внидет во уши Јего."}, {"num": "7.", "text": "И подвижесја, и трепетна бист земља, и основанија гора смјатошасја, и подвигошасја, јако прогњевасја на мја Бог."}, {"num": "8.", "text": "Взиде дим гњевом Јего, и огањ от лица Јего воспламенитсја, угљије возгорјесја от Њего."}, {"num": "9.", "text": "И приклони небеса, и сниде: и мрак под ногама Јего."}, {"num": "10.", "text": "И взиде на херувими, и летје, летје на крилу вјетрењу."}, {"num": "11.", "text": "И положи таму закров свој, окрест Јего сељеније Јего, темна вода во облацјех воздушних."}, {"num": "12.", "text": "От облистанија пре Њим облаци проидоша, град и угљије огњеноје."}, {"num": "13.", "text": "И возгремје с небесе Господ, и Вишњиј даде глас свој."}, {"num": "14.", "text": "Ниспосла стрјели, и разгна ја, и молнији умножи, и смјате ја."}, {"num": "15.", "text": "И јавишасја источници водни и откришасја основанија всељенија от запрешченија Твојего Господи, от дохновенија Духа гњева Твојего."}, {"num": "16.", "text": "Ниспосла с висоти, и пријат мја, воспријат мја от вода многих."}, {"num": "17.", "text": "Избавит мја от врагов мојих силних, и от ненавидјашчих мја: јако утвердишасја паче мене."}, {"num": "18.", "text": "Предвариша мја в ден озлобљенија мојего: И бист Господ утвержденије моје."}, {"num": "19.", "text": "И изведе мја на широту: избавит мја, јако восхотје мја."}, {"num": "20.", "text": "И воздаст ми Господ по правдје мојеј, и по чистотје руку мојеју воздаст ми:"}, {"num": "21.", "text": "Јако сохраних пути Господњи, и не нечествовах от Бога мојего."}, {"num": "22.", "text": "Јако всја судби Јего предмноју, и оправданија Јего не отступиша от мене."}, {"num": "23.", "text": "И буду непорочен с Њим, и сохрањусја от безаконија мојего."}, {"num": "24.", "text": "И воздаст ми Господ по правдје мојеј, и по чистотје руку мојеју, пред очима Јего."}, {"num": "25.", "text": "С преподобним преподобен будеши, и с мужем неповиним неповинен будеши."}, {"num": "26.", "text": "И со избраним избран будеши, и со строптивим развратишисја."}, {"num": "27.", "text": "Јако Ти људи смиренија спасеши, и очи гордих смириши."}, {"num": "28.", "text": "Јако Ти просвјетиши свјетилник мој Господи: Боже мој, просвјетиши таму моју."}, {"num": "29.", "text": "Јако Тобоју избављусја от искушенија, и Богом мојим прејду стјену."}, {"num": "30.", "text": "Бог мој, непорочен пут Јего: словоса Господња разжежена: зашчититељ јест всјех уповајушчих на Њего."}, {"num": "31.", "text": "Јако кто Бог, развје Господа; или кто Бог, развје Бога нашего;"}, {"num": "32.", "text": "Бог препојасујај мја силоју, и положи непорочен пут мој."}, {"num": "33.", "text": "Совершајај нозје моји јако јелени, и на високих постављајај мја."}, {"num": "34.", "text": "Научајај руцје моји на бран, и положил јеси лук мједјан мишца моја."}, {"num": "35.", "text": "И дал ми јеси зашчишченије спасенија, и десница Твоја воспријат мја: и наказаније Твоје исправит мја в конец, и наказаније Твоје то мја научит."}, {"num": "36.", "text": "Уширил јеси стопи моја подомноју, и не изнемогостје плесње моји."}, {"num": "37.", "text": "Пожену враги моја, и постигну ја, и не возврашчусја, дондеже скончајутсја."}, {"num": "38.", "text": "Оскорбљу их, и не возмогут стати, падут под ногама мојима."}, {"num": "39.", "text": "И препојасал мја јеси силоју на бран, спјал јеси всја востајушчија на мја под мја."}, {"num": "40.", "text": "И врагов мојих дал ми јеси хребет, и ненавидјашчија мја погребил јеси."}, {"num": "41.", "text": "Возваша, и не бје спасајај: ко Господу, и не услиша их."}, {"num": "42.", "text": "И истњу ја јако прах пред лицем вјетра, јако бреније путеј поглажду ја."}, {"num": "43.", "text": "Избавиши мја от прерјеканија људеј, поставиши мја во главу јазиков, људије, ихже не вједјех, работаша ми."}, {"num": "44.", "text": "В слух уха послушаша мја: синове чуждији солгаша ми."}, {"num": "45.", "text": "Синове чуждији обетшаша, и охромоша от стез својих."}, {"num": "46.", "text": "Жив Господ, и благословен Бог, и да вознесетсја Бог спасенија мојего:"}, {"num": "47.", "text": "Бог дајај отмишченије мње, и покоривиј људи под мја."}, {"num": "48.", "text": "Избавитељ мој от враг мојих гњевљивих, от востајушчих на мја вознесеши мја, от мужа неправедна избавиши мја."}, {"num": "49.", "text": "Сего ради исповјемсја Тебје во јазицјех, Господи, и имени Твојему поју."}, {"num": "50.", "text": "Величајај спасенија царева, и творјај милост христу својему Давиду, и сјемени јего до вјека. Слава:"}]}, "18": {"number": 18, "title": "Псалом 18. (18)", "subtitle": "", "verses": [{"num": "1.", "text": "Небеса повједајут славу Божију, твореније же руку Јего возвјешчајет тверд."}, {"num": "2.", "text": "Ден дни отригајет глагол, и ношч ношчи возвјешчајет разум."}, {"num": "3.", "text": "Не сут рјечи, ниже словеса, ихже не слишатсја гласи их."}, {"num": "4.", "text": "Во всју земљу изиде вјешчаније их, и в конци всељенија глаголи их, во солнцје положи сељеније своје:"}, {"num": "5.", "text": "И тој јако жених исходјај от чертога својего, возрадујетсја јако исполин тешчи пут."}, {"num": "6.", "text": "От краја небесе изход јего, и срјетеније јего до краја небесе: и њест, иже укријетсја теплоти јего."}, {"num": "7.", "text": "Закон Господењ непорочен, обрашчајај души: свидјетељство Господње вјерно, умудрјајушчеје младенци."}, {"num": "8.", "text": "Оправданија Господња права, весељашчаја сердце: заповјед Господња свјетла, просвјешчајушчаја очи."}, {"num": "9.", "text": "Страх Господењ чист, пребивајај во вјек вјека: судби Господњи истини, оправдани вкупје."}, {"num": "10.", "text": "Возждељени паче злата, и камене честна многа, и слаждша паче меда и сота."}, {"num": "11.", "text": "Ибо раб Твој хранит ја, внегда сохранити ја, воздајаније много."}, {"num": "12.", "text": "Грјехопаденија кто разумјет; от тајних мојих очисти мја."}, {"num": "13.", "text": "И от чуждих пошчади раба Твојего: ашче не обладајет мноју, тогда непорочен буду, и очишчусја от грјеха велика."}, {"num": "14.", "text": "И будут во благовољеније словеса уст мојих, и поученије сердца мојего пред Тобоју вину, Господи помошчниче мој, и избавитељу мој."}]}, "19": {"number": 19, "title": "Псалом 19. (19)", "subtitle": "", "verses": [{"num": "1.", "text": "Услишит тја Господ в ден печали, зашчитит тја имја Бога Јаковља."}, {"num": "2.", "text": "Послет ти помошч от свјатаго, и от Сиона заступит тја."}, {"num": "3.", "text": "Помјанет всјаку жертву твоју, и всесожеженије твоје тучно буди."}, {"num": "4.", "text": "Даст ти Господ по сердцу твојему, и вес совјет твој исполнит."}, {"num": "5.", "text": "Возрадујемсја о спасенији Твојем, и во имја Господа Бога нашего возвеличимсја, исполнит Господ всја прошенија твоја."}, {"num": "6.", "text": "Ниње познах, јако спасе Господ Христа својего: услишит Јего с небесе свјатаго својего: в силах спасеније десници Јего."}, {"num": "7.", "text": "Сији на колесницах, и сији на коњех: ми же во имја Господа Бога нашего призовем."}, {"num": "8.", "text": "Тији спјати биша, и падоша, ми же востахом, и исправихомсја."}, {"num": "9.", "text": "Господи, спаси царја, и услиши ни, в оњже ашче ден призовем Тја."}]}, "20": {"number": 20, "title": "Псалом 20. (20)", "subtitle": "", "verses": [{"num": "1.", "text": "Господи, силоју Твојеју возвеселитсја цар, и о спасенији Твојем возрадујетсја зјело."}, {"num": "2.", "text": "Желаније сердца јего дал јеси јему, и хотјенија устну јего њеси лишил јего."}, {"num": "3.", "text": "Јако предварил јеси јего благословенијем благостињим, положил јеси на главје јего вјенец от камене честна."}, {"num": "4.", "text": "Живота просил јест у Тебе, и дал јеси јему долготу дниј во вјек вјека."}, {"num": "5.", "text": "Велија слава јего спасенијем Твојим: славу и велељепије возложиши на њего."}, {"num": "6.", "text": "Јако даси јему благословеније во вјек вјека, возвеселиши јего радостију с лицем Твојим."}, {"num": "7.", "text": "Јако цар уповајет па Господа: и милостију Вишњаго не подвижитсја."}, {"num": "8.", "text": "Да обрјашчетсја рука Твоја всјем врагом Твојим, десница Твоја да обрјашчет всја ненавидјашчија Тебе."}, {"num": "9.", "text": "Јако положиши их јако пешч огњенују, во времја лица твојего: Господ гњевом својим смјатет ја, и снјест их огањ."}, {"num": "10.", "text": "Плод их от земљи погубиши, и сјемја их от синов человјеческих."}, {"num": "11.", "text": "Јако уклониша на Тја злаја, помислиша совјети, ихже не возмогут составити."}, {"num": "12.", "text": "Јако положиши ја хребет, во избитцјех Твојих уготовиши лице их."}, {"num": "13.", "text": "Вознесисја Господи силоју Твојеју: воспојем и појем сили Твоја. Слава:"}]}, "21": {"number": 21, "title": "Псалом 21. (21)", "subtitle": "", "verses": [{"num": "1.", "text": "Боже, Боже мој, вонми ми, вскују оставил Мја јеси; далече от спасенија Мојего словеса грјехопадениј Мојих."}, {"num": "2.", "text": "Боже Мој, возову во дни, и не услишиши, и в ношчи, и не в безумије Мње."}, {"num": "3.", "text": "Ти же во свјатјем живеши, хвало Израиљева."}, {"num": "4.", "text": "На Тја уповаша оци наши: уповаша, и не постидјешасја."}, {"num": "5.", "text": "К Тебје возваша, и спасошасја, на Тја уповаша, и не постидјешесја."}, {"num": "6.", "text": "Аз же јесам черв, а не человјек, поношеније человјеков и уничиженије људеј."}, {"num": "7.", "text": "Вси видјашчији Мја поругашамисја, глаголаша устнами, покиваша главоју:"}, {"num": "8.", "text": "Упова на Господа, да избавит Јего, да спасет Јего, јако хошчет Јего."}, {"num": "9.", "text": "Јако Ти јеси исторгиј Мја из чрева, упованије Моје от сосцу матере Мојеја:"}, {"num": "10.", "text": "К Тебје привержен јесам от ложесан, от чрева матере Мојеја Бог Мој јеси Ти."}, {"num": "11.", "text": "Да не отступиши от Мене, јако скорб близ, јако њест помагајај Ми."}, {"num": "12.", "text": "Обидоша Мја телци мнози, јунци тучнији одержаша Мја:"}, {"num": "13.", "text": "Отверзоша на Мја уста своја, јако лев восхишчајај и рикајај."}, {"num": "14.", "text": "Јако вода излијасја, и разсипашасја всја кости Моја: бист сердце Моје јако восак тајај посредје чрева Мојего."}, {"num": "15.", "text": "Изсше јако скудел крјепост Моја, и јазик Мој прилпе гортани Мојему, и в перст смерти свел Мја јеси."}, {"num": "16.", "text": "Јако обидоша Мја пси мнози, сонм лукавих одержаша Мја: ископаша руцје Моји и нозје Моји:"}, {"num": "17.", "text": "Исчетоша всја кости Моја: Ти же смотриша, и презрјеша Мја."}, {"num": "18.", "text": "Раздјелиша ризи Моја себје, и о одежди Мојеј меташа жребиј."}, {"num": "19.", "text": "Ти же Господи не удаљи помошч Твоју от Мене, на заступљеније Моје вонми."}, {"num": "20.", "text": "Избави от оружија душу Моју, и из руки песији јединороднују Моју:"}, {"num": "21.", "text": "Спаси Мја от уст лавових, и от рог јединорож смиреније Моје."}, {"num": "22.", "text": "Повјем имја Твоја братији Мојеј, посредје церкве воспоју Тја."}, {"num": "23.", "text": "Бојашчијисја Господа, восхвалите Јего, все сјемја Јаковље прославите Јего, да убојитсја же от Њего все сјемја Израиљево:"}, {"num": "24.", "text": "Јако не уничижи, ниже негодова молитви нишчаго, ниже отврати лице своје от мене, и јегда возвах к Њему, услиши мја."}, {"num": "25.", "text": "От Тебе похвала моја, в церкви велицјеј исповемсја Тебје, молитви моја воздам пред бојашчимсја Јего."}, {"num": "26.", "text": "Јадјат убозији, и наситјатсја, и восхваљат Господа взискајушчији Јего: жива будут сердца их во вјек вјека."}, {"num": "27.", "text": "Помјанутсја, и обратјатсја ко Господу вси конци земљи, и поклоњатсја пред Њим всја отечествија јазик."}, {"num": "28.", "text": "Јако Господње јест царствије, и Тој обладајет јазики."}, {"num": "29.", "text": "Јадоша, и поклонишасја вси тучнији земљи: пред Њим припадајут вси низходјашчији в земљу, и душа моја Тому живет."}, {"num": "30.", "text": "И сјемја моје поработајет Јему: возвјестит Господеви род грјадушчиј:"}, {"num": "31.", "text": "И возвјестјат правду Јего људем рождшимсја, јаже сотвори Господ."}]}, "22": {"number": 22, "title": "Псалом 22. (22)", "subtitle": "", "verses": [{"num": "1.", "text": "Господ пасет мја, и ничтоже мја лишит."}, {"num": "2.", "text": "На мјестје злачње, тамо всели мја, на водје покојње воспита мја."}, {"num": "3.", "text": "Душу моју обрати, настави мја на стези правди, имене ради Својего."}, {"num": "4.", "text": "Ашче бо и појду посредје сјени смертнија, не убојусја зла, јако Ти со мноју јеси: жезал Твој, и палица Твоја, та мја утјешиста."}, {"num": "5.", "text": "Уготовал јеси предомноју трапезу, сопротив стужајушчим мње: умастил јеси јелејем главу моју, и чаша Твоја упојавајушчи мја јако державна."}, {"num": "6.", "text": "И милост Твоја поженет мја всја дни живота мојего, и јеже вселитимисја в дом Господењ в долготу дниј."}]}, "23": {"number": 23, "title": "Псалом 23. (23)", "subtitle": "", "verses": [{"num": "1.", "text": "Господња земља, и исполњеније јеја, всељенаја, и вси живушчији на њеј."}, {"num": "2.", "text": "Тој на морах основал ју јест, и на рјеках уготовал ју јест:"}, {"num": "3.", "text": "Кто взидет на гору Господњу: или кто станет на мјестје свјатјем Јего."}, {"num": "4.", "text": "Неповинен рукама, и чист сердцем, иже не пријат всује душу своју, и не кљатсја лестију искренему својему."}, {"num": "5.", "text": "Сеј пријимет благословеније от Господа, и милостињу от Бога Спаса својего."}, {"num": "6.", "text": "Сеј род ишчушчих Господа, ишчушчих лице Бога Јаковља."}, {"num": "7.", "text": "Возмите врата књази ваша, и возмитесја врата вјечнаја: и внидет Цар слави."}, {"num": "8.", "text": "Кто јест сеј Цар слави: Господ крјепок и силен, Господ силен в брани."}, {"num": "9.", "text": "Возмите врата књази ваша, и возмитесја врата вјечнаја: и внидет Цар слави."}, {"num": "10.", "text": "Кто јест сеј Цар слави: Господ сил, Тој јест Цар слави. Слава:"}]}, "24": {"number": 24, "title": "Псалом 24. (24)", "subtitle": "", "verses": [{"num": "1.", "text": "К тебје Господи воздвигох душу моју, Боже мој, на Тја уповах, да не постижусја во вјек, ниже да посмјејутмисја врази моји:"}, {"num": "2.", "text": "Ибо вси терпјашчији Тја, не постидјатсја."}, {"num": "3.", "text": "Да постидјатсја безаконујушчији вотшче."}, {"num": "4.", "text": "Пути Твоја Господи скажи ми, и стезјам Твојим научи мја."}, {"num": "5.", "text": "Настави мја на истину Твоју, и научи мја, јако Ти јеси Бог спас мој, и Тебе терпјех вес ден."}, {"num": "6.", "text": "Помјани шчедроти Твоја Господи, и милости Твоја, јако от вјека сут."}, {"num": "7.", "text": "Грјех јуности мојеја, и невједјенија мојего не помјани: по милости Твојеј помјани мја Ти, ради благости Твојеја Господи."}, {"num": "8.", "text": "Благ и прав Господ, сего ради законоположит согрјешајушчим на пути."}, {"num": "9.", "text": "Наставит кроткија на суд, научит кроткија путем својим."}, {"num": "10.", "text": "Вси путије Господњи милост и истина, взискајушчим завјета Јего, и свидјенија Јего."}, {"num": "11.", "text": "Ради имене Твојего Господи, и очисти грјех мој: мног бо јест."}, {"num": "12.", "text": "Кто јест человјек бојајсја Господа; законоположит јему на пути, јегоже изволи."}, {"num": "13.", "text": "Душа јего во благих водворитсја, и сјемја јего насљедит земљу."}, {"num": "14.", "text": "Держава Господ бојашчихсја Јего, и завјет Јего јавит им."}, {"num": "15.", "text": "Очи моји вину ко Господу, јако Тој исторгнет от сјети нозје моји."}, {"num": "16.", "text": "Призри на мја, и помилуј мја, јако јединород и нишч јесам аз."}, {"num": "17.", "text": "Скорби сердца мојего умножишасја, от нужд мојих изведи мја."}, {"num": "18.", "text": "Вижд смиреније моје, и труд мој, и остави всја грјехи моја."}, {"num": "19.", "text": "Вижд враги моја, јако умножишасја, и ненавидјенијем неправедним возненавидјеша мја."}, {"num": "20.", "text": "Сохрани душу моју, и избави мја, да не постижусја, јако уповах на Тја."}, {"num": "21.", "text": "Незлобивији и правији приљепљахусја мње, јако потерпјех Тја Господи."}, {"num": "22.", "text": "Избави Боже Израиља от всјех скорбеј јего."}]}, "25": {"number": 25, "title": "Псалом 25. (25)", "subtitle": "", "verses": [{"num": "1.", "text": "Суди ми Господи, јако аз незлобоју мојеју ходих: и на Господа уповаја не изнемогу."}, {"num": "2.", "text": "Искуси мја Господи, и испитај мја, разжези утроби моја и сердце моје."}, {"num": "3.", "text": "Јако милост Твоја пред очима мојим јест, и благоугодих во истиње Твојеј."}, {"num": "4.", "text": "Не сједох со сонмом сујетним, и со законопреступними не вниду."}, {"num": "5.", "text": "Возненавидјех церков лукавнујушчих, и с нечестивими не сјаду."}, {"num": "6.", "text": "Умију в неповинених руцје моји, и обиду жертвеник Твој Господи."}, {"num": "7.", "text": "Јеже услишати ми глас хвали Твојеја, и повједати всја чудеса Твоја."}, {"num": "8.", "text": "Господи, возљубих благољепије дому Твојего, и мјесто сељенија слави Твојеја."}, {"num": "9.", "text": "Да не погубиши с нечестивими душу моју, и с мужи кровеј живот мој."}, {"num": "10.", "text": "Ихже в руку безаконија, десница их исполнисја мазди."}, {"num": "11.", "text": "Аз же незлобоју мојеју ходих, избави мја Господи и помилуј мја."}, {"num": "12.", "text": "Нога моја ста на правотје: в церквах благословљу Тја Господи."}]}, "26": {"number": 26, "title": "Псалом 26. (26)", "subtitle": "", "verses": [{"num": "1.", "text": "Господ просвјешченије моје и Спаситељ мој, кого убојусја; Господ зашчититељ живота мојего, от кого устрашусја."}, {"num": "2.", "text": "Внегда приближатисја на мја злобујушчим, јеже снјести плоти моја, оскорбљајушчији мја и врази моји, тији изнемогоша и падоша."}, {"num": "3.", "text": "Ашче ополчитсја на мја полк, не убојитсја сердце моје: ашче востанет на мја бран, на Њего аз уповају."}, {"num": "4.", "text": "Једино просих от Господа, то взишчу: јеже жити ми в дому Господњи всја дни живота мојего, зрјети ми красоту Господњу, и посјешчати храм свјатиј Јего."}, {"num": "5.", "text": "Јако скри мја в сељенији својем, в ден зол мојих, покри мја в тајње сељенија својего, на камен вознесе мја:"}, {"num": "6.", "text": "И ниње се вознесе главу моју на враги моја: обидох и пожрох в сељенији Јего жертву хваљенија и воскликновенија: поју и воспоју Господеви."}, {"num": "7.", "text": "Услиши Господи глас мој, имже возвах, помилуј мја, и услиши мја."}, {"num": "8.", "text": "Тебје рече сердце моје: Господа взишчу; взиска Тебе лице моје, лица Твојего Господи взишчу."}, {"num": "9.", "text": "Не отврати лица Твојего от мене, и не уклонисја гњевом от раба Твојего: помошчник мој буди, не отрини мене, и не остави мене Боже, Спаситељу мој:"}, {"num": "10.", "text": "Јако отец мој и мати моја остависта мја, Господ же воспријат мја."}, {"num": "11.", "text": "Законоположи ми Господи в пути Твојем, и настави мја на стезју правују враг мојих ради."}, {"num": "12.", "text": "Не предажд мене в души стужајушчих ми: јако восташа на мја свидјетеље неправеднији, и солга неправда себје."}, {"num": "13.", "text": "Вјерују видјети благаја Господња на земљи живих."}, {"num": "14.", "text": "Потерпи Господа, мужајсја, и да крјепитсја сердце твоје, и потерпи Господа. Слава:"}]}, "27": {"number": 27, "title": "Псалом 27. (27)", "subtitle": "", "verses": [{"num": "1.", "text": "К Тебје Господи возову, Боже мој, да не премолчиши от мене: да не когда премолчиши от мене, и уподобљусја низходјашчим в ров."}, {"num": "2.", "text": "Услиши Господи глас мољенија мојего, внегда молитимисја к Тебје, внегда воздјети ми руцје моји к храму свјатому Твојему."}, {"num": "3.", "text": "Не привлеци мене со грјешники, и с дјелајушчими неправду не погуби мене, глагољушчими мир с ближњими својими, злаја же в сердцах својих."}, {"num": "4.", "text": "Дажд им Господи, по дјелом их, и по лукавству начинаниј их, по дјелом руку их дажд им, воздажд воздајаније их им."}, {"num": "5.", "text": "Јако не разумјеша в дјела Господња, и в дјела руку Јего: разориши ја, и не созиждеши."}, {"num": "6.", "text": "Благословен Господ, јако услиша глас мољенија мојего."}, {"num": "7.", "text": "Господ помошчник мој, и зашчититељ мој: на Њего упова сердце моје, и поможе ми, и процвјете плот моја: и вољеју мојеју исповемсја Јему."}, {"num": "8.", "text": "Господ утвержденије људеј својих, и зашчититељ спасениј христа својего јест."}, {"num": "9.", "text": "Спаси људи Твоја, и благослови достојаније Твоје: и упаси ја, и возми ја до вјека."}]}, "28": {"number": 28, "title": "Псалом 28. (28)", "subtitle": "", "verses": [{"num": "1.", "text": "Принесите Господеви синове Божији, принесите Господеви сини овни, принесите Господеви славу и чест."}, {"num": "2.", "text": "Принесите Господеви славу имени Јего: поклонитесја Господеви во дворје свјатјем Јего."}, {"num": "3.", "text": "Глас Господењ на водах, Бог слави возгремје, Господ на водах многих."}, {"num": "4.", "text": "Глас Господењ в крјепости, глас Господењ в великољепији."}, {"num": "5.", "text": "Глас Господа, сокрушајушчаго кедри, и стријет Господ кедри Ливанскија."}, {"num": "6.", "text": "И истнит ја јако телца Ливанска, и возљубљениј јако син јединорож."}, {"num": "7.", "text": "Глас Господа, пресјецајушчаго пламен огња."}, {"num": "8.", "text": "Глас Господа, стрјасајушчаго пустињу: и стрјасет Господ пустињу Кадијскују."}, {"num": "9.", "text": "Глас Господењ свершајушчиј јелени, и откријет дубрави: и в храмје Јего всјакиј глагољет славу."}, {"num": "10.", "text": "Господ потоп насељајет, и сјадет Господ Цар во вјек."}, {"num": "11.", "text": "Господ крјепост људем својим дасе: Господ благословит људи своја миром."}]}, "29": {"number": 29, "title": "Псалом 29. (29)", "subtitle": "", "verses": [{"num": "1.", "text": "Вознесу Тја Господи, јако подјал мја јеси, и не возвеселил јеси врагов мојих о мње."}, {"num": "2.", "text": "Господи Боже мој, возвах к Тебје, и исцјелил мја јеси:"}, {"num": "3.", "text": "Господи возвел јеси от ада душу моју, спасал мја јеси от низходјашчих в ров."}, {"num": "4.", "text": "Појте Господеви преподобнији Јего, и исповједајте памјат свјатињи Јего."}, {"num": "5.", "text": "Јако гњев в јарости Јего, и жиног во вољи Јего: вечер водворитсја плач, и зајутра радост."}, {"num": "6.", "text": "Аз же рјех во обилији мојем: не подвижусја во вјек."}, {"num": "7.", "text": "Господи, вољеју Твојеју подажд добротје мојеј силу. Отвратил же јеси лице Твоје, и бих смушчен."}, {"num": "8.", "text": "К Тебје Господи возову, и к Богу мојему помољусја."}, {"num": "9.", "text": "Каја полза в крови мојеј, внегда сходити ми во истљеније; еда исповјестсја Тебје перст; или возвјестит истину Твоју;"}, {"num": "10.", "text": "Слиша Господ, и помилова мја: Господ бист помошчник мој."}, {"num": "11.", "text": "Обратил јеси плач мој в радост мње, растерзал јеси вретишче моје, и препојасал мја јеси веселијем:"}, {"num": "12.", "text": "Јако да воспојет Тебје слава моја, и не умиљусја, Господи Боже мој, во вјек исповјемсја Тебје. Слава:"}]}, "30": {"number": 30, "title": "Псалом 30. (30)", "subtitle": "", "verses": [{"num": "1.", "text": "На Тја Господи уповах, да не постижусја во вјек: правдоју Твојеју избави мја и изми мја."}, {"num": "2.", "text": "Приклони ко мње ухо Твоје, ускори изјати мја: буди ми в Бога зашчититеља, и в дом прибјежишча, јеже спасти мја."}, {"num": "3.", "text": "Јако держава моја, и прибјежишче моје јеси Ти, и имене Твојего ради наставиши мја, и препитајеши мја."}, {"num": "4.", "text": "Изведеши мја от сјети сеја, јуже скриша ми, јако Ти јеси зашчититељ мој Господи:"}, {"num": "5.", "text": "В руцје Твоји предложу дух мој: избавил мја јеси Господи Боже истини."}, {"num": "6.", "text": "Возненавидјел јеси храњашчија сујети вотшче: аз же на Господа уповах."}, {"num": "7.", "text": "Возрадујусја и возвеселисја о милости Твојеј, јако призрјел јеси на смиреније моје, спасал јеси от нужд душу моју:"}, {"num": "8.", "text": "И њеси мене затворил в руках вражијих, поставил јеси на прострање нозје моји."}, {"num": "9.", "text": "Помилуј мја Господи, јако скорбљу: сматесја јаростију око моје, душа моја, и утроба моја."}, {"num": "10.", "text": "Јако изчезе в бољезни живот мој, и љета моја во воздиханијих: изнеможе нишчетоју крјепост моја, и кости моја смјатошасја."}, {"num": "11.", "text": "От всјех враг мојих бих поношеније, и сосједом мојим зјело, и страх знајемим мојим: видјашчији мја воњ бјежаша от мене."}, {"num": "12.", "text": "Забвен бих, јако мертав от сердца: бих јако сосуд погубљен."}, {"num": "13.", "text": "Јако слишах гажденије многих живушчих окрест: внегда собратисја им вкупје на мја, пријати душу моју совјешчаша."}, {"num": "14.", "text": "Аз же на Тја Господи уповах, рјех: Ти јеси Бог мој."}, {"num": "15.", "text": "В руку Твојеју жребији моји: избави мја из руки враг мојих, и от гоњашчих мја."}, {"num": "16.", "text": "Просвјети лице Твоје на раба Твојего, спаси мја милостију Твојеју."}, {"num": "17.", "text": "Господи, да не постижусја, јако призвах Тја: да постидјатсја нечестивији, и снидут во ад."}, {"num": "18.", "text": "Нјеми да будут устни лестивија, глагољушчија на праведнаго безаконије, гордињеју и уничиженијем."}, {"num": "19.", "text": "Кољ многоје множество благости Твојеја Господи, јуже скрил јеси бојашчимсја Тебе, содјелал јеси уповајушчим на Тја, пред сини человјеческими."}, {"num": "20.", "text": "Скријеши их в тајње лица Твојего от мјатежа человјеческа, покријеши их в кровје от прерјеканија јазик."}, {"num": "21.", "text": "Благословен Господ, јако удиви милост своју во градје огражденија."}, {"num": "22.", "text": "Аз же рјех во изступљенији мојем: отвержен јесам от лица очију Твојеју: сего ради услишал јеси глас молитви мојеја, внегда возвах к Тебје."}, {"num": "23.", "text": "Возљубите Господа вси преподобнији Јего, јако истини взискајет Господ, и воздајет излише творјашчим гордињу."}, {"num": "24.", "text": "Мужајтесја, и да крјепитсја сердце ваше, вси уповајушчији на Господа."}]}, "31": {"number": 31, "title": "Псалом 31. (31)", "subtitle": "", "verses": [{"num": "1.", "text": "Блажени, ихже оставишасја безаконије, и ихже прикришасја грјеси."}, {"num": "2.", "text": "Блажен муж, јемуже не вмјенит Господ грјеха, ниже јест во устјех јего лест."}, {"num": "3.", "text": "Јако умолчах, обетшаша кости моја, от јеже звати ми вес ден:"}, {"num": "4.", "text": "Јако ден и ношч отјаготје на мње рука Твоја, возвратихсја на страст, јегда унзе ми терн."}, {"num": "5.", "text": "Безаконије моје познах, и грјеха мојего не покрих, рјех: исповјем на мја безаконије моје Господеви: и Ти оставил јеси нечестије сердца мојего."}, {"num": "6.", "text": "За то помолитсја к Тебје всјак преподобниј во времја благопотребно: о баче в потопје вода многих к њему не приближитсја."}, {"num": "7.", "text": "Ти јеси прибјежишче моје от скорби обдержашчија мја: радосте моја, избави мја от обишедших мја."}, {"num": "8.", "text": "Вразумљу тја, и настављу тја на пут сеј, в оњже појдеши: утвсржу на тја очи Моји."}, {"num": "9.", "text": "Не будите јако коњ и меск, имже њест разума: броздами и уздоју чељусти их востјагнеши не приближајушчихса к тебје."}, {"num": "10.", "text": "Многи рани грјешному: уповајушчаго же на Господа милост обидет."}, {"num": "11.", "text": "Веселитесја о Господје, и радујтесја праведнији, и хвалитесја вси правији сердцем. Слава:"}]}, "32": {"number": 32, "title": "Псалом 32. (32)", "subtitle": "", "verses": [{"num": "1.", "text": "Радујтесја праведнији о Господје, правим подобајет похвала."}, {"num": "2.", "text": "Исповједајтесја Господеви в гуслех, во псалтири десјатоструњем појте Јему:"}, {"num": "3.", "text": "Воспојте Јему пјесан нову, добрје појте Јему со восклицанијем."}, {"num": "4.", "text": "Јако право слово Господње, и всја дјела Јего во вјерје."}, {"num": "5.", "text": "Љубит милостињу и суд Господ, милости Господњи исполн земља."}, {"num": "6.", "text": "Словом Господњим небеса утвердишасја, и духом уст Јего всја сила их."}, {"num": "7.", "text": "Собирајај јако мјех води морскија, полагајај в сокровишчах бездни."}, {"num": "8.", "text": "Да убојитсја Господа всја земља, от Његоже да подвижутсја вси живушчији по всељењеј:"}, {"num": "9.", "text": "Јако Тој рече, и биша, Тој повеље, и создашасја."}, {"num": "10.", "text": "Господ разорјајет совјети јазиков, отметајет же мисли људеј, и отметајет совјети књазеј."}, {"num": "11.", "text": "Совјет же Господењ во вјек пребивајет, помишљенија сердца јего в род и род."}, {"num": "12.", "text": "Блажен јазик, јемуже јест Господ Бог јего, људи, јаже избра в насљедије себје."}, {"num": "13.", "text": "С небесе призрје Господ, видје всја сини человјеческија."}, {"num": "14.", "text": "От готоваго жилишча својего призрје на всја живушчија на земљи:"}, {"num": "15.", "text": "Создавиј на једиње сердца их, разумјевајај на всја дјела их."}, {"num": "16.", "text": "Не спасајетсја цар многоју силоју, и исполин не спасетсја множеством крјепости својеја."}, {"num": "17.", "text": "Лож коњ во спасеније, во множествје же сили својеја не спасетсја."}, {"num": "18.", "text": "Се очи Господњи на бојашчијасја Јего, уповајушчија на милост Јего:"}, {"num": "19.", "text": "Избавити от смерти души их, и препитати ја в глад."}, {"num": "20.", "text": "Душа же наша чајет Господа, јако помошчник и зашчититељ, наш јест:"}, {"num": "21.", "text": "Јако о Њем возвеселитсја сердце наше, и во имја свјатоје Јего уповахом."}, {"num": "22.", "text": "Буди Господи милост Твоја на нас, јакоже уповахом на Тја."}]}, "33": {"number": 33, "title": "Псалом 33. (33)", "subtitle": "", "verses": [{"num": "1.", "text": "Благословљу Господа на всјакоје времја, вину хвала Јего во устјех мојих."}, {"num": "2.", "text": "О Господје похвалитсја душа моја: да услишат кротци и возвесељатсја."}, {"num": "3.", "text": "Возвеличите Господа со мноју, и вознесем имја Јего вкупје."}, {"num": "4.", "text": "Взисках Господа, и услиша мја, и от всјех скорбеј мојих избави мја."}, {"num": "5.", "text": "Приступите к Њему, и просвјетитесја, и лица ваша не постидјатсја."}, {"num": "6.", "text": "Сеј нишчиј возва, и Господ услиша их, и от всјех скорбеј јего спасе их."}, {"num": "7.", "text": "Ополчитсја ангел Господењ окрест бојашчихсја Јего, и избавит их."}, {"num": "8.", "text": "Вкусите и видите, јако благ Господ: блажен муж, иже уповајет нањ."}, {"num": "9.", "text": "Бојтесја Господа в свјатији Јего, јако њест лишенија бојашчимсја Јего."}, {"num": "10.", "text": "Богатији обнишчаша и взалкаша: взискајушчији же Господа, не лишатсја всјакаго блага."}, {"num": "11.", "text": "Придите чада, послушајте мене, страху Господњу научу вас."}, {"num": "12.", "text": "Кто јест человјек хотјај живот, љубјај дни видјети благи."}, {"num": "13.", "text": "Удержи јазик твој от зла, и устње твоји, јеже не глагољати лести."}, {"num": "14.", "text": "Уклонисја от зла, и сотвори благо: взишчи мира, и пожени их."}, {"num": "15.", "text": "Очи Господњи на праведнија, и уши Јего в молитву их."}, {"num": "16.", "text": "Лице же Господње на творјашчија злаја, јеже потребити от земљи памјат их."}, {"num": "17.", "text": "Возваша праведнији, и Господ услиша их, и от всјех скорбеј их избави их."}, {"num": "18.", "text": "Близ Господ сокрушених сердцем, и смиренија духом спасет."}, {"num": "19.", "text": "Многи скорби праведним, и от всјех их избавит ја Господ."}, {"num": "20.", "text": "Хранит Господ всја кости их, и ни једина от њих сокрушитсја."}, {"num": "21.", "text": "Смерт грјешников љута, и ненавидјашчији праведнаго прегрјешат."}, {"num": "22.", "text": "Избавит Господ души раб својих, и не прегрјешат вси уповајушчији на Њего. Слава:"}]}, "34": {"number": 34, "title": "Псалом 34. (34)", "subtitle": "", "verses": [{"num": "1.", "text": "Суди Господи обидјашчија мја, побори борушчија мја."}, {"num": "2.", "text": "Прими оружије и шчит, и востани в помошч моју."}, {"num": "3.", "text": "Изсуни меч, и закључи сопротив гоњашчих мја: реци души мојеј, спасеније твоје јесам Аз."}, {"num": "4.", "text": "Да постидјатсја и посрамјатсја ишчушчији душу моју: да возвратјатсја вспјат, и постидјатсја мисљашчији ми злаја."}, {"num": "5.", "text": "Да будут јако прах пред лицем вјетра, и ангел Господењ оскорбљајај их."}, {"num": "6.", "text": "Да будет пут их тма, и ползок, и ангел Господењ погоњаја их."}, {"num": "7.", "text": "Јако туне скрша ми пагубу сјети својеја, всује поносиша души мојеј."}, {"num": "8.", "text": "Да пријидет јему сјет, јуже не вјест, и ловитва, јуже скри, да обимет их, и в сјет да впадет в њу."}, {"num": "9.", "text": "Душа же моја возрадујетсја о Господје, возвеселитсја о спасенији Јего."}, {"num": "10.", "text": "Всја кости моја рекут: Господи, Господи, кто подобен Тебје; избављајај нишча из руки крјепилших јего, и нишча и убога от расхишчајушчих јего."}, {"num": "11.", "text": "Воставше на мја свидјетеље неправеднији, јаже не вједјех, вопрошаху мја."}, {"num": "12.", "text": "Воздаша ми лукаваја возблагаја, и безчадије души мојеј."}, {"num": "13.", "text": "Аз же, внегда они стужаху ми, облачахсја во вретишче, и смирјах постом душу моју, и молитва моја в њедро моје возвратитсја."}, {"num": "14.", "text": "Јако ближњему, јако брату нашему, тако угождах: јако плача и сјетуја тако смирјахсја."}, {"num": "15.", "text": "И на мја возвеселишасја и собрашасја: собрашасја на мја рани, и не познах, раздјелишасја, и не умилишасја."}, {"num": "16.", "text": "Искусиша мја, подражниша мја подражненијем, поскрежеташа на мја зуби својими."}, {"num": "17.", "text": "Господи, когда узриши, устрој душу моју от злодјејства их, от лев јединороднују моју."}, {"num": "18.", "text": "Исповемсја Тебје в церкви мнозје, в људех тјажцјех восхваљу Тја."}, {"num": "19.", "text": "Да не возрадујутсја о мње враждујушчији ми неправедно, ненавидјашчији мја туне, и помизајушчији очима."}, {"num": "20.", "text": "Јако мње убо мирнаја глагољаху, и на гњев лести помишљаху."}, {"num": "21.", "text": "Разшириша на мја уста своја, рјеша: благоже, благоже, видјеша очи наши."}, {"num": "22.", "text": "Видјел јеси Господи, да не премолчиши: Господи не отступи от мене."}, {"num": "23.", "text": "Востани Господи, и вонми суду мојему, Боже мој, и Господи мој, на прју моју."}, {"num": "24.", "text": "Суди ми Господи по правдје Твојеј, Господи Боже мој, и да возрадујутсја о мње."}, {"num": "25.", "text": "Да не рекут в сердцах својих: благоже благоже души нашеј: ниже да рекут, пожрохом јего."}, {"num": "26.", "text": "Да постидјатсја и посрамјатсја вкупје радујушчијисја злом мојим: да облекутсја в студ и срам велерјечујушчији на мја."}, {"num": "27.", "text": "Да возрадујутсја и возвесељатсја хотјашчији правди мојеја, и да рекут вину, да возвеличитсја Господ, хотјашчији мира рабу Јего."}, {"num": "28.", "text": "И јазик мој поучитсја правдје Твојеј, всс ден хваље Твојеј."}]}, "35": {"number": 35, "title": "Псалом 35. (35)", "subtitle": "", "verses": [{"num": "1.", "text": "Глагољет пребезакониј согрјешати в себје: њест страха Божија пред очима јего."}, {"num": "2.", "text": "Јако улести пред њим обрјести безаконије своје, и возненавидјети."}, {"num": "3.", "text": "Глаголи уст јего безаконије и лест: не восхотје разумјети јеже ублажити."}, {"num": "4.", "text": "Безаконије помисли па ложи својем: предста всјакому пути неблагу, о злобје же не негодова."}, {"num": "5.", "text": "Господи на небеси милост Твоја, и истина Твоја до облак:"}, {"num": "6.", "text": "Правда Твоја јако гори Божија, судби Твоја бездна многа, человјеки и скоти спасеши Господи."}, {"num": "7.", "text": "Јако умножил јеси милост Твоју Боже: синове же человјечестији в кровје крилу Твојеју надјејатисја имут."}, {"num": "8.", "text": "Упијутсја от тука дому Твојего, и потоком сладости Твојеја напојиши ја."}, {"num": "9.", "text": "Јако у Тебе источник живота, во свјетје Твојем узрим свјет."}, {"num": "10.", "text": "Пробави милост Твоју вједушчим Тја, и правду Твоју правим сердцем."}, {"num": "11.", "text": "Да не пријидет мње нога гордињи, и рука грјешнича да не подвижит мене."}, {"num": "12.", "text": "Тамо падоша вси дјелајушчији безаконије, изриновени биша, и не возмогут стати. Слава:"}]}, "36": {"number": 36, "title": "Псалом 36. (36)", "subtitle": "", "verses": [{"num": "1.", "text": "Не ревнуј лукавнујушчим, ниже завиди творјашчим безаконије."}, {"num": "2.", "text": "Зане јако трава скоро изсшут, и јако зелије злака скоро отпадут."}, {"num": "3.", "text": "Уповај на Господа, и твори благостињу, и насели земљу, и упасешисја в богатствје јеја."}, {"num": "4.", "text": "Насладисја Господеви, и даст ти прошенија сердца Твојего."}, {"num": "5.", "text": "Откриј ко Господу пут Твој, и уповај на Њего, и тој сотворит."}, {"num": "6.", "text": "И изведет јако свјет правду твоју, и судбу твоју јако полудне."}, {"num": "7.", "text": "Повинисја Господеви, и умоли Јего, не ревнуј спјејушчему в пути својем, человјеку творјашчему законопреступљеније."}, {"num": "8.", "text": "Престани от гњева, и остави јарост, не ревнуј, јеже лукавновати."}, {"num": "9.", "text": "Зане лукавнујушчији потребјатсја: терпјашчији же Господа, тији насљедјат земљу."}, {"num": "10.", "text": "И јешче мало, и не будет грјешника: и взишчеши мјесто јего, и не обрјашчеши."}, {"num": "11.", "text": "Кротцији же насљедјат земљу, и насладјатсја о множествје мира."}, {"num": "12.", "text": "Назирајет грјешниј праведнаго, и поскрежешчет нањ зуби својими."}, {"num": "13.", "text": "Господ же посмјејетсја јему, зане прозирајет, јако пријидет ден јего."}, {"num": "14.", "text": "Меч извлекоша грјешници, напрјагоша лук свој, низложити убога и нишча, заклати правија сердцем."}, {"num": "15.", "text": "Меч их да внидет в сердца их, и луци их да сокрушатсја."}, {"num": "16.", "text": "Лучше малоје праведнику, паче богатства грјешних многа."}, {"num": "17.", "text": "Зане мишци грјешних сокрушатсја, утверждајет же праведнија Господ."}, {"num": "18.", "text": "Вјест Господ пути непорочних, и достојаније их во вјек будет."}, {"num": "19.", "text": "Не постидјатсја во времја љутоје, и во днех глада наситјатсја: јако грјешници погибнут."}, {"num": "20.", "text": "Врази же Господњи, купно прославитсја им, и вознестисја, исчезајушче јако дим исчезоша."}, {"num": "21.", "text": "Зајемљет грјешниј, и не возвратит, праведнији же шчедрит, и дајет."}, {"num": "22.", "text": "Јако благословјашчији Јего насљедјат земљу, кленушчији же Јего потребјатсја."}, {"num": "23.", "text": "От Господа стопи человјеку исправљајутсја, и пути Јего восхошчет зјело."}, {"num": "24.", "text": "Јегда падет, не разбијетсја, јако Господ подкрјепљајет руку јего."}, {"num": "25.", "text": "Јуњејшиј бих, ибо состарјехсја, и не видјех праведника остављена, ниже сјемене јего просјашча хљеби."}, {"num": "26.", "text": "Вес ден милујет, и взајим дајет праведниј, и сјемја јего во благословеније будет."}, {"num": "27.", "text": "Уклонисја от зла и сотвори благо, вселисја во вјек вјека."}, {"num": "28.", "text": "Јако Господ љубит суд, и не оставит преподобних својих, во вјек сохрањатсја: безаконици же изженутсја, и сјемја нечестивих потребитсја."}, {"num": "29.", "text": "Праведници же насљедјат земљу, и всељатсја во вјек вјека на њеј."}, {"num": "30.", "text": "Уста праведнаго поучатсја премудрости, и јазик јего возглагољет суд."}, {"num": "31.", "text": "Закон Бога јего в сердцје јего, и не запнутјса стопи јего."}, {"num": "32.", "text": "Сматрјајет грјешниј праведнаго, и ишчет јеже умертвити јего:"}, {"num": "33.", "text": "Господ же не оставит јего в руку јего, ниже осудит јего, јегда судит јему."}, {"num": "34.", "text": "Потерпи Господа, и сохрани пут Јего, и вознесет тја јеже насљедити земљу: внегда потребљатисја грјешником, узриши."}, {"num": "35.", "text": "Видјех нечестиваго превозносјашчасја и висјашчасја, јако кедри Ливанскија:"}, {"num": "36.", "text": "И мимо идох, и се не бје, и взисках јего, и не обрјетесја мјесто јего."}, {"num": "37.", "text": "Храни незлобије, и вижд правоту, јако јест останок человјеку мирну."}, {"num": "38.", "text": "Безаконици же потребјатсја вкупје, останци же нечестивих потребјатсја."}, {"num": "39.", "text": "Спасеније же праведних ое Господа, и зашчититељ их јест во времја скорби:"}, {"num": "40.", "text": "И поможет им Господ и избавит их, и измет их от грјешник, и спасет их, јако уповаша на Њего. Слава:"}]}, "37": {"number": 37, "title": "Псалом 37. (37)", "subtitle": "", "verses": [{"num": "1.", "text": "Господи, да не јаростију Твојеју обличиши мене, ниже гњевом Твојим накажеши мене:"}, {"num": "2.", "text": "Јако стрјели Твоја унзоша во мње, и утвердил јеси на мње руку Твоју."}, {"num": "3.", "text": "Њест исцјељенија в плоти мојеј, от лица гњева Твојего: њест мира в костех мојих, от лица грјех мојих."}, {"num": "4.", "text": "Јако безаконија моја превзидоша главу моју, јако бремја тјажкоје отјаготјеша на мње."}, {"num": "5.", "text": "Возсмердјеша и согниша рани моја от лица безумија мојего."}, {"num": "6.", "text": "Пострадах и сљакохсја до конца, вес ден сјетуја хождах."}, {"num": "7.", "text": "Јако љадвија моја наполнишасја поруганиј, и њест исцјељенија в плоти мојеј."}, {"num": "8.", "text": "Озлобљен бих и смирихсја до зјела, риках от воздиханија сердца мојего."}, {"num": "9.", "text": "Господи, пред Тобоју все желаније моје, и воздиханије моје от Тебе не утајисја."}, {"num": "10.", "text": "Сердце моје смјатесја, остави мја сила моја, и свјет очију мојеју, и тој њест со мноју."}, {"num": "11.", "text": "Друзи моји и искренији моји прјамо мње приближишасја и сташа."}, {"num": "12.", "text": "И ближњији моји отдалече мене сташа, и нуждахусја ишчушчији душу моју, и ишчушчији злаја мње, глагољаху сујетнаја, и лестивним вес ден поучахусја."}, {"num": "13.", "text": "Аз же јако глух не слишах, и јако нјем не отверзајај уст својих."}, {"num": "14.", "text": "И бих, јако человјек не слишај, и не имиј во устјех својих обличенија."}, {"num": "15.", "text": "Јако на Тја Господи уповах, Ти услишиши Господи Боже мој."}, {"num": "16.", "text": "Јако рјех, да не когда порадујутмисја врази моји: и внегда подвижатисја ногама мојим, на мја велерјечеваша."}, {"num": "17.", "text": "Јако аз на рани готов, и бољезан моја предомноју јест вину."}, {"num": "18.", "text": "Јако безаконије моје аз возвјешчу, и попекусја о грјесје мојем."}, {"num": "19.", "text": "Врази же моји живут, и укрјепишасја паче мене, и умножишасја ненавидјашчији мја без правди."}, {"num": "20.", "text": "Воздајушчији ми злаја возблагаја, оболгаху мја, зане гоњах благостињу."}, {"num": "21.", "text": "Не остави мене Господи Боже мој, не отступи от мене."}, {"num": "22.", "text": "Вонми в помошч моју, Господи спасенија мојего."}]}, "38": {"number": 38, "title": "Псалом 38. (38)", "subtitle": "", "verses": [{"num": "1.", "text": "Рјех, сохрању пути моја, јеже не согрјешати ми јазиком мојим: положил устом мојим хранило, внегда востати грјешному предо мноју."}, {"num": "2.", "text": "Онјемјех и смирихсја, и умолчах от благ, и бољезан моја обновисја."}, {"num": "3.", "text": "Согрјејасја сердце моје во мње, и в поученији мојем разгоритсја огањ: глагољах јазиком мојим."}, {"num": "4.", "text": "Скажи ми Господи кончину моју, и число днеј мојих које јест, да разумјеју, что лишајусја аз;"}, {"num": "5.", "text": "Се пјади положил јеси дни моја, и состав мој јако ничтоже пред Тобоју: обаче всјаческаја сујета, всјак человјек живиј."}, {"num": "6.", "text": "Убо образом ходит человјек, обаче всује мјатетсја: сокровишчствујет, и не вјест, кому соберет ја."}, {"num": "7.", "text": "И ниње кто терпјеније моје; не Господ ли; и состав мој от Тебе јест."}, {"num": "8.", "text": "От всјех безаконији мојих избави мја: поношеније безумному дал мја јеси."}, {"num": "9.", "text": "Онјемјех и не отверзох уст мојих, јако Ти сотворил јеси."}, {"num": "10.", "text": "Отстави от мене рани Твоја: от крјепости бо руки Твојеја аз изчезох."}, {"num": "11.", "text": "Во обличенијих о безаконији наказал јеси человјека, и истајал јеси јако паучину душу јего: обаче всује всјак человјек."}, {"num": "12.", "text": "Услиши молитву моју Господи, и мољеније моје внуши, слез мојих не премолчи: јако преселник аз јесам у Тебе и пришлец, јакоже вси оци моји."}, {"num": "13.", "text": "Ослаби ми, да почију, прежде даже не отиду, и ктому не буду."}]}, "39": {"number": 39, "title": "Псалом 39. (39)", "subtitle": "", "verses": [{"num": "1.", "text": "Терпја потерпјех Господа, и вњат ми, и услиша молитву моју:"}, {"num": "2.", "text": "И возведе мја от рова страстеј, и от бренија тини, и постави на камени нозје моји, и исправи стопи моја."}, {"num": "3.", "text": "И вложи во уста моја пјесан нову, пјеније Богу нашему, узрјат мнози и убојатсја и уповајут на Господа."}, {"num": "4.", "text": "Блажен муж, јемуже јест имја Господње упованије јего, и не призрје в сујети и неистовљенија ложнаја."}, {"num": "5.", "text": "Многа сотворил јеси Ти Господи Боже мој чудеса Твоја, и помишљенијем Твојим њест кто уподобитсја Тебје, возвјестих и глагољах, умножишасја паче числа."}, {"num": "6.", "text": "Жертви и приношенија не восхотјел јеси, тјело же свершил ми јеси: всесожежениј и о грјесје не взискал јеси."}, {"num": "7.", "text": "Тогда рјех: се пријиду, во главизње книжње писано јест о Мње:"}, {"num": "8.", "text": "Јеже сотворити вољу Твоју Боже мој, восхотјех, и закон Твој посредје чрева мојего."}, {"num": "9.", "text": "Благовјестих правду в церкви велицјеј, се устнам мојим не возбрању: Господи Ти разумјел јеси."}, {"num": "10.", "text": "Правду Твоју не скрих в сердцје мојем, истину Твоју и спасеније Твоје рјех, не скрих милост Твоју и истину Твоју от сонма многа."}, {"num": "11.", "text": "Ти же Господи не удаљи шчедрот Твојих от мене: милост Твоја и истина Твоја вину да заступитје мја."}, {"num": "12.", "text": "Јако одержаша мја злаја, имже њест числа: постигоша мја безаконија моја, и не возмогох зрјети, умножишасја паче влас глави мојеја, и сердце моје остави мја."}, {"num": "13.", "text": "Благоволи Господи избавити мја: Господи во јеже помошчи ми вонми."}, {"num": "14.", "text": "Да постидјатсја и посрамјатсја вкупје ишчушчији душу моју, изјати ју: да возвратјатсја вспјат, и постидјатсја хотјашчији ми злаја."}, {"num": "15.", "text": "Да пријимут абије студ свој глагољушчији ми: благоже, благоже."}, {"num": "16.", "text": "Да возрадујутсја и возвесељатсја о Тебје вси ишчушчији Тебе, Господи: и да рекут вину, да возвеличитсја Господ, љубјашчији спасеније Твоје."}, {"num": "17.", "text": "Аз же нишч јесам и убог, Господ попечетсја о мње: помошчник мој и зашчититељ мој Ти, Боже мој не закосни. Слава:"}]}, "40": {"number": 40, "title": "Псалом 40. (40)", "subtitle": "", "verses": [{"num": "1.", "text": "Блажен разумјевајај на нишча и убога, в ден љут избавит јего Господ."}, {"num": "2.", "text": "Господ да сохранит јего, и живит јего, и да ублажит јего на земљи, и да не предаст јего в руки врагов јего."}, {"num": "3.", "text": "Господ да поможет јему на одрје бољезни јего: все ложе јего обратил јеси в бољезни јего."}, {"num": "4.", "text": "Аз рјех: Господи помилуј мја, исцјели душу моју, јако согрјеших Ти."}, {"num": "5.", "text": "Врази моји рјеша мње злаја: когда умрет и погибнет имја јего;"}, {"num": "6.", "text": "И вхождаше видјети, всује глагољаше сердце јего, собра безаконије себје, исхождаше воњ, и глагољаше вкупје."}, {"num": "7.", "text": "На мја шептаху вси врази моји, на мја помишљаху злаја мње."}, {"num": "8.", "text": "Слово законопреступноје возложиша на мја: еда спјај не приложит воскреснути;"}, {"num": "9.", "text": "Ибо человјек мира мојего, на његоже уповах, јадиј хљеби моја, возвеличи на мја запинаније."}, {"num": "10.", "text": "Ти же Господи помилуј мја, и возстави мја, и воздам им."}, {"num": "11.", "text": "В сем познах, јако восхотјел мја јеси, јако не возрадујетсја враг мој о мње."}, {"num": "12.", "text": "Мене же за незлобије пријал, и утвердил мја јеси пред Тобоју во вјек."}, {"num": "13.", "text": "Благословен Господ Бог Израиљев от вјека и до вјека: буди буди."}]}, "41": {"number": 41, "title": "Псалом 41. (41)", "subtitle": "", "verses": [{"num": "1.", "text": "Имже образом желајет јелен на источники воднија: сице желајет душа моја к Тебје Боже:"}, {"num": "2.", "text": "Возжада душа моја к Богу крјепкому, живому: когда пријиду и јављусја лицу Божију:"}, {"num": "3.", "text": "Биша слези моја мње хљеб ден и ношч, внегда глагољатисја мње на всјак ден: гдје јест Бог Твој;"}, {"num": "4.", "text": "Сија помјанух, и излијах на мја душу моју: јако пројду в мјесто сељенија дивна даже до дому Божија, во гласје радованија и исповједанија, шума празднујушчаго."}, {"num": "5.", "text": "Вскују прискорбна јеси душе моја; и вскују смушчајеши мја; уповај на Бога, јако исповјемсја Јему, спасеније лица мојего, и Бог мој."}, {"num": "6.", "text": "Ко мње самому душа моја смјатесја: сего ради помјанух Тја от земљи Јордански и Ермонијимски, от гори малија."}, {"num": "7.", "text": "Бездна бездну призивајет во гласје хљабиј Твојих: всја висоти Твоја и волни Твоја на мње прејдоша."}, {"num": "8.", "text": "В ден заповјест Господ милост своју, и ношчију пјесан Јего от мене, молитва Богу живога мојего."}, {"num": "9.", "text": "Реку Богу: заступник мој јеси, почто мја забил јеси; и вскују сјетуја хожду внегда оскорбљајет враг;"}, {"num": "10.", "text": "Внегда сокрушатисја костем мојим, поношаху ми врази моји, внегда глагољати им мње на всјак ден: гдје јест Бог твој;"}, {"num": "11.", "text": "Вскују прискорбна јеси душе моја; и вскују смушчајеши мја; уповај на Бога, јако исповјемсја Јему, спасеније лица мојего, и Бог мој."}]}, "42": {"number": 42, "title": "Псалом 42. (42)", "subtitle": "", "verses": [{"num": "1.", "text": "Суди ми Боже, и разсуди прју моју: от јазика непреподобна, от человјека неправедна и лестива избави мја."}, {"num": "2.", "text": "Зане Ти јеси Боже крјепост моја, вскују отринул мја јеси; и вскују сјетуја хожду, внегда оскорбљајет враг;"}, {"num": "3.", "text": "Посли свјет Твој и истину Твоју, та мја настависта, и воведоста мја в гору свјатују Твоју, и в сељенија Твоја."}, {"num": "4.", "text": "И вниду к жертвенику Божију, к Богу весељашчему јуност моју: исповјемсја Тебје в гуслех Боже, Боже мој."}, {"num": "5.", "text": "Вскују прискорбна јеси душе моја; и вскују смушчајеши мја; уповај на Бога, јако исповјемсја Јему, спасеније лица мојего, и Бог мој. Слава:"}]}, "43": {"number": 43, "title": "Псалом 43. (43)", "subtitle": "", "verses": [{"num": "1.", "text": "Боже ушима нашима услишахом, и оци наши возвјестиша нам дјело, јеже содјелал јеси во днех их, во днех древних."}, {"num": "2.", "text": "Рука Твоја јазики потреби, и насадил ја јеси, озлобил јеси људи, и изгнал јеси ја."}, {"num": "3.", "text": "Не бо мечем својим насљедиша земљу, и мишца их не спасе их: но десница Твоја, и мишца Твоја, и просвјешченије лица Твојего, јако благоволил јеси в њих."}, {"num": "4.", "text": "Ти јеси сам Цар мој и Бог мој, заповједајај спасенија Јаковља."}, {"num": "5.", "text": "О Тебје враги нашја избодем роги, и о имени Твојем уничижим востајушчија на ни."}, {"num": "6.", "text": "Не на лук бо мој уповају, и меч мој не спасет мене:"}, {"num": "7.", "text": "Спасал бо јеси нас от стужајушчих нам и ненавидјашчих нас посрамил јеси."}, {"num": "8.", "text": "О Бозје похвалимсја вес ден, и о имени Твојем исповјемсја во вјек."}, {"num": "9.", "text": "Ниње же отринул јеси, и посрамил јеси нас, и не изидеши Боже в силах наших."}, {"num": "10.", "text": "Возвратил јеси нас вспјат при вразјех наших, и ненавидјашчији нас расхишчаху себје."}, {"num": "11.", "text": "Дал јеси нас јако овци снједију, и во јазицјех разсјејал ни јеси."}, {"num": "12.", "text": "Отдал јеси људи Твоја без цјени, и не бје множества во восклицанијих наших."}, {"num": "13.", "text": "Положил јеси нас поношеније сосједом нашим, подраженије и поруганије сушчим окрест нас."}, {"num": "14.", "text": "Положил јеси нас в причту во јазицјех, и покиванију глави в људех."}, {"num": "15.", "text": "Вес ден срам мој предомноју јест, и студ лица мојего покри мја."}, {"num": "16.", "text": "От гласа поношајушчаго и оклеветајушчаго, от лица вражија и изгоњашчаго."}, {"num": "17.", "text": "Сија всја пријидоша на ни, и не забихом Тебе, и не неправдовахом в завјетје Твојем."}, {"num": "18.", "text": "И не отступи вспјат сердце наше: и уклонил јеси стези нашја от пути Твојего."}, {"num": "19.", "text": "Јако смирил јеси нас на мјестје озлобљенија, и покри ни сјен смертнаја."}, {"num": "20.", "text": "Ашче забихом имја Бога нашего, и ашче воздјехом руки нашја к Богу чуждему:"}, {"num": "21.", "text": "Не Бог ли взишчет сих; тој бо вјест тајнаја сердца."}, {"num": "22.", "text": "Зане Тебе ради умершчвљајемсја вес ден, вмјенихомсја јако овци закољенија:"}, {"num": "23.", "text": "Востани, вскују спиши Господи; воскресни, и не отрини до конца."}, {"num": "24.", "text": "Вскују лице Твоје отврашчајеши; забивајеши нишчету нашу и скорб нашу;"}, {"num": "25.", "text": "Јако смирисја в перст душа наша, прилпе земљи утроба наша."}, {"num": "26.", "text": "Воскресни Господи, помози нам, и избави нас имене ради Твојего."}]}, "44": {"number": 44, "title": "Псалом 44. (44)", "subtitle": "", "verses": [{"num": "1.", "text": "Отригну сердце моје слово благо, глагољу аз дјела моја цареви: јазик мој трост књижника скорописца."}, {"num": "2.", "text": "Красен добротоју паче синов человјеческих, излијасја благодат во устнах Твојих: сего ради благослови Тја Бог во вјек."}, {"num": "3.", "text": "Препојаши меч Твој по бедрје Твојеј силне."}, {"num": "4.", "text": "Красотоју Твојеју и добротоју Твојеју, и налјаци, и успјевај, и царствуј истини ради и кротости и правди, и наставит Тја дивно десница Твоја."}, {"num": "5.", "text": "Стрјели Твоја изошчрени силне, људије под Тобоју падут с сердци враг царевих."}, {"num": "6.", "text": "Престол Твој Боже во вјек вјека: жезал правости, жезал царствија Твојего."}, {"num": "7.", "text": "Возљубил јеси правду, и возненавидјел јеси безаконије: сего ради помаза Тја Боже Бог Твој јелејем радости, паче причастник Твојих."}, {"num": "8.", "text": "Смирна и стакти и касија от риз Твојих, от тјажестеј слонових, из њихже возвеселиша Тја."}, {"num": "9.", "text": "Дшчери цареј в чести Твојеј: предста Царица одеснују Тебе, в ризах позлашчених одјејана, преиспешчрена."}, {"num": "10.", "text": "Ш. Слиши дшчи и вижд, и приклони ухо Твоје, и забуди људи Твоја, и дом оца Твојего."}, {"num": "11.", "text": "И возжелајет Цар доброти Твојеја: зане Тој јест Господ Твој и поклонишасја Јему."}, {"num": "12.", "text": "И дшчи Тирова с дари: лицу Твојему помољатсја богатији људстији."}, {"num": "13.", "text": "Всја слава дшчере Цареви внутар, рјасни златими одјејана и преиспешчрена."}, {"num": "14.", "text": "Приведутсја Царју дјеви в сљед јеја, искренија јеја приведутсја Тебје:"}, {"num": "15.", "text": "Приведутсја во веселији и радованији, воведутсја в храм царев."}, {"num": "16.", "text": "Вмјесто отец твојих биша синове твоји: поставиши ја кљази по всеј земљи."}, {"num": "17.", "text": "Помјану имја Твоје во всјаком родје и родје: сего ради људије исповједјатсја Тебје во вјек, и во вјек вјека."}]}, "45": {"number": 45, "title": "Псалом 45. (45)", "subtitle": "", "verses": [{"num": "1.", "text": "Бог нам прибјежишче и сила, помошчник в скорбех обрјетших ни зјело."}, {"num": "2.", "text": "Сего ради не убојимсја, внегда смушчајетсја земља, и прелагајутсја гори в сердца морскаја."}, {"num": "3.", "text": "Возшумјеша и смјатошасја води их, смјатошасја гори крјепостију јего."}, {"num": "4.", "text": "Рјечнаја устремљенија весељат град Божиј: освјатил јест сељеније своје Вишњиј."}, {"num": "5.", "text": "Бог посредје јего, и не подвижитсја: поможет јему Бог јутро зајутра."}, {"num": "6.", "text": "Смјатошасја јазици, уклонишасја царствија: даде глас свој Вишњиј, подвижесја земља."}, {"num": "7.", "text": "Господ сил с нами, заступник наш Бог Јаковаљ."}, {"num": "8.", "text": "Придите и видите дјела Божија, јаже положи чудеса на земљи:"}, {"num": "9.", "text": "Отемља брапи до конец земљи, лук сокрушит, и сломит оружије, и шчит сожежет огњем."}, {"num": "10.", "text": "Упразднитесја и разумјејте, јако Аз јесам Бог: вознесусја во јазицјех, вознесусја на земљи."}, {"num": "11.", "text": "Господ сил с нами, заступник наш Бог Јаковаљ. Слава:"}]}, "46": {"number": 46, "title": "Псалом 46. (46)", "subtitle": "", "verses": [{"num": "1.", "text": "Вси јазици восплешчите руками: воскликните Богу гласом радованија:"}, {"num": "2.", "text": "Јако Господ Вишњиј, страшен, Цар велиј по всеј земљи."}, {"num": "3.", "text": "Покори људи нам, и јазики под ноги нашја:"}, {"num": "4.", "text": "Избра нам достојаније своје: доброту Јаковљу, јуже возљуби."}, {"num": "5.", "text": "Взиде Бог во воскликновенији, Господ во гласје трубње."}, {"num": "6.", "text": "Појте Богу нашему, појте: појте Цареви нашему, појте."}, {"num": "7.", "text": "Јако Цар всеја земљи Бог, појте разумно."}, {"num": "8.", "text": "Воцарисја Бог над јазики: Бог сједит на престоље свјатјем својем."}, {"num": "9.", "text": "Књази људстији собрашасја с Богом Авраамлим: јако Божији державнији земљи зјело вознесошасја."}]}, "47": {"number": 47, "title": "Псалом 47. (47)", "subtitle": "", "verses": [{"num": "1.", "text": "Велиј Господ и хваљен зјело, во градје Бога нашего, в горје свјатјеј Јего."}, {"num": "2.", "text": "Благокореним радованијем всеја земљи, гори Сионскија, ребра сјеверова, град Царја великаго."}, {"num": "3.", "text": "Бог во тјажестех јего знајем јест, јегда заступит их."}, {"num": "4.", "text": "Јако се царије земстији собрашасја, снидоша вкупје."}, {"num": "5.", "text": "Тији видјевше тако удивишасја, смјатошасја, подвигошасја:"}, {"num": "6.", "text": "Трепет пријат ја: тамо бољезни јако раждајушчија."}, {"num": "7.", "text": "Духом бурним сокрушиши корабли Тарсијскија."}, {"num": "8.", "text": "Јакоже слишахом, тако и видјехом во градје Господа сил, во градје Бога нашего: Бог основа их во вјек."}, {"num": "9.", "text": "Пријахом Боже милост Твоју посредје људеј Твојих."}, {"num": "10.", "text": "По имени Твојему Боже, тако и хвала Твоја на концах земљи: правди исполн десница Твоја."}, {"num": "11.", "text": "Да возвеселитсја гора Сионскаја, и да возрадујутсја дшчери Јудејскија, судеб ради Твојих Господи."}, {"num": "12.", "text": "Обидите Сион, и обимите јего, повједите в столпјех јего."}, {"num": "13.", "text": "Положите сердца ваша в силу јего, и раздјелите доми јего, јако да повјесте в родје ином."}, {"num": "14.", "text": "Јако Тој јест Бог наш во вјек, и во вјек вјека: Тој упасет нас во вјеки."}]}, "48": {"number": 48, "title": "Псалом 48. (48)", "subtitle": "", "verses": [{"num": "1.", "text": "Услишитс сија вси јазици, внушите вси живушчији по вселењеј."}, {"num": "2.", "text": "Земнороднији же и синове человјечестији, вкупје богат и убог."}, {"num": "3.", "text": "Уста моја возглагољут премудрост, и поученије сердца мојего разум."}, {"num": "4.", "text": "Приклоњу в притчу ухо моје, отверзу во псалтири гананије моје."}, {"num": "5.", "text": "Вскују бојусја в ден љут; безаконије пјати мојеја обидет мја."}, {"num": "6.", "text": "Надјејушчијисја на силу своју, и о моножествје богатства својего хваљашчијисја."}, {"num": "7.", "text": "Брат не избавит: избавит ли человјек; не даст Богу измјени за сја."}, {"num": "8.", "text": "И цјену избављенија души својеја: и утрудисја во вјек."}, {"num": "9.", "text": "И жив будет до конца, не узрит пагуби, јегда увидит премудрија умирајушчија."}, {"num": "10.", "text": "Вкупје безумен и несмислен погибнут, и оставјат чуждим богатство своје."}, {"num": "11.", "text": "И гроби их жилишча их во вјек, сељенија их в род и род: нарекоша имена своја на земљах."}, {"num": "12.", "text": "И человјек в чести сиј не разумје, приложисја скотом несмисленим, и уподобисја им."}, {"num": "13.", "text": "Сеј пут их соблазан им, и по сих во устјех својих благовољат."}, {"num": "14.", "text": "Јако овци во адје положени сут, смерт упасет ја: и обладајут ими правији зајутра, и помошч их обетшајет во адје, от слави својеја изриновени биша."}, {"num": "15.", "text": "Обаче Бог избавит душу моју из руки адови, јегда пријемљет мја."}, {"num": "16.", "text": "Не убојсја, јегда разбогатјејет человјек, или јегда умножитсја слава дому јего."}, {"num": "17.", "text": "Јако внегда умрети јему, не возмет всја, ниже снидет с њим слава јего."}, {"num": "18.", "text": "Јако душа јего в животје јего благословитсја: исповјестсја Тебје, јегда благосотвориши јему."}, {"num": "19.", "text": "Внидет даже до рода отец својих: даже до вјека не узрит свјета."}, {"num": "20.", "text": "И человјек в чести сиј не разумје, приложисја скотом несмисленим, и уподобисја им. Слава:"}]}, "49": {"number": 49, "title": "Псалом 49. (49)", "subtitle": "", "verses": [{"num": "1.", "text": "Бог богов Господ глагоља, и призва зсмљу от восток солнца до запад."}, {"num": "2.", "text": "От Сиона благољепије красоти Јего."}, {"num": "3.", "text": "Бог јавје пријидет, Бог наш, и не премолчит: огањ пред Њим возгоритсја, окрест Јего бурја зјелна."}, {"num": "4.", "text": "Призовите небо свише, и земљу, разсудити људи своја."}, {"num": "5.", "text": "Соберите Јему преподобнија Јего, завјешчајушчија завјет Јего о жертвах."}, {"num": "6.", "text": "И возвјестјат небеса правду Јего: јако Бог судија јест."}, {"num": "7.", "text": "Услишите људије моји, и возглагољу вам, Израиљу, и засвидетељствују тебје: Бог, Бог твој јесам Аз."}, {"num": "8.", "text": "Не о жертвах твојих обличу тја, всесожеженија же твоја предомноју сут вину."}, {"num": "9.", "text": "Не пријиму от дому твојего телцев, пиже от стад твојих козлов."}, {"num": "10.", "text": "Јако Моји сут вси звјерије дубравнији, скоти в горах и волове."}, {"num": "11.", "text": "Познах всја птици небеснија, и красота селнаја со Мноју јест."}, {"num": "12.", "text": "Ашче взалчу, не реку тебје: Моја бо јест всељенаја и исполњеније јеја."}, {"num": "13.", "text": "Еда јам мјаса јунча: или кров козлов пију."}, {"num": "14.", "text": "Пожру Богови жертву хвали, и воздажд Вишњсму молитви твоја."}, {"num": "15.", "text": "И призови Мја в ден скорби твојеја, и изму тја, и прославиши Мја."}, {"num": "16.", "text": "Грјешнику же рече Бог: вскују ти повједајеши оправданија Моја, и воспријемљеши завјет Мој уст твојими;"}, {"num": "17.", "text": "Ти же возненавидјел јеси наказаније, и отвергал јеси словеса Моја вспјат."}, {"num": "18.", "text": "Ашче видјел јеси татја, текал јеси с њим, и с прељубодјејем участије твоје полагал јеси."}, {"num": "19.", "text": "Уста твоја умножиша злобу, и јазик твој сплеташе лешченија:"}, {"num": "20.", "text": "Сједја на брата твојего клеветал јеси, и на сина матере твојеја полагал јеси соблазан."}, {"num": "21.", "text": "Сија сотворил јеси, и умолчах, вознепшчевал јеси безаконије, јако буду тебје подобен: обличу тја и представљу пред лицем твојим грјехи твоја."}, {"num": "22.", "text": "Разумјејте убо сија забивајушчији Бога, да не когда похитит, и не будет избављајај."}, {"num": "23.", "text": "Жертва хвали прославит Мја, и тамо пут, имже јављу јему спасеније Моје."}]}, "50": {"number": 50, "title": "Псалом 50. (50)", "subtitle": "", "verses": [{"num": "1.", "text": "Помилуј мја, Боже, по велицјеј милости Твојеј, и по множеству шчедрот Твојих очисти безаконије моје."}, {"num": "2.", "text": "Најпаче омиј мја от безаконија мојего, и от грјеха мојего очисти мја."}, {"num": "3.", "text": "Јако безаконије моје аз знају, и грјех мој предо мноју јест вину."}, {"num": "4.", "text": "Тебје јединому согрјеших, и лукавоје пред Тобоју сотворих, јако да оправдишисја во словесјех Твојих, и побједиши внегда судити Ти."}, {"num": "5.", "text": "Се бо в безаконијих зачат јесам, и во грјесјех роди мја мати моја."}, {"num": "6.", "text": "Се бо истину возљубил јеси, безвјестнаја и тајнаја премудрости Твојеја јавил ми јеси."}, {"num": "7.", "text": "Окропиши мја исопом, и очишчусја, омијеши мја, и паче сњега убјељусја."}, {"num": "8.", "text": "Слуху мојему даси радост и всселије, возрадујутсја кости смиренија."}, {"num": "9.", "text": "Отврати лице Твоје от грјех мојих, и всја безаконија моја очисти."}, {"num": "10.", "text": "Сердце чисто созижди во мње, Боже, и дух прав обнови во утробје мојеј."}, {"num": "11.", "text": "Не отвержи мене от лица Твојего, и Духа Твојего Свјатаго не отими от мене."}, {"num": "12.", "text": "Воздажд ми радост спасенија Твојего, и духом владичним утверди мја."}, {"num": "13.", "text": "Научу безаконија путем Твојим, и нечестивији к Тебје обратјатсја."}, {"num": "14.", "text": "Избави мја от кровеј, Боже, Боже спасенија мојего, возрадујетсја јазик мој правдје Твојеј."}, {"num": "15.", "text": "Господи, устње моји отверзеши, и уста моја возвјестјат хвалу Твоју."}, {"num": "16.", "text": "Јако ашче би восхотјел јеси жертви, дал бих убо, всесожеженија не благоволиши."}, {"num": "17.", "text": "Жертва Богу дух сокрушен, сердце сокрушено и смирено Бог не уничижит."}, {"num": "18.", "text": "Ублажи, Господи, благовољенијем Твојим Сиона, и да созиждутсја стјени Јерусалимскија."}, {"num": "19.", "text": "Тогда благоволиши жертву правди, возношеније и всесожигајемаја, тогда возложат на олтар Твој телци. Слава:"}]}, "51": {"number": 51, "title": "Псалом 51. (51)", "subtitle": "", "verses": [{"num": "1.", "text": "Что хвалишисја в злобје силне; безаконије вес ден."}, {"num": "2.", "text": "Неправду умисли јазик твој: јако бритву изошчрену сотворил јеси лест."}, {"num": "3.", "text": "Возљубил јеси злобу паче благостињи, неправду, њеже глагољати правду."}, {"num": "4.", "text": "Возљубил јеси всја глаголи потопнија, јазик лестив."}, {"num": "5.", "text": "Сего ради Бог разрушит тја до конца: восторгнет тја, и преселит тја от сељенија твојего, и корен твој от земљи живих."}, {"num": "6.", "text": "Узрјат праведнији, и убојатсја, и о њем возсмјејутсја, и рекут:"}, {"num": "7.", "text": "Се человјек, иже не положи Бога помошчника себје, но упова на множество богатства својего, и возможе сујетоју својеју."}, {"num": "8.", "text": "Аз же јако маслина плодовита в дому Божији: уповах на милост Божију во вјек, и во вјек вјека."}, {"num": "9.", "text": "Исповјемсја Тебје во вјек, јако сотворил јеси: и терпљу имја Твоја, јако благо пред преподобними Твојими."}]}, "52": {"number": 52, "title": "Псалом 52. (52)", "subtitle": "", "verses": [{"num": "1.", "text": "Рече безумен в сердцје својем: њест Бог: растљеша и омерзишасја в безаконијих, њест творјај благоје."}, {"num": "2.", "text": "Бог с небесе приниче на сини человјеческија, видјети, ашче јест разумјевајај, или взискајај Бога;"}, {"num": "3.", "text": "Вси уклонишасја, вкупје непотребнији биша: њест творјај благоје, њест до јединаго."}, {"num": "4.", "text": "Ни ли уразумјејут вси дјелајушчији безаконије, снједајушчији људи моја в снјед хлеба; Господа не призваша."}, {"num": "5.", "text": "Тамо устрашишасја страха, идјеже не бје страх:"}, {"num": "6.", "text": "Јако Бог разсипа кости человјекоугодников: постидјешасја, јако Бог уничижи их."}, {"num": "7.", "text": "Кто даст от Сиона спасеније Израиљево: внегда возвратит Бог пљененије људеј својих, возрадујетсја Јаков, и возвеселитсја Израиљ."}]}, "53": {"number": 53, "title": "Псалом 53. (53)", "subtitle": "", "verses": [{"num": "1.", "text": "Боже во имја Твоје спаси мја, и в сиље Твојеј суди ми."}, {"num": "2.", "text": "Боже услиши молитву моју, внуши глаголи уст мојих:"}, {"num": "3.", "text": "Јако чуждији восташа на мја, и крјепци взискаша душу моју, и не предложиша Бога пред собоју."}, {"num": "4.", "text": "Се бо Бог помогајет ми, и Господ заступник души мојеј."}, {"num": "5.", "text": "Отвратит злаја врагов мојим: истиноју Твојеју потреби их."}, {"num": "6.", "text": "Вољеју пожру Тебје, исповемсја имени Твојему Господи, јако благо:"}, {"num": "7.", "text": "Јако от всјакија печали избавил мја јеси, и на враги моја возрје око моје."}]}, "54": {"number": 54, "title": "Псалом 54. (54)", "subtitle": "", "verses": [{"num": "1.", "text": "Внуши Боже молитву моју, и не презри мољенија мојего."}, {"num": "2.", "text": "Вонми ми, и услиши мја: возскорбјех печалију мојеју, и смјатохсја."}, {"num": "3.", "text": "От гласа вражија, и от стуженија грјешнича: јако уклониша на мја безаконије, и во гњевје враждоваху ми."}, {"num": "4.", "text": "Сердце моје смјатесја во мње, и бојазан смерти нападе на мја."}, {"num": "5.", "text": "Страх и трепет пријиде на мја, и покри мја тама."}, {"num": "6.", "text": "Се удаљихсја бјегаја, и водворихсја в пустињи."}, {"num": "7.", "text": "Чајах Бога спасајушчаго мја от малодушија и от бури."}, {"num": "8.", "text": "Потопи Господи, и раздјели јазики их, јако видјех безаконије и прерјеканије во градје."}, {"num": "9.", "text": "Днем и ношчију обидет их по стјенам јего: безаконије и труд посредје јего, и неправда:"}, {"num": "10.", "text": "И не оскудје от стогн јего лихва и лест."}, {"num": "11.", "text": "Јако ашче би враг поносил ми, претерпјел бих убо: и ашче би ненавидјај мја на мја велерјечевал, укрилбихсја от њего."}, {"num": "12.", "text": "Ти же человјече равнодушне, владико мој и знајемиј мој,"}, {"num": "13.", "text": "Иже купно наслаждалсја јеси со мноју брашен: в дому Божији ходихом јединомишљенијем."}, {"num": "14.", "text": "Да пријидет же смерт на ња, и да снидут во ад живи: јако лукавство в жилишчах их, посредје их."}, {"num": "15.", "text": "Аз к Богу возвах, и Господ услиша мја."}, {"num": "16.", "text": "Вечер и зајутра и полудне повјем, и возвјешчу, и услишит глас мој."}, {"num": "17.", "text": "Избавит миром душу моју от приближајушчихсја мње: јако во мнозје бјаху со мноју."}, {"num": "18.", "text": "Услишит Бог, и смирит ја сиј прежде вјек: њест бо им измјењенија, јако не убојашасја Бога."}, {"num": "19.", "text": "Простре руку своју на воздајаније: оскверниша завјет Јего."}, {"num": "20.", "text": "Раздјелишасја от гњева лица Јего, и приближишасја сердца их: умјакнуша словеса их паче јелеја, и та сут стрјели."}, {"num": "21.", "text": "Возверзи на Господа печал твоју, и Тој тја препитајет: не даст во вјек молви праведнику."}, {"num": "22.", "text": "Ти же Боже низведеши их во студенец истљенија: мужије кровеј и лести непреполовјат днеј својих: аз же Господи уповају на Тја. Слава:"}]}, "55": {"number": 55, "title": "Псалом 55. (55)", "subtitle": "", "verses": [{"num": "1.", "text": "Помилуј мја Боже, јако попра мја человјек: вес ден борја стужи ми."}, {"num": "2.", "text": "Попраша мја врази моји вес ден: јако мнози борјушчији мја с висоти."}, {"num": "3.", "text": "В ден не убојусја, аз же уповају на Тја."}, {"num": "4.", "text": "О Бозје похваљу словеса моја: на Бога уповах, не убојусја, что сотворит мње плот."}, {"num": "5.", "text": "Вес ден словес мојих гпушахусја: на мја всја помишљенија их на зло."}, {"num": "6.", "text": "Всељатсја и скријут: тији пјату моју сохрањат, јакоже потерпјеша душу моју."}, {"num": "7.", "text": "Ни о чесомже отринеши ја, гњевом људи низведеши."}, {"num": "8.", "text": "Боже, живот мој возвјестих Тебје: положил јеси слези моја пред Тобоју, јако и во објетованији Твојем."}, {"num": "9.", "text": "Да возвратјатсја врази моји вспјат, в оњже ашче ден призову Тја: се познах, јако Бог мој јеси Ти."}, {"num": "10.", "text": "О Бозје похваљу глагол: о Господје похваљу слово."}, {"num": "11.", "text": "На Бога уповах, не убојусја, что сотворит мње человјек."}, {"num": "12.", "text": "Во мње Боже молитви, јаже воздам хвали Твојеја:"}, {"num": "13.", "text": "Јако избавил јеси душу моју от смерти, очи моји от слез, и нозје моји от поползновенија, благоугожду пред Господем во свјетје живих."}]}, "56": {"number": 56, "title": "Псалом 56. (56)", "subtitle": "", "verses": [{"num": "1.", "text": "Помилуј мја Боже, помилуј мја: јако на Тја упова душа моја, и на сјен крилу Твојеју надјејусја, дондеже прејдет безаконије."}, {"num": "2.", "text": "Возову к Богу Вишњему, Богу благодјејавшему мње."}, {"num": "3.", "text": "Посла с небесе и спасе мја, даде в поношеније попирајушчија мја: посла Бог милост своју и истину своју."}, {"num": "4.", "text": "И избави душу моју от среди скимнов, поспах смушчен: синове человјечестији, зуби их оружија и стрјели, и јазик их меч оштар."}, {"num": "5.", "text": "Вознесисја на небеса Боже, и по всеј земљи слава Твоја."}, {"num": "6.", "text": "Сјет уготоваша ногам мојим, и сљакоша душу моју: ископаша пред лицем мојим јаму, и впадоша в њу."}, {"num": "7.", "text": "Готово сердце моје Боже, готово сердце моје: воспоју и поју во славје мојеј."}, {"num": "8.", "text": "Востани слава моја, востани псалтирју и гусли: востану рано."}, {"num": "9.", "text": "Исповјемсја Тебје в људех Господи, воспоју Тебје во јазицјех:"}, {"num": "10.", "text": "Јако возвеличисја до небес милост Твоја, и даже да облак истина Твоја."}, {"num": "11.", "text": "Вознесисја на небеса Боже, и по всеј земљи слава Твоја."}]}, "57": {"number": 57, "title": "Псалом 57. (57)", "subtitle": "", "verses": [{"num": "1.", "text": "Ашче воистину убо правду глагољете, праваја судите синове человјечестији;"}, {"num": "2.", "text": "Ибо в сердцје безаконије дјелајете на земљи: неправду руки вашја сплетајут."}, {"num": "3.", "text": "Очуждишасја грјешници от ложесан заблудиша от чрева, глагољаша лажу."}, {"num": "4.", "text": "Јарост их по подобију змијину, јако аспида глуха и затикајушчаго уши своји,"}, {"num": "5.", "text": "Иже не услишит гласа обавајушчих, обавајем обавајетсја от премудра."}, {"num": "6.", "text": "Бог сокрушит зуби их во устјех их: членовнија лавов сокрушил јест Господ."}, {"num": "7.", "text": "Уничижатсја јако вода мимотекушчаја: напрјажет лук свој, дондеже изнемогут."}, {"num": "8.", "text": "Јако воск растајав отимутсја: паде огањ на њих, и нс видјеша солнца."}, {"num": "9.", "text": "Прежде јеже разумјети тернија вашего рамна, јако живи, јако во гњевје пожрет ја."}, {"num": "10.", "text": "Возвеселитсја праведник, јегда увидит отмишченије: руцје своји умијет в крови грјешника."}, {"num": "11.", "text": "И речет человјек: ашче убо јест плод праведнику; убо јест Бог судја им на земљи. Слава:"}]}, "58": {"number": 58, "title": "Псалом 58. (58)", "subtitle": "", "verses": [{"num": "1.", "text": "Изми мја от враг мојих Боже, и от востајушчих на мја избави мја."}, {"num": "2.", "text": "Избави мја от дјелајушчих безаконије, и от муж кровеј спаси мја."}, {"num": "3.", "text": "Јако се уловиша душу моју, нападоша на мја крјепцији: ниже безаконије моје, ниже грјех мој, Господи."}, {"num": "4.", "text": "Без безаконија текох и исправих: востани в срјетеније моје, и вижд."}, {"num": "5.", "text": "И Ти Господи Боже сил, Боже Израиљев, вонми посјетити всја јазики: да не ушчедриши всја дјелајушчија безаконије."}, {"num": "6.", "text": "Возвратјатсја на вечер, и взалчут јако пес, и обидут град."}, {"num": "7.", "text": "Се тији отвјешчајут уст својими, и меч во устнах их: јако кто слиша;"}, {"num": "8.", "text": "И Ти Господи посмјејешисја им, уничижиши всја јазики."}, {"num": "9.", "text": "Державу моју к Тебје сохрању: јако Ти Боже заступник мој јеси."}, {"num": "10.", "text": "Бог мој, милост Јего предварит мја: Бог мој, јавит мње на вразјех мојих."}, {"num": "11.", "text": "Не убиј их, да не когда забудут закон Твој: расточи ја силоју Твојеју, и низведи ја, зашчитниче мој Господи."}, {"num": "12.", "text": "Грјех уст их, слово устен их: и јати да будут в гордињи својеј, и от кљатви и лажи возвјестјатсја в кончиње."}, {"num": "13.", "text": "Во гњевје кончини, и не будут: и увједјат, јако Бог владичествујет Јаковом, и конци земљи."}, {"num": "14.", "text": "Возвратјатсја на вечер, и взалчут јако пес, и обидут град."}, {"num": "15.", "text": "Тији разидутсја јасти: ашче ли же не наситјатсја, и порошнчут."}, {"num": "16.", "text": "Аз же воспоју силу Твоју, и возрадујусја зајутра о милости Твојеј: јако бил јеси заступник мој, и прибјежишче моје в ден скорби мојеја."}, {"num": "17.", "text": "Помошчник мој јеси, Тебје поју: јако Бог заступник мој јеси, Боже мој, милост моја."}]}, "59": {"number": 59, "title": "Псалом 59. (59)", "subtitle": "", "verses": [{"num": "1.", "text": "Боже, отринул ни јеси, и низложил јеси нас: разгњевалсја јеси, и ушчедрил јеси нас."}, {"num": "2.", "text": "Стрјасал јеси земљу, и смутил јеси ју: исцјели сокрушеније јеја, јако подвижесја."}, {"num": "3.", "text": "Показал јеси људем Твојим жестокаја: напојил јеси нас вином умиљенија."}, {"num": "4.", "text": "Дал јеси бојашчимсја Тебе знаменије, јеже убјежати от лица лука."}, {"num": "5.", "text": "Јако да избавјатсја возљубљенији Твоји, спаси десницеју Твојеју и услиши мја."}, {"num": "6.", "text": "Бог возглагоља во свјатјем својем: возрадујусја, и раздјељу Сикиму, и Јудол жилишч размјерју."}, {"num": "7.", "text": "Мој јест Галад, и мој јест Манасиј, и Јефрем крјепост глави Мојеја, Јуда цар Мој."}, {"num": "8.", "text": "Моав коноб упованија Мојего, на Идумеју простру сапог Мој: Мње ипоплеменици покоришасја."}, {"num": "9.", "text": "Кто воведет мја во град огражденија; или кто наставит мја до Идумеји;"}, {"num": "10.", "text": "Не Ти ли Боже, отринувиј нас; и не изидеши Боже в силах наших;"}, {"num": "11.", "text": "Дажд нам помошч от скорби; и сујетно спасеније человјеческо,"}, {"num": "12.", "text": "О Бозје сотворим силу, и Тој уничижит стужајушчија нам."}]}, "60": {"number": 60, "title": "Псалом 60. (60)", "subtitle": "", "verses": [{"num": "1.", "text": "Услиши Боже мољеније моје, вонми молитвје мојеј:"}, {"num": "2.", "text": "От конец земљи к Тебје возвах, внегда уни сердце моје: на камен вознесал мја јеси, наставил мја јеси."}, {"num": "3.", "text": "Јако бил јеси упованије моје, столп крјепости от лица вражија."}, {"num": "4.", "text": "Всељусја в сељенији Твојем во вјеки: покријусја в кровје крил Твојих."}, {"num": "5.", "text": "Јако Ти Боже услишил јеси молитви моја: дал јеси достојаније бојашчимсја имене Твојего."}, {"num": "6.", "text": "Дни на дни цареви приложиши: љета јего до дне рода."}, {"num": "7.", "text": "Пребудет во вјек пред Богом: милост и истину Јего взишчет;"}, {"num": "8.", "text": "Тако воспоју имени Твојему во вјеки, воздати ми молитви моја ден от дне. Слава:"}]}, "61": {"number": 61, "title": "Псалом 61. (61)", "subtitle": "", "verses": [{"num": "1.", "text": "Не Богу ли повинетсја душа моја; от Того бо спасеније моје."}, {"num": "2.", "text": "Ибо Тој Бог мој, и спас мој, заступник мој: не подвижусја најпаче."}, {"num": "3.", "text": "Докоље належите на человјека; убивајете вси ви, јако стјење преклонење и оплоту возриновену;"}, {"num": "4.", "text": "Обаче цјену моју совјешчаша отринути, текоша в жажди: уст својими благословљаху, и сердцем својим клењаху."}, {"num": "5.", "text": "Обаче Богови повинисја душе моја: јако от Того терпјеније моје."}, {"num": "6.", "text": "Ибо тој Бог мој, спас мој, заступник мој: пе пресељусја."}, {"num": "7.", "text": "О Бозје спасеније моје и слава моја; Бог помошчи мојеја, и упованије моје на Бога."}, {"num": "8.", "text": "Уповајте на Њего вес сонм људеј, излијајте пред Њим сердца ваша: јако Бог помошчник наш."}, {"num": "9.", "text": "Обаче сујетни синове человјечестији, лаживи синове человјечестији, в мјериљех јеже неправдовати, тији от сујети вкупје."}, {"num": "10.", "text": "Не уповајте на неправду, и на восхишченије не желајте: богатство ашче течет, не прилагајте сердца."}, {"num": "11.", "text": "Јединоју глагоља Бог, двоја сија слишах: зане держава Божија."}, {"num": "12.", "text": "И Твоја Господи милост: јако Ти воздаси комуждо по дјелом јего."}]}, "62": {"number": 62, "title": "Псалом 62. (62)", "subtitle": "", "verses": [{"num": "1.", "text": "Боже, Боже мој, к Тебје јутрењују: возжада Тебе душа моја, кољ множицеју Тебје плот моја, в земљи пустје, и непроходње, и безводње."}, {"num": "2.", "text": "Тако во свјатјем јавихсја Тебје видјети силу Твоју и славу Твоју."}, {"num": "3.", "text": "Јако лучши милост Твоја паче живот: устње моји похвалитје Тја."}, {"num": "4.", "text": "Тако благословљу Тја в животје мојем, о имени Твојем воздјежу руцје моји."}, {"num": "5.", "text": "Јако от тука и масти да исполнитсја душа моја: и устнама радости восхваљат Тја уста моја."}, {"num": "6.", "text": "Ашче поминах Тја па постељи мојеј: на јутрених поучахсја в Тја."}, {"num": "7.", "text": "Јако бил јеси помошчник мој, и в кровје крилу Твојеју возрадујусја."}, {"num": "8.", "text": "Прилпе душа моја по Тебје, мене же пријат десница Твоја."}, {"num": "9.", "text": "Тији же всује искаша душу моју: внидут в преисподњаја земљи."}, {"num": "10.", "text": "Предадјатсја в руки оружија: части лисовом будут."}, {"num": "11.", "text": "Цар же возвеселитсја о Бозје: похвалитсја всјак кленијсја им: јако заградишасја уста глагољушчих неправеднаја."}]}, "63": {"number": 63, "title": "Псалом 63. (63)", "subtitle": "", "verses": [{"num": "1.", "text": "Услиши Боже глас мој, внегда молимтисја к Тебје: от страха вражија изми душу моју."}, {"num": "2.", "text": "Покриј мја от сонма лукавнујушчих, от множества дјелајушчијих неправду."}, {"num": "3.", "text": "Иже изостриша јако меч јазики своја, напрјагоша лук свој, вешч горку."}, {"num": "4.", "text": "Сострјељати в тајних непорочна: внезапу сострјељајут јего, и не убојатсја."}, {"num": "5.", "text": "Утвердиша себје слово лукавноје: повједаша скрити сјет, рјеша: кто узрит их;"}, {"num": "6.", "text": "Испиташа безаконије: исчезоша испитајушчији испитанија: приступит человјек, и сердце глубоко."}, {"num": "7.", "text": "И вознесетсја Бог: стрјели младенец биша јазви их."}, {"num": "8.", "text": "И изнемогоша на ња јазици их, смутишасја вси видјашчији их."}, {"num": "9.", "text": "И убојасја всјак человјек: и возвјестиша дјела Божија, и творенија Јего разумјеша."}, {"num": "10.", "text": "Возвеселитсја праведник о Господје, и уповајет на Њего, и похваљатсја вси правији сердцем. Слава:"}]}, "64": {"number": 64, "title": "Псалом 64. (64)", "subtitle": "", "verses": [{"num": "1.", "text": "Тебје подобајет пјесан Боже в Сиоње, и Тебје воздатсја молитва во Јерусалимје."}, {"num": "2.", "text": "Услиши молитву моју: к Тебје всјака плот пријидет."}, {"num": "3.", "text": "Словеса безаконик премогоша нас, и нечестија наша Ти очистиши."}, {"num": "4.", "text": "Блажен, јегоже избрал јеси и пријал, вселитсја во дворјех Твојих: исполнимсја во благих дому Твојего: свјат храм Твој,"}, {"num": "5.", "text": "Дивен в правдје, услиши ни Боже Спаситељу паш, упованије всјех концеј земљи, и сушчих в мори далече."}, {"num": "6.", "text": "Уготовљајај гори крјепостију својеју, препојасан силоју:"}, {"num": "7.", "text": "Смушчајај глубину морскују, шуму волн јего кто постојит; смјатутсја јазици."}, {"num": "8.", "text": "И убојатсја живушчији в копцах от знаменији Твојих: исходи јутра и вечера украсиши."}, {"num": "9.", "text": "Посјетил јеси земљу, и упојил јеси ју, умножил јеси обогатити ју: рјека Божија наполнисја вод: уготовал јеси пишчу им, јако тако јест уготованије."}, {"num": "10.", "text": "Бразди јеја упој, умножи жита јеја, в капљах јеја возвеселитсја возсијајушчи."}, {"num": "11.", "text": "Благословиши вјенец љета благости Твојеја, и поља Твоја исполњатсја тука."}, {"num": "12.", "text": "Разботјејут краснаја пустињи, и радостију холми препојашутсја."}, {"num": "13.", "text": "Одјејашасја овни овчији, и удолија умножат пшеницу: возовут, ибо воспојут."}]}, "65": {"number": 65, "title": "Псалом 65. (65)", "subtitle": "", "verses": [{"num": "1.", "text": "Воскликните Господеви всја земља, појте же имени Јего, дадите славу хваље Јего."}, {"num": "2.", "text": "Реците Богу: кољ страшна дјела Твоја: во множествје сили Твојеја солжут Тебје врази Твоји."}, {"num": "3.", "text": "Всја земља да поклонитсја Тебје, и појет Тебје: да појет же имени Твојему Вишњиј."}, {"num": "4.", "text": "Придите и видите дјела Божија, кољ страшен во совјетјех паче синов человјеческих."}, {"num": "5.", "text": "Обрашчајај море в сушу, в рјецје пројдут ногами: тамо возвеселимсја о Њем."}, {"num": "6.", "text": "Владичествујушчем силоју својеју вјеком: очи Јего на јазики призирајетје: преогорчевајушчији да не возносјатсја в себје."}, {"num": "7.", "text": "Благословите јазици Бога нашего, и услишан сотворите глас хвали Јего:"}, {"num": "8.", "text": "Положшаго душу моју в живот, и не давшаго во смјатеније ног мојих."}, {"num": "9.", "text": "Јако искусил ни јеси Боже, разжегал ни јеси, јакоже разжизајетсја сребро."}, {"num": "10.", "text": "Вовел ни јеси в сјет: положил јеси скорби на хребтје нашем."}, {"num": "11.", "text": "Возвел јеси человјеки на глави нашја: проидохом сквозје огањ и воду, и извел јеси ни в покој."}, {"num": "12.", "text": "Вниду в дом Твој со всесожеженијем: воздам Тебје молитви моја,"}, {"num": "13.", "text": "Јаже изрекостје устње моји, и глагољаша уста моја в скорби мојеј."}, {"num": "14.", "text": "Всесожеженија тучна вознесу Тебје с кадилом и овни, вознесу Тебје воли с козли."}, {"num": "15.", "text": "Придите услишите, и повјем вам, вси бојашчијисја Бога, јелика сотвори души мојеј."}, {"num": "16.", "text": "К Њему уст мојими возвах, и вознесох под јазиком мојим."}, {"num": "17.", "text": "Неправду ашче узрјех в сердцје мојем, да не услишит мене Господ:"}, {"num": "18.", "text": "Сего ради услиша мја Бог, вњат гласу мољенија мојего."}, {"num": "19.", "text": "Благословен Бог, иже не остави молитву моју, и милост своју от мене."}]}, "66": {"number": 66, "title": "Псалом 66. (66)", "subtitle": "", "verses": [{"num": "1.", "text": "Боже ушчедри ни, и благослови ни, просвјети лице Твоје на ни, и помилуј ни."}, {"num": "2.", "text": "Познати на земљи пут Твој, во всјех јазицјех спасеније Твоје."}, {"num": "3.", "text": "Да исповједјатсја Тебје људије Боже: да исповједјатсја Тебје људије вси."}, {"num": "4.", "text": "Да возвесељатсја, и да возрадујутсја јазици: јако судиши људем правотоју, и јазики на земљи наставиши."}, {"num": "5.", "text": "Да исповједјатсја Тебје људије Боже: да исповједатсја Тебје људије вси."}, {"num": "6.", "text": "Земља даде плод свој: благослови ни Боже, Боже наш."}, {"num": "7.", "text": "Благослови ни Боже: и да убојатсја Јего вси конци земљи. Слава:"}]}, "67": {"number": 67, "title": "Псалом 67. (67)", "subtitle": "", "verses": [{"num": "1.", "text": "Да воскреснет Бог, и расточатсја врази Јего, и да бјежат от лица Јего ненавидјашчији Јего."}, {"num": "2.", "text": "Јако исчезајет дим, да исчезнут: јако тајет восак от лица огња, тако да погибнут грјешници от лица Божија,"}, {"num": "3.", "text": "А праведници да возвесељатсја: да возрадујутсја пред Богом, да насладјатсја во веселији."}, {"num": "4.", "text": "Воспојте Богу, појте имени Јего: путесотворите возшедшему на запади, Господ имја Јему: и радујтесја пред Њим."}, {"num": "5.", "text": "Да смјатутсја от лица Јего, оца сирих, и судиј вдовиц. Бог во мјестје свјатјем својем."}, {"num": "6.", "text": "Бог всељајет јединомисленија в дом, изводја окованија мужеством, такожде преогорчевајушчија живушчија во гробјех."}, {"num": "7.", "text": "Боже, внегда исходити Тебје пред људми Твојими, внегда мимоходити Тебје в пустињи:"}, {"num": "8.", "text": "Земља потрјасесја, ибо небеса кануша от лица Бога Синаина, от лица Бога Израиљева."}, {"num": "9.", "text": "Дожд вољен отлучиши Боже достојанију Твојему, и изнеможе, Ти же совершил јеси је."}, {"num": "10.", "text": "Животнаја Твоја живут на њеј: уготовал јеси благостију Твојеју нишчему Боже."}, {"num": "11.", "text": "Господ даст глагол благовјествујушчим силоју многоју."}, {"num": "12.", "text": "Цар сил возљубљенаго, красотоју дому раздјелити користи:"}, {"num": "13.", "text": "Ашче поспите посредје предјел, криље голубиње посребрење, и междорамија јеја в блешчанији злата:"}, {"num": "14.", "text": "Внегда разниствит небесниј цари на њеј, осњежатсја в Селмоње."}, {"num": "15.", "text": "Гора Божија, гора тучнаја, гора усиренаја, гора тучнаја."}, {"num": "16.", "text": "Вскују непшчујете гори усиренаја; гора, јуже благоволи Бог жити в њеј: ибо Бог вселитсја до конца."}, {"num": "17.", "text": "Колесница Божија тмами тем, тисјашча гобзујушчих: Господ в њих в Синај во свјатјем."}, {"num": "18.", "text": "Возшел јеси на висоту, пљенил јеси пљен: пријал јеси дајанија в человјецјех, ибо непокарјајушчијасја, јеже вселитисја."}, {"num": "19.", "text": "Господ Бог благословен, благословен Господ ден дне: поспјешит нам Бог спасенији наших."}, {"num": "20.", "text": "Бог наш, Бог јеже спасати: и Господња Господња исходишча смертнаја."}, {"num": "21.", "text": "Обаче Бог сокрушит глави врагов својих, верх влас преходјашчих в прегрјешенијих својих."}, {"num": "22.", "text": "Рече Господ: от Васана обрашчу, обрашчу во глубинах морских:"}, {"num": "23.", "text": "Јако да омочитсја нога твоја в крови, јазик пес твојих от враг от њего."}, {"num": "24.", "text": "Видјена биша шествија Твоја Боже, шествија Бога мојего Царја, иже во свјатјем."}, {"num": "25.", "text": "Предвариша књази близ појушчих, посредје дјев тимпаниц."}, {"num": "26.", "text": "В церквах благословите Бога, Господа от источник Израиљевих."}, {"num": "27.", "text": "Тамо Венијамин јуњејшиј во ужасје, књази Јудови владики их, књази Завулони; књази Нефталимли."}, {"num": "28.", "text": "Заповјежд Боже силоју Твојеју, укрјепи Боже сије, јеже содјелал јеси в нас."}, {"num": "29.", "text": "От храма Твојего во Јерусалим Тебје принесут царије дари."}, {"num": "30.", "text": "Запрети звјерем тростним: сонм јунец в јуницах људских, јеже затворити искушенија сребром; расточи јазики хотјашчија бранем."}, {"num": "31.", "text": "Пријидут молитвеници от Египта: Етиопија предварит руку своју к Богу."}, {"num": "32.", "text": "Царствија земнаја појте Богу, воспојте Господеви,"}, {"num": "33.", "text": "Возшедшему на небо небесе на востоки: се даст гласу својему глас сили."}, {"num": "34.", "text": "Дадите славу Богови: на Израиљи велељепота Јего, и сила Јего на облацјех."}, {"num": "35.", "text": "Дивен Бог во свјатих својих, Бог Израиљев: Тој даст силу и державу људем својим: благословен Бог. Слава:"}]}, "68": {"number": 68, "title": "Псалом 68. (68)", "subtitle": "", "verses": [{"num": "1.", "text": "Спаси мја Боже, јако внидоша води до души мојеја."}, {"num": "2.", "text": "Угљебох в тимјенији глубини морскија, и бурја потопи мја."}, {"num": "3.", "text": "Утрудихсја зовиј, измолче гортан мој, исчезостје очи моји, от јеже уповати ми на Бога мојего."}, {"num": "4.", "text": "Умножишасја паче влас глави мојеја ненавидјашчији мја туне: укрјепишасја врази моји, изгоњашчији мја неправедно: јаже не восхишчах, тогда воздајах."}, {"num": "5.", "text": "Боже Ти увједјел јеси безумије моје, и прегрјешенија моја от Тебе не утајишасја."}, {"num": "6.", "text": "Да не постидјатсја о мње терпјашчији Тебе Господи, Господи сил: ниже да посрамјатсја о мње ишчушчији Тебе Боже Израиљев."}, {"num": "7.", "text": "Јако Тебе ради претерпјех поношеније, покри срамота лице моје."}, {"num": "8.", "text": "Чужд бих братији мојеј, и странен синовом матере мојеја."}, {"num": "9.", "text": "Јако ревност дому Твојего снједе мја, и поношенија поносјашчих Ти нападоша на мја."}, {"num": "10.", "text": "И покрих постом душу моју, и бист в поношеније мње."}, {"num": "11.", "text": "И положих одјејаније моје вретишче, и бих им в притчу."}, {"num": "12.", "text": "О мње глумљахусја сједјашчији во вратјех, и о мње појаху пијушчији вино."}, {"num": "13.", "text": "Аз же молитвоју мојеју к Тебје Боже: времја благовољенија, Боже во множествје милости Твојеја услиши мја, во истиње спасенија Твојего."}, {"num": "14.", "text": "Спаси мја от бренија, да не угљебну: да избављусја от ненавидјашчих мја, и от глубоких вод."}, {"num": "15.", "text": "Да не потопит мене бурја воднаја, ниже да пожрет мене глубина, ниже сведет о мње ровеник уст својих."}, {"num": "16.", "text": "Услиши мја Господи, јако блага милост Твоја: по множеству шчедрот Твојих призри на мја."}, {"num": "17.", "text": "Не отврати лица Твојего от отрока Твојего: јако скорбљу, скоро услиши мја."}, {"num": "18.", "text": "Вонми души мојеј, и избави ју: враг мојих ради избави мја."}, {"num": "19.", "text": "Ти бо вјеси поношеније моје, и студ мој, и срамоту моју: пред Тобоју вси оскорбљајушчији мја."}, {"num": "20.", "text": "Поношеније чајаше душа моја и страст: и ждах соскорбјашчаго, и не бје, и утјешајушчих, и не обрјетох."}, {"num": "21.", "text": "И даша в снјед Моју желч, и в жажду Моју напојиша оцта."}, {"num": "22.", "text": "Да будет трапеза их пред њими в сјет, и во воздајаније и в соблазан."}, {"num": "23.", "text": "Да помрачатсја очи их јеже не видјети, и хребет их вину сљаци."}, {"num": "24.", "text": "Пролеј на ња гњев Твој, и јарост гњева Твојего да постигнет их."}, {"num": "25.", "text": "Да будет двор их пуст, и в жилишчах их да не будет живиј:"}, {"num": "26.", "text": "Зане јегоже Ти поразил јеси, тији погнаша, и к бољезни јазви мојих приложиша."}, {"num": "27.", "text": "Приложи безаконије к безаконију их, и да не внидут в правду Твоју."}, {"num": "28.", "text": "Да потребјатсја от књиги живих, и с праведними да не напишутсја."}, {"num": "29.", "text": "Нишч и бољај јесам аз: спасеније Твоје Боже да пријимет мја."}, {"num": "30.", "text": "Восхваљу имја Бога мојего с пјеснију, возвеличу Јего во хваљенији:"}, {"num": "31.", "text": "И угодно будет Богу паче телца јуна, роги износјашча и пазнокти."}, {"num": "32.", "text": "Да узрјат нишчији и возвесељатсја: взишчите Бога, и жива будет душа ваша."}, {"num": "33.", "text": "Јако услиша убогија Господ, и окованија своја не уничижи."}, {"num": "34.", "text": "Да восхваљат Јего небеса и земља, море и всја живушчаја в њем."}, {"num": "35.", "text": "Јако Бог спасет Сиопа, и созиждутсја гради Јудејстији: и всељатсја тамо, и насљедјат их."}, {"num": "36.", "text": "И сјемја рабов Твојих удержит их, и љубљашчији имја Твоје всељатсја в њем."}]}, "69": {"number": 69, "title": "Псалом 69. (69)", "subtitle": "", "verses": [{"num": "1.", "text": "Боже, в помошч моју вонми: Господи помошчи ми потшчисја."}, {"num": "2.", "text": "Да постидјатсја и посрамјатсја ишчушији душу моју, да возвратјатсја вспјат, и постидјатсја, хотјашчији ми злаја."}, {"num": "3.", "text": "Да возвратјатсја абије стидјашчесја глагољушчији ми, благоже благоже."}, {"num": "4.", "text": "Да возрадујутсја и возвесељатсја о Тебје вси ушчушчији Тебе Боже: и да глагољут вину, да возвеличитсја Господ, љубљашчији спасеније Твоје."}, {"num": "5.", "text": "Аз же нишч јесам и убог, Боже помози ми: помошчник мој, и избавитељ мој јеси Ти, Господи не закосни. Слава:"}]}, "70": {"number": 70, "title": "Псалом 70. (70)", "subtitle": "", "verses": [{"num": "1.", "text": "На Тја Господи уповах, да не постижусја во вјек."}, {"num": "2.", "text": "Правдоју Твојеју избави мја, и изми мја: приклони ко мње ухо Твоје, и спаси мја."}, {"num": "3.", "text": "Буди ми в Бога зашчититеља, и в мјесто крјепко спасти мја: јако утвержденије моје, и прибјежишче моје јеси Ти."}, {"num": "4.", "text": "Боже мој, избави мја из руки грјешнаго, из руки законопреступнаго и обидјашчаго:"}, {"num": "5.", "text": "Јако Ти јеси терпјеније моје Господи, Господи упованије моје от јуности мојеја."}, {"num": "6.", "text": "В Тебје утвердихсја от утроби, от чрева матере мојеја Ти јеси мој покровитељ: о Тебје пјеније моје вину."}, {"num": "7.", "text": "Јако чудо бих многим: и Ти помошчник мој крјепок."}, {"num": "8.", "text": "Да исполњатсја уста моја хваљенија, јако да воспоју славу Твоју, вес ден великољепије Твоје."}, {"num": "9.", "text": "Не отвержи мене во времја старости: внегда оскудјевати крјепости мојеј, не остави мене."}, {"num": "10.", "text": "Јако рјеша врази моји мње, и стрегушчији душу моју совјешчаша вкупје."}, {"num": "11.", "text": "Глагољушче: Бог оставил јест јего, пожените и измите јего, јако њест избављајај."}, {"num": "12.", "text": "Боже мој не удаљисја от мене, Боже мој в помошч моју вонми."}, {"num": "13.", "text": "Да постидјатсја и изчезнут оклеветајушчији душу моју: да облекутсја в студ и срам ишчушчији злаја мње."}, {"num": "14.", "text": "Аз же всегда возуповају на Тја, и приложу на всјаку похвалу Твоју."}, {"num": "15.", "text": "Уста моја возвјестјат правду Твоју, вес ден спасеније Твоје, јако не познах књижнаја."}, {"num": "16.", "text": "Вниду в сиље Господњи: Господи, помјану правду Тебе јединаго."}, {"num": "17.", "text": "Боже мој, имже научил мја јеси от јуности мојеја, и до ниње возвјешчу чудеса Твоја:"}, {"num": "18.", "text": "И даже до старости и престарјенија, Боже мој не остави мене, дондеже возвјешчу мишцу Твоју роду всему грјадушчему."}, {"num": "19.", "text": "Силу Твоју и правду Твоју, Боже, даже до вишњих, јаже сотворил ми јеси величија, Боже, кто подобен Тебје;"}, {"num": "20.", "text": "Јелика јавил ми јеси скорби многи и зли: и обрашчасја оживотворил мја јеси, и от бездан земљи возвел мја јеси."}, {"num": "21.", "text": "Умножил јеси на мње величествије Твоје, и обрашчасја утјешил мја јеси, и от бездан земљи паки возвел мја јеси."}, {"num": "22.", "text": "Ибо аз исповјемсја Тебје в људех Господи, во сосудјех псаломских истину Твоју, Боже, воспоју Тебје в гуслех, Свјатиј Израиљев."}, {"num": "23.", "text": "Возрадујетсја устње моји, јегда воспоју Тебје, и душа моја, јуже јеси избавил:"}, {"num": "24.", "text": "Јешче же и јазик мој вес ден поучитсја правдје Твојеј, јегда постидјатсја и посрамјатсја ишчушчији злаја мње."}]}, "71": {"number": 71, "title": "Псалом 71. (71)", "subtitle": "", "verses": [{"num": "1.", "text": "Боже суд Твој цареви дажд, и иравду Твоју сину цареву:"}, {"num": "2.", "text": "Судити људем Твојим в правдје, и нишчим Твојим в судје."}, {"num": "3.", "text": "Да воспријимут гори мир људем и холми правду:"}, {"num": "4.", "text": "Судит нишчим људским, и спасет сини убогих, и смирит клеветника."}, {"num": "5.", "text": "И пребудет со солнцсм, и прежде луни рода родов."}, {"num": "6.", "text": "Снидет јако дожд на руно, и јако капља капљушчаја на земљу."}, {"num": "7.", "text": "Возсијајет во днех Јего правда, и множество мира, дондеже отиметсја луна."}, {"num": "8.", "text": "И обладајет от морја до морја, и от рјек до конец всељенија."}, {"num": "9.", "text": "Пред Њим припадут Етиопљане, и врази Јего перст полижут:"}, {"num": "10.", "text": "Царије Тарсистији и острови дари принесут, царије Аравстији и Сава дари приведут:"}, {"num": "11.", "text": "И поклоњатсја Јему вси царије земстији, вси јазици поработајут Јему."}, {"num": "12.", "text": "Јако избави нишча от силна, и убога, јемуже не бје помошчника."}, {"num": "13.", "text": "Пошчадит нишча и убога, и души убогих спасет."}, {"num": "14.", "text": "От лихви и от неправди избавит души их, и честно имја Јего пред њими."}, {"num": "15.", "text": "И жив будет, и дастсја Јему от злата Аравијска: и помољатсја о Њем вину: вес ден благословјат Јего."}, {"num": "16.", "text": "Будет утвержденије на земљи на версјех гори, превознесетсја паче Ливана плод Јего: и процвјетут от града јако трава земнаја."}, {"num": "17.", "text": "Будет имја Јего благословено во вјеки, прежде солнца пребивајет имја Јего: и благословјатсја в Њем всја кољена земнаја, вси јазици ублажат Јего."}, {"num": "18.", "text": "Благословен Господ Бог Израиљев, творјај чудеса једин."}, {"num": "19.", "text": "И благословено имја слави Јего во вјек, и во вјек вјека: и исполнитсја слави Јего всја земља: буди, буди. Слава:"}]}, "72": {"number": 72, "title": "Псалом 72. (72)", "subtitle": "", "verses": [{"num": "1.", "text": "Кољ благ Бог Израиљев, правим сердцем."}, {"num": "2.", "text": "Мој же вмаље не подвижастјесја позје, вмаље не пролијашасја стопи моја."}, {"num": "3.", "text": "Јако возревновах на безаконија, мир грјешников зрја."}, {"num": "4.", "text": "Јако њест восклоњенија в смерти их, и утвержденија в ранје их."}, {"num": "5.", "text": "В трулјех человјеческих не сут, и с человјеки не пријимут рани."}, {"num": "6.", "text": "Сего ради удержа ја гордиња их до конца, одјејашасја неправдоју и нечестијем својим."}, {"num": "7.", "text": "Изидет јако из тука неправда их, преидоша в љубов сердца."}, {"num": "8.", "text": "Помислиша и глагољаша в лукавствје, неправду в висоту глагољаша."}, {"num": "9.", "text": "Положиша на небеси уста своја, и јазик их прејде по земљи."}, {"num": "10.", "text": "Сего ради обратјатсја људије моји сјемо, и дније исполњени обрјашчутсја вњих."}, {"num": "11.", "text": "И рјеша: како увједје Бог, и ашче јест разум во Вишњем."}, {"num": "12.", "text": "Се сиј грјешници, и гобзујушчији во вјек, удержаша богатство."}, {"num": "13.", "text": "И рјех: Еда всује оправдих сердце моје, и умих в неповинених руцје моји."}, {"num": "14.", "text": "И бих јазвен вес ден, и обличеније моје на јутрених."}, {"num": "15.", "text": "Ашче глагољах, повјем тако: се роду синов твојих, јемуже објешчахсја."}, {"num": "16.", "text": "И непшчевах разумјети, сије труд јест предомноју."}, {"num": "17.", "text": "Дондеже вниду во свјатило Божије, и разумјеју в посљедњаја их."}, {"num": "18.", "text": "Обаче за лешченија их положил јеси им злаја, низложил јеси ја, внегда разгорјешасја."}, {"num": "19.", "text": "Како биша во запустјеније, внезапу изчезоша, погибоша за безаконије своје."}, {"num": "20.", "text": "Јако соније востајушчаго, Господи во градје Твојем образ их уничижиши."}, {"num": "21.", "text": "Јако разжежесја сердце моје, и утроби моја измјенишасја."}, {"num": "22.", "text": "И аз уничижен, и не разумјех, скотен бих у Тебе."}, {"num": "23.", "text": "И аз вину с Тобоју, удержал јеси руку деснују моју."}, {"num": "24.", "text": "И совјетом Твојим наставил мја јеси, и со славоју пријал мја јеси."}, {"num": "25.", "text": "Что бо ми јест на небеси, и от Тебе что восхотјех на земљи."}, {"num": "26.", "text": "Исчезе сердце моје и плот моја, Боже сердца мојего, и част моја Боже во вјек."}, {"num": "27.", "text": "Јако се удаљајушчији себе от Тебе, погибнут, потребил јеси всјакаго љубодјејушчаго от Тебе."}, {"num": "28.", "text": "Мње же приљепљатисја Богови благо јест, полагати на Господа упованије моје, возвјестити ми всја хвали Твоја во вратјех дшчере Сиони."}]}, "73": {"number": 73, "title": "Псалом 73. (73)", "subtitle": "", "verses": [{"num": "1.", "text": "Вскују Боже отринул јеси до конца, разгњевасја јарост Твоја на овци пажити Твојеја."}, {"num": "2.", "text": "Помјани сонм Твој, јегоже стјажал јеси исперва, избавил јеси жезлом достојанија Твојего, гора Сион сија, в њејже вселилсја јеси."}, {"num": "3.", "text": "Воздвигни руцје Твоји на гордињи их в конец, јелика лукавнова враг во свјатјем Твојем."}, {"num": "4.", "text": "И восхвалишасја ненавидјашчији Тја посредје праздника Твојего, положиша знаменија своја, знаменија, и не познаша."}, {"num": "5.", "text": "Јако во исходје превише, јако в дубравје древјање сјекирами разсјекоша."}, {"num": "6.", "text": "Двери јего вкупје, сјечивом и оскордом разрушиша ја."}, {"num": "7.", "text": "Возжегоша огњем свјатило Твоје, на земљи оскверниша жилишче имене Твојего."}, {"num": "8.", "text": "Рјеша в сердцје својем јужики их вкупје, придите и оставим всја праздники Божија от земљи."}, {"num": "9.", "text": "Знаменија их ме видјехом, њест ктому пророка, и нас не познајет ктому."}, {"num": "10.", "text": "Докоље Боже поносит враг, раздражит противниј имја Твоје до конца."}, {"num": "11.", "text": "Вскују отврашчајеши руку Твоју, и десницу Твоју от среди њедра Твојего в конец."}, {"num": "12.", "text": "Бог же Цар наш прежде вјека, содјела спасеније посредје земљи."}, {"num": "13.", "text": "Ти утвердил јеси силоју Твојеју море, Ти стерл јеси глави змијев во водје."}, {"num": "14.", "text": "Ти сокрушил јеси главу змијеву, дал јеси того брашно људем Етиопским."}, {"num": "15.", "text": "Ти расторгал јеси источники и потоки, Ти изсушил јеси рјеки Итамскија."}, {"num": "16.", "text": "Твој јест ден, и Твоја јест ношч, Ти совершил јеси зарју и солнце."}, {"num": "17.", "text": "Ти сотворил јеси всја предјели земљи: жатву и весну Ти создал јеси ја."}, {"num": "18.", "text": "Помјани сија: враг поноси Господеви, и људије безумнији раздражиша имја Твоје."}, {"num": "19.", "text": "Не предажд звјерјем душу исповједајушчујусја Тебје, души убогих Твојих не забуди до конца."}, {"num": "20.", "text": "Призри на завјет Твој, јако исполнишасја помраченији земљи домов безакониј."}, {"num": "21.", "text": "Да не возвратитсја смирениј посрамљен, нишч и убог восхвалит имја Твоје."}, {"num": "22.", "text": "Востани Боже, суди прју Твоју, помјани поношеније Твоје, јеже безумнаго вес ден."}, {"num": "23.", "text": "Не забуди гласа молитвеник Твојих, гордиња ненавидјашчих Тја взиде вину. Слава:"}]}, "74": {"number": 74, "title": "Псалом 74. (74)", "subtitle": "", "verses": [{"num": "1.", "text": "Исповјемсја Тебје Боже, исповјемсја Тебје, и призовем имја Твоје, повјем всја чудеса Твоја."}, {"num": "2.", "text": "Јегда пријиму времја, Аз правоти возсужду."}, {"num": "3.", "text": "Растајасја земља и вси живушчији на њеј, Аз утвердих столпи јеја."}, {"num": "4.", "text": "Рјех безаконујушчим, не безаконујте, и согрјешајушчим, не возносите рога."}, {"num": "5.", "text": "Не воздвизајте на висоту рога вашего, и не глагољите на Бога неправду."}, {"num": "6.", "text": "Јако ниже от исход, ниже от запад, ниже од пустих гори."}, {"num": "7.", "text": "Јако Бог судија јест, сего смирајет, и сего возносит."}, {"num": "8.", "text": "Јако чаша в руцје Господњи, вина нерастворена, исполн растворенија, и уклони от сеја в сију: обаче дрождије јего не истошчисја, испијут вси грјешнији земљи."}, {"num": "9.", "text": "Аз же возрадујусја во вјек, воспоју Богу Јаковљу."}, {"num": "10.", "text": "И всја роги грјешних сломљу, и вознесетсја рог праведнаго."}]}, "75": {"number": 75, "title": "Псалом 75. (75)", "subtitle": "", "verses": [{"num": "1.", "text": "Вједом во Јудеји Бог, во Израиљи велије имја Јего."}, {"num": "2.", "text": "И бист в мирје мјесто Јего, и жилишче Јего во Сиоње."}, {"num": "3.", "text": "Тамо сокруши крјепости луков, оружије и меч и бран."}, {"num": "4.", "text": "Просвјешчајеши ти дивно от гори вјечних."}, {"num": "5.", "text": "Смјатошасја вси неразумнији сердцем, уснуша сном својим, и ничтоже обрјетоша вси мужије богатства в руках својих."}, {"num": "6.", "text": "От запрешченија Твојего Боже Јаковаљ, воздремаша всједшији на коњи."}, {"num": "7.", "text": "Ти страшен јеси, и кто противстанет Тебје, отоље гњев Твој."}, {"num": "8.", "text": "С небесе слишан сотворил јеси суд, земља убојасја и умолча."}, {"num": "9.", "text": "Внегда востати на суд Богу, спасти всја кроткија земљи."}, {"num": "10.", "text": "Јако помишљеније человјеческоје исповјестсја Тебје, и останок помишљенија празднујет Ти."}, {"num": "11.", "text": "Помолитесја и воздадите Господеви Богу нашему, вси иже окрест Јего принесут дари."}, {"num": "12.", "text": "Страшному и отемљајушчему духи књазеј, страшному паче цареј земних."}]}, "76": {"number": 76, "title": "Псалом 76. (76)", "subtitle": "", "verses": [{"num": "1.", "text": "Гласом мојим ко Господу возвах, гласом мојим к Богу, и вњат ми."}, {"num": "2.", "text": "В ден скорби мојеја Бога взисках рукама мојима, ношчију пред Њим, и не прелешчен бих, отвержесја утјешитисја душа моја."}, {"num": "3.", "text": "Помјанух Бога, и возвеселихсја, поглумљахсја, и малодушестоваше дух мој."}, {"num": "4.", "text": "Предваристје стражби очи моји, смјатохсја и не глагољах."}, {"num": "5.", "text": "Помислих дни первија, и љета вјечнаја помјанух, и поучахсја."}, {"num": "6.", "text": "Ношчију сердцем мојим глумљахсја, и тужаше дух мој."}, {"num": "7.", "text": "Еда во вјеки отринут Господ, и не приложит благоволити паки."}, {"num": "8.", "text": "Или до конца милост своју отсјечет, сконча глагол от рода в род."}, {"num": "9.", "text": "Еда забудет ушчедрити Бог, или удержит во гњевје својем шчедроти своја."}, {"num": "10.", "text": "И рјех: ниње начах, сија измјена десници Вишњаго."}, {"num": "11.", "text": "Помјанух дјела Господња, јако помјану от начала чудеса Твоја."}, {"num": "12.", "text": "И поучусја во всјех дјељех Твојих, и в начинанијих Твојих поглумљусја."}, {"num": "13.", "text": "Божс во свјатјем пут Твој, кто Бог велиј јако Бог наш."}, {"num": "14.", "text": "Ти јеси Бог творјај чудеса, сказал јеси в људех силу Твоју."}, {"num": "15.", "text": "Избавил јеси мишцеју Твојеју људи Твоја, сини Јаковљи и Јосифови."}, {"num": "16.", "text": "Видјеша Тја води Боже, видјеша Тја води, и убојашасја, смјатошасја бездни."}, {"num": "17.", "text": "Множество шума води, глас даша облаци, ибо стрјели Твоја преходјат."}, {"num": "18.", "text": "Глас грома Твојего в колеси, освјетиша молнија Твоја всељенују, подвижесја и трепетна бист земља."}, {"num": "19.", "text": "В мори путије Твоји, и стези Твоји во водах многих, и сљеди Твоја не познајутсја."}, {"num": "20.", "text": "Наставил јеси јако овци људи Твоја, рукоју Мојсијевоју и Аронеју. Слава:"}]}, "77": {"number": 77, "title": "Псалом 77. (77)", "subtitle": "", "verses": [{"num": "1.", "text": "Внемљите људије моји закону мојему, приклоните ухо ваше во глаголи уст мојих."}, {"num": "2.", "text": "Отверзу в притчах уста моја, провјешчају гананија исперва."}, {"num": "3.", "text": "Јелика слишахом и познахом ја, и оци наши повједаша нам."}, {"num": "4.", "text": "Не утајишасја от чад их в род ин, возвјешчајушче хвали Господњи, и сили Јего, и чудеса Јего јаже сотвори."}, {"num": "5.", "text": "И воздвиже свидјеније во Јаковје, и закон положи во Израиљи, јелика заповједа оцем нашим, сказати ја синовом својим."}, {"num": "6.", "text": "Јако да познајет род ин синове родјашчијисја, и востанут и повједјат ја синовом својим."}, {"num": "7.", "text": "Да положат на Бога упованије своје, и не забудут дјел Божијих, и заповједи Јего взишчут."}, {"num": "8.", "text": "Да не будут јакоже оци их род строптив и преогорчевајај, род иже исправи сердца својего, и не у вјери с Богом духа својего."}, {"num": "9.", "text": "Синове Јефремли наљацајушче и стрјељајушче луки, возвратишасја в ден брани."}, {"num": "10.", "text": "Не сохраниша завјета Божија, и в закоње Јего не восхотјеша ходити."}, {"num": "11.", "text": "И забиша благодјејанија Јего, и чудеса, иже показа им."}, {"num": "12.", "text": "Пред оци их, јаже сотвори чудеса, в земљи Египетстјеј на пољи Танеосје."}, {"num": "13.", "text": "Разверзе море, и проведе их, пристави води јако мјех."}, {"num": "14.", "text": "И настави ја облаком во дни, и всју ношч просвјешченијем огња."}, {"num": "15.", "text": "Разверзе камен в пустињи, и напоји ја јако в бездње мнозје."}, {"num": "16.", "text": "И изведе воду из камене, и низведе јако рјеки води."}, {"num": "17.", "text": "И приложиша јешче согрјешати Јему, преогорчиша Вишњаго в безводњеј."}, {"num": "18.", "text": "И искусиша Бога в сердцах својих, воспросити брашна душам својим."}, {"num": "19.", "text": "И клеветаша па Бога, и рјеша: Еда возможет Бог уготовати трапезу в пустињи."}, {"num": "20.", "text": "Понеже порази камен, и потекоша води, и потоци наводнишасја, еда и хљеб може дати, или уготовати трапезу људем својим."}, {"num": "21.", "text": "Сего ради слиша Господ и презрје, и огањ возгорјесја во Јаковје, и гњев взиде на Израиља."}, {"num": "22.", "text": "Јако не вјероваша Богови, ниже уповаша на спасеније Јего."}, {"num": "23.", "text": "И заповједа облаком свише, и двери небесе отверзе."}, {"num": "24.", "text": "И одожди им ману јасти, и хљеб небесниј даде им."}, {"num": "25.", "text": "Хљеб ангелскиј јаде человјек, брашно посла им до ситости."}, {"num": "26.", "text": "Воздвиже југ с небесе, наведе силоју својеју Лива."}, {"num": "27.", "text": "И одожди на ња јако прах плоти, и јако песок морскиј птици пернати."}, {"num": "28.", "text": "И нападоша посредје стана их, и окрест жилишч их."}, {"num": "29.", "text": "И јадоша и наситишасја зјело, и желаније их принесе им."}, {"num": "30.", "text": "Не лишишасја от желанија својего, јешче брашну сушчу во устјех их."}, {"num": "31.", "text": "И гњев Божиј взиде на ња, и уби множајшаја их, и избраним Израиљевим запјат."}, {"num": "32.", "text": "Во всјех сих согрешиша јешче, и не вјероваша чудесем Јего."}, {"num": "33.", "text": "И исчезоша в сујетје дније их, и љета их со тшчанијем."}, {"num": "34.", "text": "Јегда убиваше ја, тогда взискаху Јего, и обрашчахусја, јутрењеваху к Богу."}, {"num": "35.", "text": "И помјануша, јако Бог помошчник им јест, и Бог Вишњиј избавитељ им јест."}, {"num": "36.", "text": "И возљубиша Јего уст својими, и јазиком својим солгаша Јему."}, {"num": "37.", "text": "Сердце же их не бје право с Њим, ниже увјеришасја в завјетје Јего."}, {"num": "38.", "text": "Тој же јест шчедар, очистит грјехи их, и не растлит, и умножит отвратити јарост своју, и не разжежет всего гњева својего."}, {"num": "39.", "text": "И помјану, јако плот сут, дух ходјај и не обрашчајајсја."}, {"num": "40.", "text": "Кољ крати преогорчиша Јего в пустињи, прогњеваша Јего в земљи безводњеј."}, {"num": "41.", "text": "И обратишасја, и искусиша Бога, и свјатаго Израиљева раздражиша."}, {"num": "42.", "text": "И не помјануша руки Јего в ден, в оњже избави ја из руку оскорбљајушчаго."}, {"num": "43.", "text": "Јакоже положи во Египтје знаменија своја, и чудеса своја на поли Танеосје."}, {"num": "44.", "text": "И преложи в кров рјеки их, и источники их, јако да не пијут."}, {"num": "45.", "text": "Посла на ња песија мухи, и појадоша ја, и жаби и растли ја."}, {"num": "46.", "text": "И даде ржје плоди их, и труди их пругом."}, {"num": "47.", "text": "Уби градом виногради их, и черничије их сланоју."}, {"num": "48.", "text": "И предаде граду скоти их, и имјеније их огњу."}, {"num": "49.", "text": "Посла на ња гњев јарости својеја, јарост и гњев и скорб, посланије ангели љутими."}, {"num": "50.", "text": "Путесотвори стезју гњеву својему, и не пошчадје от смерти души их, и скоти их в смерти закључи."}, {"num": "51.", "text": "И порази всјакоје первородноје в земљи Египетстјеј, начаток всјакаго труда их в сељенијих Хамових."}, {"num": "52.", "text": "И воздвиже јако овци људи своја, и возведе ја јако стадо в пустињи."}, {"num": "53.", "text": "И настави ја на упованије, и не убојашасја, и враги их покри море."}, {"num": "54.", "text": "И воведе ја в гору свјатињи својеја, гору сију, јуже стјажа десница Јего."}, {"num": "55.", "text": "И изгна от лица их јазики, и по жребију даде им земљу ужем жребодајанија, и всели в сељенијих их кољена Израиљева."}, {"num": "56.", "text": "И искусиша и преогорчиша Бога Вишњаго, и свидјенији Јего не сохраниша."}, {"num": "57.", "text": "И отвратишасја, и отвергошасја јакоже и оци их, превратишасја в лук разврашчен."}, {"num": "58.", "text": "И прогњеваша Јего в холмјех својих, и во истуканих својих раздражиша Јего."}, {"num": "59.", "text": "Слиша Бог и презрје, и уничижи зјело Израиља."}, {"num": "60.", "text": "И отрину скинију Силомскују, сељеније јеже вселисја в человјецјех."}, {"num": "61.", "text": "И предаде в пљен крјепост их, и доброту их в руки врагов."}, {"num": "62.", "text": "И затвори в оружији људи своја, и достојаније своје презрје."}, {"num": "63.", "text": "Јуноши их појаде огањ, и дјеви их не осјетовани биша."}, {"num": "64.", "text": "Свјашченици их мечем падоша, и вдовици их не оплакани будут."}, {"num": "65.", "text": "И воста јако спја Господ, јако силен и шумен от вина."}, {"num": "66.", "text": "И порази враги своја вспјат, поношеније вјечноје даде им."}, {"num": "67.", "text": "И отрину сељеније Јосифово, и кољено Јефремово не избра."}, {"num": "68.", "text": "И избра кољено Јудово, гору Сиоњу, јуже возљуби."}, {"num": "69.", "text": "И созда јако јединорога свјатилишче своје, на земљи основа их во вјек."}, {"num": "70.", "text": "И избра Давида раба својего, и воспријат Јего от стада овчих."}, {"num": "71.", "text": "От дојилица појаг јего, пасти Јакова раба својего, и Израиља достојаније своје."}, {"num": "72.", "text": "И упасе ја в незлобији сердца својего, и в разумјех руку својеју наставил ја јест. Слава:"}]}, "78": {"number": 78, "title": "Псалом 78. (78)", "subtitle": "", "verses": [{"num": "1.", "text": "Боже пријидоша јазици в достојаније Твоје, оскверниша храм свјатиј Твој."}, {"num": "2.", "text": "Положиша Јерусалим јако овошченоје хранилишче, положиша трупија раб Твојих брашно птицам небесним, плоти преподобних Твојих звјерем земним."}, {"num": "3.", "text": "Пролијаша кров их јако воду окрест Јерусалима, и не бје погребајај."}, {"num": "4.", "text": "Бихом поношеније сосједом нашим, подраженије и поруганије сушчим окрест нас."}, {"num": "5.", "text": "Докоље Господи прогњевајешисја до конца, разжежетсја јако огањ рвеније Твоје."}, {"num": "6.", "text": "Пролеј гњев Твој на јазики незнајушчија Тебе, и на царствија, јаже имене Твојего не призваша."}, {"num": "7.", "text": "Јако појадоша Јакова, и мјесто јего опустошиша."}, {"num": "8.", "text": "Не помјани наших безаконије первих, скоро да предварјат ни шчедроти Твоја Господи, јако обнишчахом зјело."}, {"num": "9.", "text": "Помози нам Боже Спаситељу наш, слави ради имене Твојего, Господи избави ни, и очисти грјехи нашја имене ради Твојего."}, {"num": "10.", "text": "Да не когда рекут јазици: Гдје јест Бог их, и да увјестсја во јазицјех пред очима нашим отмишченија крове раб Твојих пролитија."}, {"num": "11.", "text": "Да внидет пред Тја воздиханије окованих, по величију мишци Твојеја снабди сини умершчвљених."}, {"num": "12.", "text": "Воздажд сосједом нашим седмерицеју в њедро их поношеније их, имже поносиша Тја Господи."}, {"num": "13.", "text": "Ми же људије Твоји и овци пажити Твојеја исповјемсја Тебје Боже во вјек, в род и род возвјестим хвалу Твоју."}]}, "79": {"number": 79, "title": "Псалом 79. (79)", "subtitle": "", "verses": [{"num": "1.", "text": "Пасиј Израиља вонми, настављајај јако овча Јосифа, сједјај на херувимјех јависја."}, {"num": "2.", "text": "Пред Јефремом и Венијамином, и Манасијем воздвигни силу Твоју, и пријиди во јеже спасти нас."}, {"num": "3.", "text": "Боже обрати ни, и просвјети лице Твоје, и спасемсја."}, {"num": "4.", "text": "Господи Боже сил, докоље гњевајешисја на молитву раб Твојих."}, {"num": "5.", "text": "Напитајеши нас хљебом слезним, и напојиши нас слезами в мјеру."}, {"num": "6.", "text": "Положил јеси нас в прерјеканије сосједом нашим, и врази иаши подражиша ни."}, {"num": "7.", "text": "Господи Боже сил обрати ни, и просвјети лице Твоје, и спасемсја."}, {"num": "8.", "text": "Виноград из Египта пренесал јеси, изгнал јеси јазики, и насадил јеси их."}, {"num": "9.", "text": "Путесотворил јеси пред њим, и насадил јеси коренија јего, и исполни земљу."}, {"num": "10.", "text": "Покри гори сјен јего, и вјетвија јего кедри Божија."}, {"num": "11.", "text": "Простре розги јего до морја, и даже до рјек отрасли јего."}, {"num": "12.", "text": "Вскују низложил јеси оплот јего, и обимајут и вси мимоходјашчији путем."}, {"num": "13.", "text": "Озоба и вепар от дубрави, и уједињениј дивиј појаде их."}, {"num": "14.", "text": "Боже сил обратисја убо, и призри с небесе и вижд, и посјети виноград сеј."}, {"num": "15.", "text": "И соверши их, јегоже насади десница Твоја, и на сина человјеческаго, јегоже укрјепил јеси себје."}, {"num": "16.", "text": "Пожежен огњем и раскопан, от запрешченија лица Твојего погибнут."}, {"num": "17.", "text": "Да будет рука Твоја на мужа десници Твојеја, и на сина человјеческаго, јегоже укрјепил јеси себје."}, {"num": "18.", "text": "И не отступим от Тебе, оживиши ни, и имја Твоје призовем."}, {"num": "19.", "text": "Господи Боже сил, обрати ни, и просвјети лице Твоје, и спасемсја."}]}, "80": {"number": 80, "title": "Псалом 80. (80)", "subtitle": "", "verses": [{"num": "1.", "text": "Радујтесја Богу помошчнику нашему, воскликните Богу Јаковљу."}, {"num": "2.", "text": "Примите псалом, и дадите тимпан, псалтир красен с гуслами."}, {"num": "3.", "text": "Вострубите во новомјесјачији трубоју, во благознаменитиј ден праздника вашего."}, {"num": "4.", "text": "Јако повељеније Израиљево јест, и судба Богу Јаковљу."}, {"num": "5.", "text": "Свидјеније во Јосифје положи је, внегда изити јему от земљи Египетскија, јазика, јегоже не вједјаше, услиша."}, {"num": "6.", "text": "Отјат от времене хребет јего, руцје јего в коши поработастје."}, {"num": "7.", "text": "В скорби призвал Мја јеси, и избавих тја, услишах тја в тајње бурње, искусих тја на водје прерјеканија."}, {"num": "8.", "text": "Слишите људије Моји, и засвидјетељстују вам Израиљу, ашче послушајеши Мене."}, {"num": "9.", "text": "Не будет тебје бог нов, ниже поклонишасја богу чуждему."}, {"num": "10.", "text": "Аз бо јесам Господ Бог твој, изведиј тја от земљи Египетскија, разшири уста твоја, и исполњу ја."}, {"num": "11.", "text": "И не послушаша људије Моји гласа Мојего, и Израиљ не вњат Ми."}, {"num": "12.", "text": "И отпустих ја по начинанијем сердец их, појдут в начинанијих својих."}, {"num": "13.", "text": "Ашче биша људије Моји послушали Мене, Израиљ ашче би в пути Моја ходил."}, {"num": "14.", "text": "Ни о чесом же убо враги јего смирил бих, и на оскорбљајушчија их возложил бих руку Моју."}, {"num": "15.", "text": "Врази Господњи солгаша Јему, и будет времја их во вјек."}, {"num": "16.", "text": "И напита их от тука пшенична, и от камене меда насити их. Слава:"}]}, "81": {"number": 81, "title": "Псалом 81. (81)", "subtitle": "", "verses": [{"num": "1.", "text": "Бог ста в сонмје богов, посредје же боги разсудит."}, {"num": "2.", "text": "Докоље судите неправду, и лица грјешников пријемљете."}, {"num": "3.", "text": "Судите сиру и убогу, смирена и нишча оправдајте."}, {"num": "4.", "text": "И измите нишча и убога, из руки грјешничи избавите јего."}, {"num": "5.", "text": "Не познаша ниже уразумјеша, во тамје ходјат, да подвижатсја всја основанија земљи."}, {"num": "6.", "text": "Аз рјех: Бози јесте и синове Вишњаго вси."}, {"num": "7.", "text": "Ви же јако человјеци умирајете, и јако једин от књазеј падајете."}, {"num": "8.", "text": "Воскресни Боже, суди земљи, јако Ти наследиши во всјех јазицјех."}]}, "82": {"number": 82, "title": "Псалом 82. (82)", "subtitle": "", "verses": [{"num": "1.", "text": "Боже, кто уподобитсја Тебје, не премолчи, ниже укроти Боже."}, {"num": "2.", "text": "Јако се врази Твоји возшумјеша, и ненавидјашчији Тја воздвигоша главу."}, {"num": "3.", "text": "На људи Твоја лукавноваша вољеју, и совјешчаша на свјатија Твоја."}, {"num": "4.", "text": "Рјеша: Пријидите и потребим ја от јазик, и не помјанетсја имја Израиљево ктому."}, {"num": "5.", "text": "Јако совјешчаша јединомишљенијем вкупје, на Тја завјет завјешчаша."}, {"num": "6.", "text": "Сељенија Идумејска и Исмаилите, Моав и Агарјане."}, {"num": "7.", "text": "Гевал и Амон и Амалик, иноплеменици с живушчими в Тирје."}, {"num": "8.", "text": "Ибо и Асур пријде с њими, биша в заступљеније синовом Лотовим."}, {"num": "9.", "text": "Сотвори им јако Мадијаму и Сисарје, јако Јавиму в потоцје Кисовје."}, {"num": "10.", "text": "Потребишасја во Аендорје, биша јако гној земниј."}, {"num": "11.", "text": "Положи књази их јако Орива и Зива, Зевсја и Салмана всја књази их."}, {"num": "12.", "text": "Иже рјеша, да насљедим себје свјатилишче Божије."}, {"num": "13.", "text": "Боже мој, положи ја јако коло, јако трост пред лицем вјетра."}, {"num": "14.", "text": "Јако огањ попаљај дубрави, јако пламен пожигајај гори."}, {"num": "15.", "text": "Тако поженеши ја буреју Твојеју, и гњевом Твојим смјатешија."}, {"num": "16.", "text": "Исполни лица их безчестија, и взишчут имене Твојего Господи."}, {"num": "17.", "text": "Да постидјатсја и смјатутсја во вјек вјека, и посрамјатсја и погибнут."}, {"num": "18.", "text": "И да познајут, јако имја Тебје Господ, Ти једин Вишњиј по всеј земљи."}]}, "83": {"number": 83, "title": "Псалом 83. (83)", "subtitle": "", "verses": [{"num": "1.", "text": "Кољ возљубљена сељенија Твоја Господи сил."}, {"num": "2.", "text": "Желајет и скончавајетсја душа моја во двори Господњи, сердце моје и плот моја возрадовастасја о Бозје живје."}, {"num": "3.", "text": "Ибо птица обрјете себје храмину, и горлица гњездо себје, идјеже положит птенци своја, олтари Твоја Господи сил, Царју мој и Боже мој."}, {"num": "4.", "text": "Блажени живушчији в дому Твојем, во вјеки вјеков восхваљат Тја."}, {"num": "5.", "text": "Блажен муж, јемуже јест заступљеније јего у Тебе, восхожденија в сердцје својем положи."}, {"num": "6.", "text": "Во јудол плачевнују, во мјесто јеже положи, ибо благословеније даст законополагајај."}, {"num": "7.", "text": "Појдут от сили в силу, јавитсја Бог богов в Сиоње."}, {"num": "8.", "text": "Господи Боже сил, услиши молитву моју, внуши Боже Јаковаљ."}, {"num": "9.", "text": "Зашчитниче наш вижд Боже, и призри на лице Христа Твојего."}, {"num": "10.", "text": "Јако лучше ден једин во дворјех Твојих паче тисјашч, изволих приметатисја в дому Бога мојего паче, неже жити ми в сељенијих грјешничих."}, {"num": "11.", "text": "Јако милост и истину љубит Господ Бог, благодат и славу даст, Господ не лишит благих, ходјашчих незлобијем."}, {"num": "12.", "text": "Господи Боже сил, блажен человјек уповајај на Тја."}]}, "84": {"number": 84, "title": "Псалом 84. (84)", "subtitle": "", "verses": [{"num": "1.", "text": "Благоволил јеси Господи земљу Твоју, возвратил јеси пљен Јаковаљ."}, {"num": "2.", "text": "Оставил јеси безаконија људеј Твојих, покрил јеси всја грјехи их."}, {"num": "3.", "text": "Укротил јеси вес гњев Твој, возвратилсја јеси от гњева јарости Твојеја."}, {"num": "4.", "text": "Возврати нас Боже спасениј наших, и отврати јарост Твоју от нас."}, {"num": "5.", "text": "Еда во вјеки прогњевајешисја на ни, или простреши гњев Твој от рода в род."}, {"num": "6.", "text": "Боже, Ти обрашчасја оживиши ни, и људије Твоји возвесељатсја о Тебје."}, {"num": "7.", "text": "Јави нам Господи милост Твоју, и спасеније Твоје дажд нам."}, {"num": "8.", "text": "Услишу, что речет о мње Господ Бог, јако речет мир на људи своја, и на преподобнија своја, и на обрашчајушчија сердца к Њему."}, {"num": "9.", "text": "Обаче близ бојашчихсја Јего спасеније Јего, вселити славу в земљу нашу."}, {"num": "10.", "text": "Милост и истина сретостјесја, правда и мир облобизастасја."}, {"num": "11.", "text": "Истина от земљи возсија, и правда с небесе приниче."}, {"num": "12.", "text": "Ибо Господ даст благост, и земља наша даст плод свој."}, {"num": "13.", "text": "Правда пред Њим предидет, и положит пут стопи своја. Слава:"}]}, "85": {"number": 85, "title": "Псалом 85. (85)", "subtitle": "", "verses": [{"num": "1.", "text": "Приклони Господи ухо Твоје, и услиши мја, јако нишч и убог јесам аз."}, {"num": "2.", "text": "Сохрани душу моју, јако преподобен јесам, спаси раба Твојего Боже мој, уповајушчаго на Тја."}, {"num": "3.", "text": "Помилуј мја Господи, јако к Тебје возову вес ден."}, {"num": "4.", "text": "Возвесели душу раба Твојего, јако к Тебје взјах душу моју."}, {"num": "5.", "text": "Јако Ти Господи благ и кроток и многомилостив всјем призивајушчим Тја."}, {"num": "6.", "text": "Внуши Господи молитву моју, и вонми гласу мољенија мојего."}, {"num": "7.", "text": "В ден скорби мојеја возвах к Тебје, јако услишал мја јеси."}, {"num": "8.", "text": "Њест подобен Тебје в бозјех Господи, и њест по дјелом Твојим."}, {"num": "9.", "text": "Вси јазици, јелики сотворил јеси, пријдут и поклоњатсја пред Тобоју Господи, и прослављат имја Твоје."}, {"num": "10.", "text": "Јако велиј јеси Ти, и творјај чудеса, Ти јеси Бог једин."}, {"num": "11.", "text": "Настави мја Господи на пут Твој, и појду во истиње Твојеј, да возвеселитсја сердце моје бојатисја имене Твојего."}, {"num": "12.", "text": "Исповјемсја Тебје Господи Боже мој всјем сердцем мојим, и прослављу имја Твоје во вјек."}, {"num": "13.", "text": "Јако милост Твоја велија на мње, и избавил јеси душу моју от ада преисподњејшаго."}, {"num": "14.", "text": "Боже законопреступници восташа на мја, и сонм державних взискаша душу моју, и не предложиша Тебе пред собоју."}, {"num": "15.", "text": "И Ти Господи Боже мој шчедриј и милостивиј, долготерпјељивиј и истиниј."}, {"num": "16.", "text": "Призри на мја, и помилуј мја, дажд державу Твоју отроку Твојему, и спаси сина раби Твојеја."}, {"num": "17.", "text": "Сотвори со мноју знаменије во благо, и да видјат ненавидјашчији мја, и постидјатсја, јако Ти Господи помогал ми и утјешил мја јеси."}]}, "86": {"number": 86, "title": "Псалом 86. (86)", "subtitle": "", "verses": [{"num": "1.", "text": "Основанија јего на горјах свјатих, љубит Господ врата Сиоња паче всјех сељениј Јаковљих."}, {"num": "2.", "text": "Преславнаја глагољашасја о тебје граде Божиј."}, {"num": "3.", "text": "Помјану Раав и Вавилона вједјушчим мја, и се иноплеменици, и Тир и људије Етиопстији, сији биша тамо."}, {"num": "4.", "text": "Мати Сион речет: Человјек и чсловјек родисја в њем, и тој основа Вишњиј."}, {"num": "5.", "text": "Господ повјест в писанији људеј, и књазеј, сих бивших в њем."}, {"num": "6.", "text": "Јако весељашчихсја всјех жилишче в тебје."}]}, "87": {"number": 87, "title": "Псалом 87. (87)", "subtitle": "", "verses": [{"num": "1.", "text": "Господи Боже спасенија мојего, во дни возвах, и во ношчи пред Тобоју."}, {"num": "2.", "text": "Да внидет пред Тја молитва моја, приклони ухо Твоје к мољенију мојему."}, {"num": "3.", "text": "Јако исполнисја зол душа моја, и живот мој аду приближисја."}, {"num": "4.", "text": "Привмјењен бих с нисходјашчими в ров, бих јако человјек без помошчи."}, {"num": "5.", "text": "В мертвих свобод, јако јазвенији спјашчи во гробје, ихже не помјанул јеси к тому, и тији от руки Твојеја отриновенији биша."}, {"num": "6.", "text": "Положиша мја в ровје преисподњем, в темних и сјени смертњеј."}, {"num": "7.", "text": "На мње утвердисја јарост Твоја, и всја волни Твоја навел јеси на мја."}, {"num": "8.", "text": "Удаљил јеси знаемих мојих от мене, положиша мја мерзост себје, предан бих, и не исхождах."}, {"num": "9.", "text": "Очи моји изнемогостје от нишчети, возвах к Тебје Господи вес ден, воздјех к Тебје руцје моји."}, {"num": "10.", "text": "Еда мертвими твориши чудеса, или врачеве воскресјат, и исповједјатсја Тебје."}, {"num": "11.", "text": "Еда повјест кто во гробје милост Твоју и истину Твоју в погибељи."}, {"num": "12.", "text": "Еда познана будут во тамје чудеса Твоја, и правда Твоја в земљи забвењеј."}, {"num": "13.", "text": "И аз к Тебје Господи возвах, и ујутро молитва моја предварит Тја."}, {"num": "14.", "text": "Вскују Господи отрјејеши душу моју, отврашчајеши лице Твоје от мене."}, {"num": "15.", "text": "Нишч јесам аз, и в трудјех от јуности мојеја вознесжесја смирихсја и изнемогох."}, {"num": "16.", "text": "На мње преидоша гњеви Твоји, устрашенија Твоја возмутиша мја."}, {"num": "17.", "text": "Обидоша мја као вода вес ден, одержаша мја вкупје."}, {"num": "18.", "text": "Удаљил јеси от мене друга и искренаго, и знаемих мојих от страстеј. Слава:"}]}, "88": {"number": 88, "title": "Псалом 88. (88)", "subtitle": "", "verses": [{"num": "1.", "text": "Милости Твоја Господи во вјек воспоју, в род и род возвјешчу истину Твоју уст мојими."}, {"num": "2.", "text": "Зане рекал јеси во вјек милост созиждетсја, на небесјех уготовитсја истина Твоја."}, {"num": "3.", "text": "Завјешчах завјет избраним мојим, кљахсја Давиду рабу Мојему."}, {"num": "4.", "text": "До вјека уготовају сјемја твоје, и созижду в род и род престол твој."}, {"num": "5.", "text": "Исповједјат небеса чудеса Твоја Господи, ибо истину Твоју в церкви свјатих."}, {"num": "6.", "text": "Јако кто во облацјех уравнитисја Господеви, уподобитсја Господеви в сињех Божијих."}, {"num": "7.", "text": "Бог прослављајем в совјете свјатих, велиј и страшен јест пад всјеми окрестними Јего."}, {"num": "8.", "text": "Господи Боже сил, кто подобен Тебје, силен јеси Господи, и истина Твоја окрест Тебе."}, {"num": "9.", "text": "Ти владичествујеши державоју морскоју, возмушченије же волн јего Ти укрочајеши."}, {"num": "10.", "text": "Ти смирил јеси, јако јазвена гордаго, мишцеју сили Твојеја расточил јеси враги Твоја."}, {"num": "11.", "text": "Твоја сут небеса, и Твоја јест земља, всељенују и исполњеније јеја Ти основал јеси."}, {"num": "12.", "text": "Сјевер и море Ти создал јеси, Тавор и Ермон о имени Твојем возрадујетсја."}, {"num": "13.", "text": "Твоја мишца со силоју, да укрјепитсја рука Твоја, и вознесетсја десница Твоја."}, {"num": "14.", "text": "Правда и судба уготованије престола Твојего, милост и истина предидетје пред лицем Твојим."}, {"num": "15.", "text": "Блажени људије вједушчији воскликновеније, Господи во свјетје лица Твојего појдут."}, {"num": "16.", "text": "И о имене Твојем возрадујутсја вес ден, и правдоју Твојеју вознесутсја."}, {"num": "17.", "text": "Јако похвала сили их Ти јеси, и во благовољенији Твојем вознесетсја рог наш."}, {"num": "18.", "text": "Јако Господње јест заступљеније, и свјатаго Израиљева Царја нашего."}, {"num": "19.", "text": "Тогда глагољал јеси во видјенији синовом Твојим, и рекал јеси: Положих помошч на силнаго, возиесох избранаго от људеј мојих."}, {"num": "20.", "text": "Обрјетох Давида раба Мојего, јелејем свјатим Мојим помазах јего."}, {"num": "21.", "text": "Ибо рука Моја застуиит јего, и мишца Моја укрјепит јего."}, {"num": "22.", "text": "Ничтоже успјејет враг на њего, и син безаконија не приложит озлобити јего."}, {"num": "23.", "text": "И сосјеку от лица јего враги јего, и ненавидјашчија јего побјежду."}, {"num": "24.", "text": "И истина Моја и милост Моја с њим, и о имени Мојем вознесетсја рог јего."}, {"num": "25.", "text": "И положу на мори руку јего, и па рјеках десницу јего."}, {"num": "26.", "text": "Тој призовет Мја: Отец мој јеси Ти, Бог мој, и заступник спасенија мојего."}, {"num": "27.", "text": "И Аз первенца положу јего, висока паче цареј земних."}, {"num": "28.", "text": "Во вјек сохрању јему милост Моју, и завјет Мој вјерен јему."}, {"num": "29.", "text": "И положу во вјек вјека сјемја јего, и престол јего јако дније неба."}, {"num": "30.", "text": "Ашче оставјат синове јего закон Мој, и в судбах Мојих не појдут."}, {"num": "31.", "text": "Ашче оправданија Моја оскверњат, и заповједеј Мојих не сохрањат."}, {"num": "32.", "text": "Посјешчу жезлом безаконија их, и ранами неправди их."}, {"num": "33.", "text": "Милост же Моју не разорју от њих, не преврежду во истиње Мојеј."}, {"num": "34.", "text": "Ниже оскверњу завјета Мојего, и исходјашчих от уст Мојих не отвергусја."}, {"num": "35.", "text": "Јединоју кљахсја о свјатјем Мојем, ашче Давиду солжу."}, {"num": "36.", "text": "Сјемја јего во вјек пребудет, и престол јего јако солнце предомноју."}, {"num": "37.", "text": "И јако луна совершена во вјек, и свидјетељ на небеси вјерен."}, {"num": "38.", "text": "Ти же отринул јеси, и уничижил, пегодовал јеси помазанаго Твојего."}, {"num": "39.", "text": "Разорил јеси завјет раба Твојего, осквернил јеси на земљи свјатињу јего."}, {"num": "40.", "text": "Разорил јеси всја оплоти јего, положил јеси твердаја јего страх."}, {"num": "41.", "text": "Расхишчаху јего вси мимоходјашчији путем, бист поношеније сосједом својим."}, {"num": "42.", "text": "Возвисил јеси десницу стужајушчим јему, возвеселил јеси всја враги јего."}, {"num": "43.", "text": "Отвратил јеси помошч меча јего, и не заступил јеси јего во брани."}, {"num": "44.", "text": "Разорил јеси от очишченија јего, престол јего на земљу повергал јеси."}, {"num": "45.", "text": "Умалил јеси дни времене јего, облијал јеси јего студом."}, {"num": "46.", "text": "Докоље Господи отврашчајешисја в конец, разжежетсја јако огањ гњев Твој."}, {"num": "47.", "text": "Помјани, кији мој состав, еда во всује создал јеси всја сини человјеческија."}, {"num": "48.", "text": "Кто јест человјек, иже поживет, и не узрит смерти, избавит душу своју из руку адови."}, {"num": "49.", "text": "Гдје сут милости Твоја древнија Господи, имиже кљалсја јеси Давиду во истиње Твојеј."}, {"num": "50.", "text": "Помјани Господи поношеније раб Твојих, јеже удержах во њедрје мојем многих јазик."}, {"num": "51.", "text": "Имже поносиша врази Твоји Господи, имже поносиша измјењенију Христа Твојего."}, {"num": "52.", "text": "Благословен Господ во вјек, буди, буди. Слава:"}]}, "89": {"number": 89, "title": "Псалом 89. (89)", "subtitle": "", "verses": [{"num": "1.", "text": "Господи прибјежишче бил јеси нам в род и род."}, {"num": "2.", "text": "Прежде даже горам не бити, и создатисја земљи и вселењеј, и от вјека и до вјека Ти јеси."}, {"num": "3.", "text": "Не отврати человјека во смиреније, и рекал јеси: Обратитесја синове человјечестији."}, {"num": "4.", "text": "Јако тисјашча љет пред очима Твојима Господи, јако ден вчерашниј, иже мимо иде, и стража ношчнаја."}, {"num": "5.", "text": "Уничиженија их љета будут, јутро јако трава мимо идет, јутро процвјетет и прејдет, на вечер отпадет, и ожестјејет и изсхнет."}, {"num": "6.", "text": "Јако изчезохом гњевом Твојим, и јаростију Твојеју смутихомсја."}, {"num": "7.", "text": "Положил јеси безаконија наша пред Тобоју, вјек наш во просвјешченије лица Твојего."}, {"num": "8.", "text": "Јако вси дније наши оскудјеша, и гњевом Твојим исчезохом."}, {"num": "9.", "text": "Љета наша јако паучина поучахусја, дније љет наших, в њихже седамдесјат љет, ашче же в силах, осамдесјат љет, и множаје их труд и бољезан, јако пријиде кротост на ни и накажемсја."}, {"num": "10.", "text": "Кто вјест державу гњева Твојего, и от страха Твојего јарост Твоју исчести."}, {"num": "11.", "text": "Десницу Твоју тако скажи ми, и окованија сердцем в мудрости."}, {"num": "12.", "text": "Обратисја Господи, докоље, и умољен буди на раби Твоја."}, {"num": "13.", "text": "Исполнихомсја зајутра милости Твојеја Господи, и возрадовахомсја и возвеселихомсја."}, {"num": "14.", "text": "Во всја дни нашја возвеселихомсја, за дни в њаже смирил ни јеси, љета в њаже видјехом злаја."}, {"num": "15.", "text": "И призри на раби Твоја, и на дјела Твоја, и настави сини их."}, {"num": "16.", "text": "И буди свјетлост Господа Бога нашего на нас, и дјела руку наших исправи на нас, и дјело руку наших исправи."}]}, "90": {"number": 90, "title": "Псалом 90. (90)", "subtitle": "", "verses": [{"num": "1.", "text": "Живиј в помошчи Вишњаго, в кровје Бога небеснаго водворитсја."}, {"num": "2.", "text": "Речет Господеви: Заступник мој јеси и прибјежишче моје, Бог мој, и уповају на Њего."}, {"num": "3.", "text": "Јако Тој избавит Тја от сјети ловчи, и от словесе мјатежна."}, {"num": "4.", "text": "Плешчма својима осјенит тја, и под криље Јего надјејешисја, оружијем обидет тја истина Јего."}, {"num": "5.", "text": "Не убојишисја от страха ношчнаго, от стрјели летјашчија во дни."}, {"num": "6.", "text": "От вешчи во тамје преходјашчија, от срјашча и бјеса полуденаго."}, {"num": "7.", "text": "Падет от страни твојеја тисјашча, и тма одеснују тебе, к тебје же не приближитсја."}, {"num": "8.", "text": "Обаче очима твојима смотриши, и воздајаније грјешников узриши."}, {"num": "9.", "text": "Јако Ти Господи упованије моје, Вишњаго положил јеси прибјежишче Твоје."}, {"num": "10.", "text": "Не пријдет к Тебје зло, и рана не приближитсја тјелеси Твојему."}, {"num": "11.", "text": "Јако ангелом својим заповјест о Тебје, сохранити Тја во всјех путех Твојих."}, {"num": "12.", "text": "На руках возмут Тја, да не когда преткнеши о камен ногу Твоју."}, {"num": "13.", "text": "На аспида и василиска наступиши, и попереши лава и змија."}, {"num": "14.", "text": "Јако на Мја упова, и избављу их, покрију их, јако позна имја Моје."}, {"num": "15.", "text": "Возовет ко Мње, и услишу јего, с њим јесам в скорби, изму јего, и прослављу јего."}, {"num": "16.", "text": "Долготоју днеј исполњу јего, и јављу јему спасеније Моје. Слава:"}]}, "91": {"number": 91, "title": "Псалом 91. (91)", "subtitle": "", "verses": [{"num": "1.", "text": "Благо јест исповједатисја Господеви, и пјети имени Твојему Вишњиј."}, {"num": "2.", "text": "Возвјешчати зајутра милост Твоју, и истину Твоју на всјаку ношч."}, {"num": "3.", "text": "В десјатоструњем псалтири с пјеснију в гуслех."}, {"num": "4.", "text": "Јако возвеселил мја јеси Господи во творенији Твојем, и во дјељех руку Твојеју возрадујусја,"}, {"num": "5.", "text": "Јако возвеличишасја дјела Твоја Господи, зјело углубишасја помишљенија Твоја."}, {"num": "6.", "text": "Муж безумен не познајет, и неразумив не разумјет сих."}, {"num": "7.", "text": "Внегда прозјабоша грјешници јако трава, и проникоша вси дјелајушчији безаконије, јако да потребјатсја во вјек вјека."}, {"num": "8.", "text": "Ти же Вишњиј во вјек Господи."}, {"num": "9.", "text": "Јако се врази Твоји Господи, јако се врази Твоји погибнут, и разидутсја вси дјелајушчији безаконије."}, {"num": "10.", "text": "И вознесетсја јако јединорога рог мој, и старост моја во јелеј маститје."}, {"num": "11.", "text": "И возрје око моје на враги моја, и востајушчија на мја лукавнујушчија услишит ухо моје."}, {"num": "12.", "text": "Праведник јако финик процвјетет, јако кедар, иже в Ливање, умножитсја."}, {"num": "13.", "text": "Насаждени в дому Господњи, во дворјех Бога нашего процвјетут."}, {"num": "14.", "text": "Јешче умножатсја в старости маститје, и благопријемљушче будут."}, {"num": "15.", "text": "Да возвјестјат, јако прав Господ Бог наш, и њест неправди в Њем."}]}, "92": {"number": 92, "title": "Псалом 92. (92)", "subtitle": "", "verses": [{"num": "1.", "text": "Господ воцарисја, в љепоту облечесја, облечесја Господ в силу и препојасасја, ибо утверди всељенују, јаже не подвижитсја."}, {"num": "2.", "text": "Готов престол Твој отоље, от вјека Ти јеси."}, {"num": "3.", "text": "Воздвигоша рјеки Господи, воздвигоша рјеки гласи своја."}, {"num": "4.", "text": "Возмут рјеки сотренија своја, от гласов вода многих."}, {"num": "5.", "text": "Дивни висоти морскија, дивен во високих Господ."}, {"num": "6.", "text": "Свидјенија Твоја увјеришасја зјело, дому Твојему подобајет свјатиња Господи в долготу дниј."}]}, "93": {"number": 93, "title": "Псалом 93. (93)", "subtitle": "", "verses": [{"num": "1.", "text": "Бог отмишчениј Господ, Бог отмишчениј не обиљулсја јест."}, {"num": "2.", "text": "Вознесисја судјај земљи, воздажд воздајаније гордим."}, {"num": "3.", "text": "Докоље грјешници Господи, докоље грјешници восхваљатсја."}, {"num": "4.", "text": "Просвјешчајут и возглагољут неправду, возглагољут вси дјелајушчији безаконије."}, {"num": "5.", "text": "Људи Твоја Господи смириша, и достојаније Твоје озлобиша."}, {"num": "6.", "text": "Вдовицу и сира умориша, и пришелца убиша."}, {"num": "7.", "text": "И рјеша: Не узрит Господ, ниже уразумјејет Бог Јаковаљ."}, {"num": "8.", "text": "Разумјејте же безумнији в људех, и буији њекогда умудритесја."}, {"num": "9.", "text": "Насаждеј ухо, не слишит ли, или создавиј око, не сматрајет ли."}, {"num": "10.", "text": "Наказујај јазики, не обличит ли, учај человјека разуму."}, {"num": "11.", "text": "Господ вјест помишљенија человјеческаја, јако сут сујетна,"}, {"num": "12.", "text": "Блажен человјек, јегоже ашче накажеши Господи, и от закона Твојего научиши јего."}, {"num": "13.", "text": "Укротити јего от днеј љутих, дондеже изријетсја грјешному јама."}, {"num": "14.", "text": "Јако не отринет Господ људеј својих, и достојанија својего не оставит."}, {"num": "15.", "text": "Дондеже правда обратитсја на суд, и держашчијисја јеја вси правији сердцем."}, {"num": "16.", "text": "Кто востанет ми на лукавнујушчија, или кто предстанет ми на дјелајушчија безаконије."}, {"num": "17.", "text": "Ашче не Господ помогал би ми, вмаље вселиласја би во ад душа моја."}, {"num": "18.", "text": "Ашче глагољах, подвижесја нога моја, милост Твоја Господи помогаше ми."}, {"num": "19.", "text": "По множеству бољезнеј мојих в сердцје мојем, утјешенија Твоја возвеселиша душу моју."}, {"num": "20.", "text": "Да не прибудет Тебје престол безаконија, созидајај труд на повељеније."}, {"num": "21.", "text": "Уловјат на душу праведничу, и кров неповинују осудјат."}, {"num": "22.", "text": "И бист мње Господ в прибјежишче, и Бог мој в помошч упованија мојего."}, {"num": "23.", "text": "И воздаст им Господ безаконије их, и по лукавствију их погубит ја Господ Бог. Слава:"}]}, "94": {"number": 94, "title": "Псалом 94. (94)", "subtitle": "", "verses": [{"num": "1.", "text": "Придите возрадујемсја Господеви, воскликнем Богу Спаситељу нашему."}, {"num": "2.", "text": "Предварим лице Јего во исповједанији, и во псалмјех воскликнем Јему."}, {"num": "3.", "text": "Јако Бог велиј Господ, и Цар велиј по всеј земљи."}, {"num": "4.", "text": "Јако в руцје Јего вси конци земљи, и висоти гора Того сут."}, {"num": "5.", "text": "Јако Того јест море, и Тој сотвори је, и сушу руцје јего создастје."}, {"num": "6.", "text": "Придите поклонимсја и припадем Јему, и восплачемсја пред Господем сотворшим нас."}, {"num": "7.", "text": "Јако Тој јест Бог наш, и ми људије пажити Јего, и овци руки Јего, днес ашче глас Јего услишите."}, {"num": "8.", "text": "Не ожесточите сердец ваших, јако в прогњеванији, по дни искушенија в пустињи."}, {"num": "9.", "text": "В оњже искусиша Мја оци ваши, искусиша Мја и видјеша дјела Моја."}, {"num": "10.", "text": "Четиредесјат љет негодовах рода того, и рјех: Присно заблуждајут сердцем, тији же не познаша путеј Мојих."}, {"num": "11.", "text": "Јако кљахсја во гњевје Мојем, ашче внидут в покој Мој."}]}, "95": {"number": 95, "title": "Псалом 95. (95)", "subtitle": "", "verses": [{"num": "1.", "text": "Воспојте Господеви пјесан нову, воспојте Господеви всја земља."}, {"num": "2.", "text": "Воспојте Господеви, благословите имја Јего, благовјестите ден от дне спасеније Јего."}, {"num": "3.", "text": "Возвјестите во јазицјех славу Јего, во всјех људех чудеса Јего."}, {"num": "4.", "text": "Јако велиј Господ и хваљен зјело, страшен јест над всјеми боги."}, {"num": "5.", "text": "Јако вси бози јазик бјесове, Господ же небеса сотвори."}, {"num": "6.", "text": "Исповједаније и красота пред Њим, свјатиња и великољепије во свјатиље Јего."}, {"num": "7.", "text": "Принесите Господеви отечествија јазик, принесите Господеви славу и чест."}, {"num": "8.", "text": "Принесите Господеви славу имени Јего, возмите жертви, и входите во двори Јего."}, {"num": "9.", "text": "Поклонитесја Господеви во дворје свјатјем Јего, да подвижитсја от лица Јего всја земља."}, {"num": "10.", "text": "Реците во јазицјех, јако Господ воцарисја, ибо исправи всељенују, јаже не подвижитсја, судит људем правостију."}, {"num": "11.", "text": "Да возвесељатсја небеса, и радујетсја земља, да подвижитсја море, и исполњеније јего."}, {"num": "12.", "text": "Возрадујутсја поља, и всја јаже на њих, тогда возрадујутсја всја древа дубравнаја."}, {"num": "13.", "text": "От лица Господња, јако грјадет, јако грјадет судити земљи, судити всељењеј в правду, и људем истиноју својеју."}]}, "96": {"number": 96, "title": "Псалом 96. (96)", "subtitle": "", "verses": [{"num": "1.", "text": "Господ воцарисја, да радујетсја земља, да весељатсја острови мнози."}, {"num": "2.", "text": "Облак и мрак окрест Јего: правда и судба исправљеније престола Јего."}, {"num": "3.", "text": "Огањ пред Њим предидет, и попалит окрест враги Јего."}, {"num": "4.", "text": "Освјетиша молнија Јего всељенују, видје, и подвижесја земља."}, {"num": "5.", "text": "Гори јако восак растајаша от лица Господња, от лица Господа всеја земљи."}, {"num": "6.", "text": "Возвјестиша небеса правду Јего, и видјеша вси људије славу Јего."}, {"num": "7.", "text": "Да постидјатсја вси клањајушчијисја истуканим, хваљашчијисја о идољех својих, поклонитесја Јему вси ангели Јего."}, {"num": "8.", "text": "Слиша и возвеселисја Сион, и возрадовашасја дшчери Јудејскија, судеб ради Твојих Господи."}, {"num": "9.", "text": "Јако Ти Господ Вишњиј над всеју земљеју, зјело превознесалсја јеси над всјеми боги."}, {"num": "10.", "text": "Љубјашчији Господа, ненавидите злаја, хранит Господ души преподобних својих, из руки грјешничи избавит ја."}, {"num": "11.", "text": "Свјет возсија праведнику, и правим сердцем веселије."}, {"num": "12.", "text": "Веселитесја праведнији о Господје, и исповједајте памјат свјатињи Јего. Слава:"}]}, "97": {"number": 97, "title": "Псалом 97. (97)", "subtitle": "", "verses": [{"num": "1.", "text": "Воспојте Господеви пјесан нову, јако дивиа сотвори Господ, спасе Јего десница Јего, и мишца свјатаја Јего."}, {"num": "2.", "text": "Сказа Господ спасеније своје, пред јазики откри правду своју."}, {"num": "3.", "text": "Помјану милост своју Јакову, и истину своју дому Израиљеву, видјеша вси конци земљи спасеније Бога нашего."}, {"num": "4.", "text": "Воскликните Богови всја земља, воспојте, и радујтесја, и појте."}, {"num": "5.", "text": "Појте Господеви в гуслех, в гуслех, и гласје псаломстје."}, {"num": "6.", "text": "В трубах кованих, и гласом труби рожани, вострубите пред царем Господем."}, {"num": "7.", "text": "Да подвижитсја море и исполњеније јего, всељенаја и вси живушчији на њеј."}, {"num": "8.", "text": "Рјеки восплешчут рукоју вкупје, гори возрадујутсја."}, {"num": "9.", "text": "От лица Господња, јако грјадет, јако идет судити земљи, судити всељењеј в правду, људем правостију."}]}, "98": {"number": 98, "title": "Псалом 98. (98)", "subtitle": "", "verses": [{"num": "1.", "text": "Господ воцарисја, да гњевајутсја људије, сједјај на херувимјех, да подвижитсја земља."}, {"num": "2.", "text": "Господ в Сиоње велик, и висок јест над всјеми људми."}, {"num": "3.", "text": "Да исповједјатсја имени Твојему великому, јако страшно и свјато јест."}, {"num": "4.", "text": "И чест царева суд љубит, Ти уготовал јеси правоти, суд и правду во Јаковје Ти сотворил јеси."}, {"num": "5.", "text": "Возносите Господа Бога нашего, и поклањајтесја подножију ногу Јего, јако свјато јест."}, {"num": "6.", "text": "Мојсеј и Аарон во јерејех Јего, и Самуил в призивајушчих имја Јего, призиваху Господа, и Тој послушаше их."}, {"num": "7.", "text": "В столпје облачње глагољаше к Њим, јако храњаху свидјенија Јего и повељенија Јего, јаже даде им."}, {"num": "8.", "text": "Господи Боже наш, Ти послушал јеси их, Боже, Ти милостив бивал јеси им, и мишчаја на всја начинанија их."}, {"num": "9.", "text": "Вознесите Господа Бога нашего, и поклањајтесја в горје свјатјеј Јего, јако свјат Господ Бог наш."}]}, "99": {"number": 99, "title": "Псалом 99. (99)", "subtitle": "", "verses": [{"num": "1.", "text": "Воскликните Богови всја земља."}, {"num": "2.", "text": "Работајте Господеви в сељенији, внидите пред Њим в радости."}, {"num": "3.", "text": "Увједите, јако Господ Тој јест Бог наш, Тој сотвори нас, а не ми, ми же људије Јего, и овци пажити Јего."}, {"num": "4.", "text": "Внидите во врата Јего во исповједанији, во двори Јего в пјенијих, исповједајтесја Јему, хвалите имја Јего."}, {"num": "5.", "text": "Јако благ Господ, во вјек милост Јего, и даже до рода и рода истина Јего."}]}, "100": {"number": 100, "title": "Псалом 100. (100)", "subtitle": "", "verses": [{"num": "1.", "text": "Милост и суд воспоју Тебје Госноди."}, {"num": "2.", "text": "Поју и разумјеју в пути непорочње, когда пријдеши ко мње, прехождах во незлобији сердца мојего, посредје дому мојего."}, {"num": "3.", "text": "Не предлагах пред очима мојим вешч законопреступнују, творјашчија преступљеније возненавидјех."}, {"num": "4.", "text": "Не прилпе мње сердце строптиво, уклоњајушчагосја от мене лукаваго не познах."}, {"num": "5.", "text": "Оклеветајушчаго тај искренаго својего, сего изгоњах, гордим оком, и неситим сердцем со сим не јадјах."}, {"num": "6.", "text": "Очи моји на вјернија земљи, посаждати ја со мноју, ходјај по пути непорочну, сеј ми служаше."}, {"num": "7.", "text": "Не живјаше посредје дому мојего творјај гордињу, глагољај неправеднаја, не исправљаше пред очима мојима."}, {"num": "8.", "text": "Во јутрија избивах всја грјешнија земљи, јеже потребити от града Господња всја дјелајушчија безаконије. Слава:"}]}, "101": {"number": 101, "title": "Псалом 101. (101)", "subtitle": "", "verses": [{"num": "1.", "text": "Господи услиши молитву моју, и вопал мој к Тебје да пријдет."}, {"num": "2.", "text": "Не отврати лица Твојего од мене, в оњже ашче ден скорбљу, приклони ко мње ухо Твоје, во оњже ашче ден призову Тја, скоро услиши мја."}, {"num": "3.", "text": "Јако исчезоша јако дим дније моји, и кости моја јако сушило сосхошасја."}, {"num": "4.", "text": "Ујазвен бих јако трава, и изсуше сердце моје, јако забих снјести хљеб мој."}, {"num": "5.", "text": "От гласа воздиханија мојего прилпе кост моја плоти мојеј."}, {"num": "6.", "text": "Уподобихсја нејасити пустињеј, бих јако ношчниј вран на ниришчи."}, {"num": "7.", "text": "Бдјех и бих јако птица особјашчајасја на здје."}, {"num": "8.", "text": "Вес ден поношаху ми врази моји, и хваљајушчији мја мноју клењахусја."}, {"num": "9.", "text": "Зане пепел јако хљеб јадјах, и питије моје с плачем растворјах."}, {"num": "10.", "text": "От лица гњева Твојего и јарости Твојеја, јако низвергал мја јеси."}, {"num": "11.", "text": "Дније моји јако сјен уклонишасја, и аз јако сјено исхох."}, {"num": "12.", "text": "Ти же Господи во вјек пребивајеши, и памјат Твоја в род и род."}, {"num": "13.", "text": "Ти воскрес ушчедриши Сиона, јако времја ушчедрити јего, јако пријде времја."}, {"num": "14.", "text": "Јако благовилиша раби Твоји каменије јего, и перст јего ушчедрјат."}, {"num": "15.", "text": "И убојатсја јазици имене Господња, и вси царије земстији слави Твојеја."}, {"num": "16.", "text": "Јако созиждет Господ Сиона, и јавитсја во славје својеј."}, {"num": "17.", "text": "Призрје на молитву смирених, и не уничижи мољенија их."}, {"num": "18.", "text": "Да напишетсја сије в род ин, и људије зиждемији восхваљат Господа."}, {"num": "19.", "text": "Јако приниче с висоти свјатија својеја, Господ с небесе на земљу призрје."}, {"num": "20.", "text": "Услишати воздиханије окованих, разрјешити сини умершчвљених."}, {"num": "21.", "text": "Возвјестите в Сиоње имја Господње, и хвалу Јего во Јерусалимје."}, {"num": "22.", "text": "Внегда собратисја људем вкупје, и царем јеже работати Господеви."}, {"num": "23.", "text": "Отвјешча јему пути крјепости јего, умаљеније днеј мојих возвјести ми."}, {"num": "24.", "text": "Не возведи мене во преполовеније днеј мојих, в родје родов љета Твоја."}, {"num": "25.", "text": "В начаљех Ти Господи земљу основал јеси, и дјела руку Твојеју сут небеса."}, {"num": "26.", "text": "Та погибнут, Ти же пребивајеши, и всја јако риза обетшајут, и јако одежду свијеши ја, и измјењатсја."}, {"num": "27.", "text": "Ти же тојжде јеси, и љета Твоја не оскудјејут."}, {"num": "28.", "text": "Синове раб твојих всељатсја, и сјемја их во вјек исправитсја."}]}, "102": {"number": 102, "title": "Псалом 102. (102)", "subtitle": "", "verses": [{"num": "1.", "text": "Благослови душе моја Господа, и всја внутрењаја моја имја свјатоје Јего."}, {"num": "2.", "text": "Благослови душе моја Господа, и не забивај всјех воздајаниј Јего."}, {"num": "3.", "text": "Очишчајушчаго всја безаконија твоја, исцјељајушчаго всја недуги твоја."}, {"num": "4.", "text": "Избављајушчаго от истљенија живот твој, вјенчајушчаго тја милостију и шчедротами."}, {"num": "5.", "text": "Исполњајушчаго во благих желаније твоје, обновитсја јако орља јуност твоја."}, {"num": "6.", "text": "Творјај милостињи Господ, и судбу всјем обидимим."}, {"num": "7.", "text": "Сказа пути Своја Мојсеови, синовом Израиљевим хотјенија Своја."}, {"num": "8.", "text": "Шчедар и милостив Господ, долготерпјељив и многомилостив."}, {"num": "9.", "text": "Не до конца прогњевајетсја, ниже во вјек враждујет."}, {"num": "10.", "text": "Не по безаконијем нашим сотворил јест нам, ниже по грјехом нашим воздал јест нам."}, {"num": "11.", "text": "Јако по висотје небесњеј от земљи утвердил јест Господ милост Своју на бојашчихсја Јего."}, {"num": "12.", "text": "Јелико отстојат востоци от запад удаљил јест от нас безаконија наша."}, {"num": "13.", "text": "Јакоже шчедрит отец сини, ушчедри Господ бојашчихсја Јего."}, {"num": "14.", "text": "Јако Тој позна созданије наше, помјану јако перст јесми."}, {"num": "15.", "text": "Человјек јако трава, дније јего јако цвјет селниј, тако оцвјетет."}, {"num": "16.", "text": "Јако дух пројде в њем, и не будет и не познајет ктому мјеста својего."}, {"num": "17.", "text": "Милост же Господња от вјека и до вјека на бојашчихсја Јего."}, {"num": "18.", "text": "И правда Јего на сињех синов, храњашчих завјет Јего, и помњашчих заповједи Јего творити ја."}, {"num": "19.", "text": "Господ на Небеси уготова престол свој, и царство Јего всјеми обладајет."}, {"num": "20.", "text": "Благословите Господа вси ангели Јего, силнији крјепостију творјашчији слово Јего, услишати глас словес Јего."}, {"num": "21.", "text": "Благословите Господа всја сили Јего, слуги Јего творјашчији вољу Јего."}, {"num": "22.", "text": "Благословите Господа всја дјела Јего, на всјаком мјестје владичества Јего, благослови душе моја Господа. Слава:"}]}, "103": {"number": 103, "title": "Псалом 103. (103)", "subtitle": "", "verses": [{"num": "1.", "text": "Благослови душе моја Господа, Господи Боже мој, возвеличилсја јеси зјело, во исповједаније и во велељепоту облекалсја јеси."}, {"num": "2.", "text": "Одјејајсја свјетом јако ризоју, простирајај небо јако кожу."}, {"num": "3.", "text": "Покривајај водами превиспрењаја своја, полагајај облаки на восхожденије своје, ходјај на крилу вјетрењу."}, {"num": "4.", "text": "Творјај ангели своја духи, и слуги своја пламен огњениј."}, {"num": "5.", "text": "Основајај земљу на тверди јеја, не преклонитсја во вјек вјека."}, {"num": "6.", "text": "Бездна јако риза одјејаније јеја, на горах станут води."}, {"num": "7.", "text": "От запрешченија Твојего побјегнут, от гласа грома Твојего убојатсја."}, {"num": "8.", "text": "Восходјат гори, и нисходјат поља в мјесто, јеже основал јеси им."}, {"num": "9.", "text": "Предјел положил јеси, јегоже не прејдут, ниже обратјатсја покрити земљу."}, {"num": "10.", "text": "Посилајај источники в дебрех, посредје гори пројдут води."}, {"num": "11.", "text": "Напајајут всја звјери селнија, ждут онагри в жажду своју."}, {"num": "12.", "text": "На тих птици небеснија привитајут, от среди каменија дадјат глас."}, {"num": "13.", "text": "Напајај гори от превиспрених својих, от плода дјел Твојих наситјатсја земља."}, {"num": "14.", "text": "Прозјабајај траву скотом, и злак на службу человјеком, извести хљеб от земљи."}, {"num": "15.", "text": "И вино веселит сердце человјека, умастити лице јелејем, и хљеб сердце человјека укрјепит."}, {"num": "16.", "text": "Наситјатсја древа пољскаја, кедри Ливанстији, ихже јеси насадил."}, {"num": "17.", "text": "Тамо птици вогњездјатсја, јеродијево жилишче предводитељствујет ими."}, {"num": "18.", "text": "Гори високија јеленем, камен прибјежишче зајацем."}, {"num": "19.", "text": "Сотворил јест луну во времена, солнцс позна запад свој."}, {"num": "20.", "text": "Положил јеси таму, и бист ношч, в њејже пројдут вси звјерије дубравнији."}, {"num": "21.", "text": "Скимни рикајушчији восхитити, и взискати от Бога пишчу себје."}, {"num": "22.", "text": "Возсија солнце, и собрашасја, и в ложах својих љагут."}, {"num": "23.", "text": "Изидет человјек на дјело своје, и на дјеланије своје до вечера."}, {"num": "24.", "text": "Јако возвеличишасја дјела Твоја Господи, всја премудростију сотворил јеси, исполнисја земља твари Твојеја."}, {"num": "25.", "text": "Сије море великоје и пространоје, тамо гади, ихже њест числа, животнаја малаја с великими."}, {"num": "26.", "text": "Тамо корабљи преплавајут, змиј сеј, јегоже создал јеси ругатисја јему."}, {"num": "27.", "text": "Всја к Тебје чајут, дати пишчу им во благо времја."}, {"num": "28.", "text": "Давшу Тебје им, соберут, отверзешу Тебје руку, всјаческаја исполњатсја благости."}, {"num": "29.", "text": "Отврашчшу же Тебје лице, возмјатутсја, отимеши дух их, и исчезнут, и в перст своју возвратјатсја."}, {"num": "30.", "text": "Послеши Духа Твојего и созиждутсја, и обновиши лице земљи."}, {"num": "31.", "text": "Буди слава Господња во вјеки, возвеселитсја Господ о дјељех својих."}, {"num": "32.", "text": "Призирајај на земљу, и творјај ју трјастисја, прикасајајсја горам и димјатсја."}, {"num": "33.", "text": "Воспоју Господеви в животје мојем, поју Богу мојему дондеже јесам."}, {"num": "34.", "text": "Да усладитсја Јему бесједа моја, аз же возвесељусја о Господје."}, {"num": "35.", "text": "Да исчезнут грјешници от земљи, и безаконици јакоже не бити им. Благослови душе моја Господа. Слава:"}]}, "104": {"number": 104, "title": "Псалом 104. (104)", "subtitle": "", "verses": [{"num": "1.", "text": "Исповједајтесја Господеви, и призивајте имја Јего, возвјестите во јазицјех дјела Јего."}, {"num": "2.", "text": "Воспојте Јему, и појте Јему, повједите всја чудеса Јего."}, {"num": "3.", "text": "Хвалитесја о имени свјатом Јего, да возвеселитсја сердце ишчушчих Господа."}, {"num": "4.", "text": "Взишчите Господа, и утвердитесја, взишчите лица Јего вину."}, {"num": "5.", "text": "Помјаните чудеса Јего, јаже сотвори, чудеса Јего, и судби уста Јего."}, {"num": "6.", "text": "Сјемја Авраамле раби Јего, синове Јаковљи избранији Јего."}, {"num": "7.", "text": "Тој Господ Бог наш, по всеј земљи судби Јего."}, {"num": "8.", "text": "Помјану во вјек завјет свој, слово, јеже заповједа в тисјашчи родов."}, {"num": "9.", "text": "Јежс завјешча Аврааму, и кљатву своју Исааку."}, {"num": "10.", "text": "И постави ју Јакову в повељеније, и Израиљу завјет вјечан."}, {"num": "11.", "text": "Глагоља: Тебје дам земљу Ханаанску, уже достојанија вашего."}, {"num": "12.", "text": "Внегда бити им малим числом, маљејшим и пришелцем в њеј."}, {"num": "13.", "text": "И преидоша от јазика в јазик, и от царствија в људи ини."}, {"num": "14.", "text": "Не остави человјека обидјети их, и обличи о њих цари."}, {"num": "15.", "text": "Не прикасајтесја помазаним Мојим, и во пророцјех Мојих не лукавнујте."}, {"num": "16.", "text": "И призва глад па земљу, всјако утверженије хљебноје сотри."}, {"num": "17.", "text": "Посла пред њими человјека, в раба продан бист Јосиф."}, {"num": "18.", "text": "Смириша во оковах нозје јего, жељезо пројде душа јего."}, {"num": "19.", "text": "Дондеже пријде слово јего, слово Господње разжеже јего."}, {"num": "20.", "text": "Посла цар и разрјеши јего, књаз људеј, и остави јего."}, {"num": "21.", "text": "Постави јего господина дому својему, и књаза всему стјажанију својему."}, {"num": "22.", "text": "Наказати књази јего јако себе, и старци јего умудрити."}, {"num": "23.", "text": "И вниде Израиљ во Египет, и Јаков пришелствова в земљу Хамову."}, {"num": "24.", "text": "И возрасти људи своја зјело, и укрјепи ја паче врагов их."}, {"num": "25.", "text": "Преврати сердце их возненавидјети људи Јего, лест сотворити в рабјех Јего."}, {"num": "26.", "text": "Посла Мојсеја раба својего, Аарона, јегоже избра себје."}, {"num": "27.", "text": "Положи в њих словеса знамениј својих, и чудес својих в земљи Хамовје."}, {"num": "28.", "text": "Посла таму, и помрачи, јако преогорчиша словеса Јего."}, {"num": "29.", "text": "Преложи води их в кров, и измори риби их."}, {"num": "30.", "text": "Воскипје земља их жабами в сокровишчницах цареј их."}, {"num": "31.", "text": "Рече, и пријидоша песији мухи, и скнипи во всја предјели их."}, {"num": "32.", "text": "Положи дожди их гради, огањ попаљајушчи в земљи их."}, {"num": "33.", "text": "И порази виногради их, и смокви их, и сотри всјакоје древо предјел их."}, {"num": "34.", "text": "Рече, и пријидоша прузи и гусеници, имже не бје числа."}, {"num": "35.", "text": "И снједоша всјаку траву в земљи их, и појадоша всјак плод их."}, {"num": "36.", "text": "И порази всјакаго первенца в земљи их, начаток всјакаго труда их."}, {"num": "37.", "text": "И изведе ја со сребром и златом, и не бје в кољенах их бољај."}, {"num": "38.", "text": "Возвеселисја Египет во исхожденији их, јако нападе страх их на ња."}, {"num": "39.", "text": "Распростре облак в покров им, и огањ, јеже просвјетити им ношчију."}, {"num": "40.", "text": "Просиша и пријидоша крастели, и хљеба небеснаго насити ја."}, {"num": "41.", "text": "Разверзе камен, и потекоша води, потекоша в безводних рјеки."}, {"num": "42.", "text": "Јако помјану слово свјатоје своје, јеже ко Аврааму рабу својему."}, {"num": "43.", "text": "И изведе људи своја в радости, и избранија своја во веселији."}, {"num": "44.", "text": "И даде им страни јазик, и труди људеј насљедоваша."}, {"num": "45.", "text": "Јако да сохрањат оправданија Јего, и закона Јего взишчут. Слава:"}]}, "105": {"number": 105, "title": "Псалом 105. (105)", "subtitle": "", "verses": [{"num": "1.", "text": "Исповједајтесја Господеви, јако благ, јако во вјек милост Јего."}, {"num": "2.", "text": "Кто возглагољет сили Господњи, слишани сотворит всја хвали Јего."}, {"num": "3.", "text": "Блажени храњашчији суд, и творјашчији правду во всјакоје времја."}, {"num": "4.", "text": "Помјани нас Господи во благовољенији људеј Твојих, посјети нас спасенијем Твојим."}, {"num": "5.", "text": "Видјети во благости избранија Твоја, возвеселитсја во веселији јазика Твојего, хвалитисја со достојанијем Твојим."}, {"num": "6.", "text": "Согрјешихом со оци нашими, безаконовахом, неправдовахом."}, {"num": "7.", "text": "Оци наши во Египтје не разумјеша чудеса Твојих, ни помјануша множества милости Твојеја, и преогорчиша восходјашче в Чермноје море."}, {"num": "8.", "text": "И спасе их имене својего ради, сказати силу своју."}, {"num": "9.", "text": "И запрети Чермному морју, и изсјаче, и настави ја в бездње јако в пустињи."}, {"num": "10.", "text": "И спасе ја из руки ненавидјашчих, и избави ја из руки врагов."}, {"num": "11.", "text": "Покри вода стужајушчија им, ни једин от њих избист."}, {"num": "12.", "text": "И вјероваша словеси Јего, и воспјеша хвалу Јего."}, {"num": "13.", "text": "Ускориша, забиша дјела Јего, не стерпјеша совјета Јего."}, {"num": "14.", "text": "И похотјеша желанију в пустињи, и искусиша Бога во безводњеј."}, {"num": "15.", "text": "И даде им прошеније их, посла ситост в души их."}, {"num": "16.", "text": "И прогњеваша Мојсеја в стану, Аарона свјатаго Господња."}, {"num": "17.", "text": "Отверзесја земља, и пожре Датана, и покри на сонмишчи Авирона."}, {"num": "18.", "text": "И разжежесја огањ в сонмје их, пламен попали грјешники."}, {"num": "19.", "text": "И сотвориша телца в Хоривје, и поклонишасја истуканому."}, {"num": "20.", "text": "И измјениша славу Јего во подобије телца јадушчаго траву."}, {"num": "21.", "text": "И забиша Бога спасајушчаго их, сотворшаго велија во Египтје."}, {"num": "22.", "text": "Чудеса в земљи Хамовје, страшнаја в мори Чермњем."}, {"num": "23.", "text": "И рече потребити их, ашче не би Мојсеј, избраниј Јего, стал в сокрушенији пред Њим, возвратити јарост Јего, да не погубит их."}, {"num": "24.", "text": "И уничижиша земљу желанују, не јаша вјери словеси Јего."}, {"num": "25.", "text": "И поропташа в сељенијих својих, не услишаша гласа Господња."}, {"num": "26.", "text": "И воздвиже руку своју на ња, низложити ја в пустињи."}, {"num": "27.", "text": "И низложит сјемја их во јазицјех, и расточити ја в страни."}, {"num": "28.", "text": "И причастишасја Велфегору, и снједоша жертви мертвих."}, {"num": "29.", "text": "И раздражиша Јего в начинанијих својих, и умножисја в њих паденије."}, {"num": "30.", "text": "И ста Финес, и умилостиви, и преста сјеч."}, {"num": "31.", "text": "И вмјенисја јему в правду, в род и род до вјека."}, {"num": "32.", "text": "И прогњеваша Јего на водје прерјеканија, и озлобљен бист Мојсеј их ради."}, {"num": "33.", "text": "Јако преогорчиша дух јего, и разинствова устнама својима."}, {"num": "34.", "text": "Не потребиша јазики, јаже рече Господ им."}, {"num": "35.", "text": "И смјесишасја во јазицјех, и навикоша дјелом их."}, {"num": "36.", "text": "И поработаша истуканим их, и бист им во соблазан."}, {"num": "37.", "text": "И пожроша сини своја, дшчери своја бјесовом."}, {"num": "38.", "text": "И пролијаша кров неповинују, кров синов својих и дшчереј, јаже пожроша истуканим Ханаанским, и убијена бист земља их кровми."}, {"num": "39.", "text": "И осквернисја в дјељех их, и соблудиша в начинанијих својих."}, {"num": "40.", "text": "И разгњевасја јаростију Господ на људи своја, и омерзи достојаније своје."}, {"num": "41.", "text": "И предаде ја в руки врагов, и обладаша ими ненавидјашчији их."}, {"num": "42.", "text": "И стужиша им врази их, и смиришасја под руками их."}, {"num": "43.", "text": "Множицеју избави ја, тији же преогорчиша Јего совјетом својим, и смиришасја в безаконијих својих."}, {"num": "44.", "text": "И видје Господ, внегда скорбјети им, внегда услишаше мољеније их."}, {"num": "45.", "text": "И помјану завјет свој, и раскајасја по множеству милости својеја."}, {"num": "46.", "text": "И даде ја в шчедроти пред всјеми пљенившими ја."}, {"num": "47.", "text": "Спаси ни Господи Боже наш, и собери ни от јазик, исповједатисја имени Твојему свјатому, хвалитисја во хваље Твојеј."}, {"num": "48.", "text": "Благословен Господ Бог Израиљев от вјека и до вјека, и рекут вси људије: буди, буди. Слава:"}]}, "106": {"number": 106, "title": "Псалом 106. (106)", "subtitle": "", "verses": [{"num": "1.", "text": "Исповједајтесја Господеви, јако благ, јако во вјек милост Јего."}, {"num": "2.", "text": "Да рекут избављенији Господем, ихже избави из руки врага."}, {"num": "3.", "text": "И от стран собра их, от восток, и запад, и сјевера, и морја."}, {"num": "4.", "text": "Заблудиша в пустињи безводњеј, пути града обитељнаго не обрјетоша."}, {"num": "5.", "text": "Алчушче и жаждушче, душа их в њих исчезе."}, {"num": "6.", "text": "И возваша ко Господу, внегда скорбјети им, и от нужд их избави ја."}, {"num": "7.", "text": "И настави ја на пут прав, внити во град обитељних."}, {"num": "8.", "text": "Да исповједјатсја Господеви милости Јего, и чудеса Јего синовом человјеческим."}, {"num": "9.", "text": "Јако наситил јест душу тшчу, и душу алчушчу исполни благ."}, {"num": "10.", "text": "Сједјашчија в тамје и сјени смертњеј, окованија нишчетоју и жељезом."}, {"num": "11.", "text": "Јако преогорчиша словеса Божија, и совјет Вишњаго раздражиша."}, {"num": "12.", "text": "И смирисја в трудјех сердце их и изнемогоша, и не бје помогајај."}, {"num": "13.", "text": "И возваша ко Господу, внегда скорбјети им, и от нужд их спасе ја."}, {"num": "14.", "text": "И изведе ја из тами, и сјени смертнија, и узи их растерза."}, {"num": "15.", "text": "Да исповједјатсја Господеви милости Јего, и чудеса Јего синовом человјеческим."}, {"num": "16.", "text": "Јако сокруши врата мједнаја, и вереј жељезнија сломи."}, {"num": "17.", "text": "Воспријат ја от пути безаконија их, безакониј бо ради својих смиришасја."}, {"num": "18.", "text": "Всјакаго брашна возгнушасја душа их, и приближишасја до врат смертних."}, {"num": "19.", "text": "И возваша ко Господу, внегда скорбјети им, и от нужд их спасе ја."}, {"num": "20.", "text": "Посла слово своје, и исцјели ја, и избави ја от растљениј их."}, {"num": "21.", "text": "Да исповједјатсја Господеви милости Јего, и чудеса Јего синовом человјеческим."}, {"num": "22.", "text": "И да пожрут Јему жертву хвали, и да возвјестјат дјела Јего в радости."}, {"num": "23.", "text": "Сходјашчији в море в корабљах, творјашчији дјеланија во водах многих."}, {"num": "24.", "text": "Тији видјеша дјела Господња, и чудеса Јего во глубиње."}, {"num": "25.", "text": "Рече и ста дух бурен, и вознесошасја волни Јего."}, {"num": "26.", "text": "Восходјат до небес, и низходјат до бездан, душа их в злих тајаше."}, {"num": "27.", "text": "Смјатошасја, подвигошасја јако пијаниј, и всја мудрост их поглошчена бист."}, {"num": "28.", "text": "И возваша ко Господу, внегда скорбјети им, и от нужд их изведе ја."}, {"num": "29.", "text": "И повеље бури, и ста в тишину, и умолкоша волни јего."}, {"num": "30.", "text": "И возвеселишасја, јако умолкоша, и настави ја в пристанишче хотјенија својего."}, {"num": "31.", "text": "Да исповједјатсја Господеви милости Јего, и чудеса Јего синовом человјеческим."}, {"num": "32.", "text": "Да вознесут Јего в церкви људстеј, и на сједалишчи старец восхваљат Јего."}, {"num": "33.", "text": "Положил јест рјеки в пустињу, и исходишча воднаја в жажду."}, {"num": "34.", "text": "Земљу плодоноснују в сланост, от злоби живушчих на њеј."}, {"num": "35.", "text": "Положил јест пустињу во језера воднаја, и земљу безводнују во исходишча воднаја."}, {"num": "36.", "text": "И насели тамо алчушчија, и составиша гради обитељни."}, {"num": "37.", "text": "И насјејаша села, и насадиша виногради, и сотвориша плод житен."}, {"num": "38.", "text": "И благослови ја, и умножишасја зјело, и скоти их не умали."}, {"num": "39.", "text": "И умалишасја и озлобишасја от скорби зол и бољезни."}, {"num": "40.", "text": "Излијасја уничиженије на књази их, и облазни ја по непроходњеј, а не по пути."}, {"num": "41.", "text": "И поможе убогу от нишчети, и положи јако овци отечествија."}, {"num": "42.", "text": "Узрјат правији и возвесељатсја, и всјакоје безаконије заградит уста своја."}, {"num": "43.", "text": "Кто премудар и сохранит сија, и уразумјејут милости Господњи. Слава:"}]}, "107": {"number": 107, "title": "Псалом 107. (107)", "subtitle": "", "verses": [{"num": "1.", "text": "Готово сердце моје Боже, готово сердце моје, воспоју и поју во славје мојеј."}, {"num": "2.", "text": "Востани слава моја, востани псалтирју и гусли, востану рано."}, {"num": "3.", "text": "Исповјемсја Тебје в људех Господи, поју Тебје во јазицјех."}, {"num": "4.", "text": "Јако велија верху небес милост Твоја, и до облак истина Твоја."}, {"num": "5.", "text": "Вознесисја на небеса Боже, и по всеј земљи слава Твоја,"}, {"num": "6.", "text": "Јако да избавјатсја возљубљенији Твоји, спаси десницеју Твојеју, и услиши мја."}, {"num": "7.", "text": "Бог возглагоља во свјатјем својем, вознесусја и раздјељу Сикиму, и удол сељениј размјерју."}, {"num": "8.", "text": "Мој јест Галад, и Мој јест Манасиј, и Јефрем заступљеније глави Мојеја, Јуда цар Мој."}, {"num": "9.", "text": "Моав коноб упованија Мојего, на Идумеју наложу сапог Мој, Мње иноплеменици покоришасја."}, {"num": "10.", "text": "Кто воведет мја во град огражденија, или кто наставит мја до Идумеји."}, {"num": "11.", "text": "Не Ти ли Боже отринувиј иас, и не изидеши Боже в силах наших."}, {"num": "12.", "text": "Дажд нам помошч от скорби, и сујетно спасеније человјеческо."}, {"num": "13.", "text": "О Бозје сотворим силу, и Тој уничижит враги нашја."}]}, "108": {"number": 108, "title": "Псалом 108. (108)", "subtitle": "", "verses": [{"num": "1.", "text": "Боже хвали мојеја не премолчи."}, {"num": "2.", "text": "Јако уста грјешнича и уста лестиваго на мја отверзошасја, глагољаша на мја јазиком лестивим."}, {"num": "3.", "text": "И словеси ненавистними обидоша мја, и брашасја со мноју туне."}, {"num": "4.", "text": "Вмјесто јеже љубити мја, оболгаху мја, аз же мољахсја."}, {"num": "5.", "text": "И положиша на мја злаја за благаја, и ненавист за возљубљеније моје."}, {"num": "6.", "text": "Постави на њего грјешника, и дијавол да не стане одеснују јего."}, {"num": "7.", "text": "Внегда судитисја јему, да изидет осужден, и молитва јего да будет в грјех."}, {"num": "8.", "text": "Да будут дније јего мали, и епископство јего да пријимет ин."}, {"num": "9.", "text": "Да будут синове јего сири, и жена јего вдова."}, {"num": "10.", "text": "Движушчесја да пресељатсја синове и воспросјат, да изгнани будут из домов својих."}, {"num": "11.", "text": "Да взишчет зајмодавец всја, јелика сут јего, и да восхитјат чуждији труди јего."}, {"num": "12.", "text": "Да не будет јему заступника, ниже да будет ушчедрјајај сироти јего."}, {"num": "13.", "text": "Да будут чада јего в погубљеније, в родје једином да потребитсја имја јего."}, {"num": "14.", "text": "Да воспомјанетсја безаконије отец јего пред Господем, и грјех матери јего да не очиститсја."}, {"num": "15.", "text": "Да будут пред Господем вину, и да потребитсја от земљи памјат их."}, {"num": "16.", "text": "Занеже не помјану сотворити милост, и погна человјека нишча, и убога, и умиљена сердцем умертвити."}, {"num": "17.", "text": "И возљуби кљатву, и пријидет јему, и не восхотје благословенија и удаљитсја от њего."}, {"num": "18.", "text": "И облечесја в кљатву јако в ризу, и вниде јако вода во утробу јего, и јако јелеј в кости јего."}, {"num": "19.", "text": "Да будет јему јако риза, в њуже облачитсја, и јако појас, имже вину опојасујетсја."}, {"num": "20.", "text": "Сије дјело оболгајушчих мја у Господа, и глагољушчих лукаваја на душу моју."}, {"num": "21.", "text": "И Ти Господи Господи сотвори со мноју имене ради Твојего, јако блага милост Твоја."}, {"num": "22.", "text": "Избави мја, јако нишч и убог јесам аз, и сердце моје смјатесја внутар мене."}, {"num": "23.", "text": "Јако сјен, внегда уклонитисја јеј, отјахсја, стрјасохсја, јако прузи."}, {"num": "24.", "text": "Кољена моја изнемогоста от поста, и плот моја измјенисја јелеја ради."}, {"num": "25.", "text": "И аз бих поношеније им, видјеша мја, покиваша главами својим."}, {"num": "26.", "text": "Помози ми Господи Боже мој, и спаси мја по милости Твојеј."}, {"num": "27.", "text": "И да разумјејут, јако рука Твоја сија, и Ти Господи сотворил јеси ју."}, {"num": "28.", "text": "Прокленут тији, и Ти благословиши, востајушчији на мја да постидјатсја, и раб же Твој возвеселитсја."}, {"num": "29.", "text": "Да облекутсја оболгајушчији мја в срамоту, и одеждутсја јако одеждеју студом својим."}, {"num": "30.", "text": "Исповјемсја Господеви зјело уст мојими, и посредје многих восхваљу Јего."}, {"num": "31.", "text": "Јако предста одеснују убогаго, јеже спасти от гоњашчих душу моју. Слава:"}]}, "109": {"number": 109, "title": "Псалом 109. (109)", "subtitle": "", "verses": [{"num": "1.", "text": "Рече Господ Господеви мојему: Сједи одеснују Мене, дондеже положу враги Твоја подножије ног Твојих."}, {"num": "2.", "text": "Жезал сили послет Ти Господ от Сиона, и господствуј посредје врагов Твојих."}, {"num": "3.", "text": "С Тобоју начало в ден сили Твојеја, во свјетлостех свјатих Твојих, из чрева прежде деници родих Тја."}, {"num": "4.", "text": "Кљатсја Господ, и не раскајетсја: Ти јереј во вјек, по чину Мелхиседекову."}, {"num": "5.", "text": "Господ одеснују тебе, сокрушил јест в ден гњева својего цари."}, {"num": "6.", "text": "Судит во јазицјех, исполнит паденија, сокрушит глави на земљи многих."}, {"num": "7.", "text": "От потока на пути пијет, сего ради вознесет главу."}]}, "110": {"number": 110, "title": "Псалом 110. (110)", "subtitle": "", "verses": [{"num": "1.", "text": "Исповјемсја Тебје Господеви всјем сердцем мојим, в совјетје правих и сонмје."}, {"num": "2.", "text": "Велија дјела Господња, изискана во всјех вољах Јего."}, {"num": "3.", "text": "Исповједаније и великољепије дјело Јего, и правда Јего пребивајет во вјек вјека."}, {"num": "4.", "text": "Памјат сотворил јест чудес својих, милостив и шчедар Господ."}, {"num": "5.", "text": "Пишчу даде бојашчимсја Јего, помјанет во вјек завјет свој."}, {"num": "6.", "text": "Крјепост дјел својих возвјести људем својим, дати им достојаније јазик."}, {"num": "7.", "text": "Дјела рук Јего истина и суд, вјерни всја заповједи Јего."}, {"num": "8.", "text": "Утвержени во вјек вјека, сотворени во истиње и правотје."}, {"num": "9.", "text": "Избављеније посла људем својим, заповједа во вјек завјет свој, свјато и страшно имја Јего."}, {"num": "10.", "text": "Начало премудрости страх Господењ, разума же благ всјем творјашчим их, хвала Јего пребивајет во вјек вјека."}]}, "111": {"number": 111, "title": "Псалом 111. (111)", "subtitle": "", "verses": [{"num": "1.", "text": "Блажен муж бојајсја Госиода, в заповједех Јего восхошчет зјело."}, {"num": "2.", "text": "Силно на земљи будет сјемја јего, род правих благословитсја."}, {"num": "3.", "text": "Слава и богатство во дому јего, и правда јего пребивајет во вјек вјека."}, {"num": "4.", "text": "Возсија во тамје свјет правим, милостив и шчедар и праведен."}, {"num": "5.", "text": "Благ муж шчедрја и даја, устројит словеса своја на судје, јако во вјек не подвижитсја."}, {"num": "6.", "text": "В памјат вјечнују будет праведник."}, {"num": "7.", "text": "От слуха зла не убојитсја."}, {"num": "8.", "text": "Готово сердце јего, уповати на Господа, утвердисја сердце јего, не убојитсја, дондеже возрит на враги своја."}, {"num": "9.", "text": "Расточи, даде убогим, правда јего пребивајет во вјек вјека, рог јего вознесесја во славје."}, {"num": "10.", "text": "Грјешник узрит и прогњевајетсја, зуби својими поскрежешчет и растајет, желаније грјешника погибнет. Слава:"}]}, "112": {"number": 112, "title": "Псалом 112. (112)", "subtitle": "", "verses": [{"num": "1.", "text": "Хвалите отроци Господа, хвалите имја Господње."}, {"num": "2.", "text": "Буди имја Господње благословено от ниње и до вјека."}, {"num": "3.", "text": "От восток солнца до запад хвално имја Господње."}, {"num": "4.", "text": "Висок над всјеми јазики Господ, над небеси слава Јего."}, {"num": "5.", "text": "Кто јако Господ Бог наш, на високих живиј,"}, {"num": "6.", "text": "И на смиренија призирајај, на небеси и на земљи."}, {"num": "7.", "text": "Воздвизајај от земљи нишча, и от гнојишча возвишајај убога."}, {"num": "8.", "text": "Посадити јего с књази, с књази људеј својих."}, {"num": "9.", "text": "Всељаја неплодов в дом, матер о чадјех весељашчусја."}]}, "113": {"number": 113, "title": "Псалом 113. (113)", "subtitle": "", "verses": [{"num": "1.", "text": "Во исходје Израиљевље от Египта, дому Јаковља, из људеј варвар."}, {"num": "2.", "text": "Бист Јудеја свјатиња јего, Израиљ област јего."}, {"num": "3.", "text": "Море видје и побјеже, Јордан возвратисја вспјат."}, {"num": "4.", "text": "Гори взиграшасја јако овни, и холми јако аганци овчији."}, {"num": "5.", "text": "Что ти јест море, јако побјегло јеси, и тебје Јордане, јако возвратилсја јеси вспјат."}, {"num": "6.", "text": "Гори, јако взиграстесја јако овни, и холми јако аганци овчији."}, {"num": "7.", "text": "От лица Господња подвижесја земља, от лица Бога Јаковља."}, {"num": "8.", "text": "Обрашчшаго камен в језера воднаја, и несјекомиј во источники воднија."}, {"num": "9.", "text": "Не нам Господи, не иам, но имени Твојему дажд славу, о милости Твојеј и истиње Твојеј."}, {"num": "10.", "text": "Да не когда рекут јазици: Гдје јест Бог их."}, {"num": "11.", "text": "Бог же наш на небеси и на земљи, всја јелика восхотје сотвори."}, {"num": "12.", "text": "Идоли јазик сребро, и злато, дјела рук человјеческих."}, {"num": "13.", "text": "Уста имут, и не возглагољут, очи имут и не узрјат."}, {"num": "14.", "text": "Уши имут, и не услишат, ноздри имут, и пе обоњајут."}, {"num": "15.", "text": "Руцје имут, и не осјажут, нозје имут, и не појдут, не возгласјат гортанем својим."}, {"num": "16.", "text": "Подобни им да будут творјашчији ја, и вси надјејушчијисја на ња."}, {"num": "17.", "text": "Дом Израиљев упова на Господа, помошчник и зашчититељ им јест."}, {"num": "18.", "text": "Дом Аарон упова на Господа, помошчник и зашчититељ им јест."}, {"num": "19.", "text": "Бојашчијисја Господа уповаша на Господа, помошчник и зашчититељ им јест."}, {"num": "20.", "text": "Господ помјанув ни, благословил јест нас, благословил јест дом Израиљев, благословил јест дом Аарон."}, {"num": "21.", "text": "Благословил јест бојашчијасја Господа, малија с великими."}, {"num": "22.", "text": "Да приложит Господ на ви, на ви, и на сини вашја."}, {"num": "23.", "text": "Благословени ви Господеви, сотворшему небо и земљу."}, {"num": "24.", "text": "Небо небесе Господеви, земљу же даде синовом человјеческим."}, {"num": "25.", "text": "Не мертвији восхваљат тја Господи, ниже вси низходјашији во ад."}, {"num": "26.", "text": "Но ми живији благословим Господа, от ниње и до вјека."}]}, "114": {"number": 114, "title": "Псалом 114. (114)", "subtitle": "", "verses": [{"num": "1.", "text": "Возљубих, јако услишит Господ глас мољенија мојего."}, {"num": "2.", "text": "Јако приклони ухо своје мње, и во дни моја призову."}, {"num": "3.", "text": "Објаша мја бољезни смертнија, бједи адови обрјетоша мја, скорб и бољезан обрјетох, и имја Господње призвах."}, {"num": "4.", "text": "О Господи, избави душу моју, милостив Господ и праведен, и Бог наш милујет."}, {"num": "5.", "text": "Храњај младенци Господ, смирихсја, и спасе мја."}, {"num": "6.", "text": "Обратисја душе моја в покој Твој, јако Господ благодјејствова тја."}, {"num": "7.", "text": "Јако изјат душу моју от смерти, очи моји от слез, и нозје моји от поползновенија."}, {"num": "8.", "text": "Благоугожду пред Господем во страње живих. Слава:"}]}, "115": {"number": 115, "title": "Псалом 115. (115)", "subtitle": "", "verses": [{"num": "1.", "text": "Вјеровах, тјемже и возглагољах: аз же смирихсја зјело."}, {"num": "2.", "text": "Аз же рјех во изступљенији мојем: всјак человјек лож."}, {"num": "3.", "text": "Что воздам Господеви о всјех, јаже воздаде ми."}, {"num": "4.", "text": "Чашу спасенија пријиму, и имја Господње призову."}, {"num": "5.", "text": "Молитви моја Господеви воздам пред всјеми људми Јего."}, {"num": "6.", "text": "Честна пред Господем смерт преподобних Јего."}, {"num": "7.", "text": "О, Господи, аз раб Твој, аз раб Твој, и син рабини Твојеја: растерзал јеси узи моја."}, {"num": "8.", "text": "Тебје пожру жертву хвали, и во имја Господње призову."}, {"num": "9.", "text": "Молитви моја Господеви воздам пред всјеми људми Јего."}, {"num": "10.", "text": "Во дворјех дому Господња, посредје тебе, Јерусалиме."}]}, "116": {"number": 116, "title": "Псалом 116. (116)", "subtitle": "", "verses": [{"num": "1.", "text": "Хвалите Господа вси јазици, похвалите Јего вси људије."}, {"num": "2.", "text": "Јако утвердисја милост Јего на нас, и истина Господња пребивајет во вјек."}]}, "117": {"number": 117, "title": "Псалом 117. (117)", "subtitle": "", "verses": [{"num": "1.", "text": "Исповједајтесја Господеви, јако благ, јако во вјек милост Јего."}, {"num": "2.", "text": "Да речет убо дом Израиљев, јако благ, јако во вјек милост Јего."}, {"num": "3.", "text": "Да речет убо дом Аарон, јако благ, јако во вјек милост Јего."}, {"num": "4.", "text": "Да рекут убо вси бојашчијисја Господа, јако благ, јако во вјек милост Јего."}, {"num": "5.", "text": "От скорби призвах Господа, и услиша мја в пространство."}, {"num": "6.", "text": "Господ мње помошчник, и не убојусја, что сотворит мње человјек."}, {"num": "7.", "text": "Господ мње помошчник, и аз возрју на враги моја."}, {"num": "8.", "text": "Благо јест надјејатисја на Господа, нежели надјејатисја на человјека."}, {"num": "9.", "text": "Благо јест уповати на Господа, нежели уповати на књази."}, {"num": "10.", "text": "Вси јазици обидоша мја, и именем Господњим противљахсја им."}, {"num": "11.", "text": "Обишедше обидоша мја, и именем Господњим противљахсја им."}, {"num": "12.", "text": "Обидоша мја јако пчели сот, и разгорјешасја јако огањ в тернији, и именем Господњим противљахсја им."}, {"num": "13.", "text": "Отриновен превратихсја пасти, и Господ пријат мја."}, {"num": "14.", "text": "Крјепост моја и пјеније моје Господ, и бист ми во спасеније."}, {"num": "15.", "text": "Глас радости и спасенија в сељенијих праведних, десница Господња сотвори силу."}, {"num": "16.", "text": "Десница Господња вознесе мја, десница Господња сотвори силу."}, {"num": "17.", "text": "Не умру, но жив буду, и повјем дјела Господња."}, {"num": "18.", "text": "Наказујај наказа мја Господ, смерти же не предаде мја."}, {"num": "19.", "text": "Отверзите мње врата правди, вшед в ња исповјемсја Господеви."}, {"num": "20.", "text": "Сија врата Господња, праведнији внидут в ња."}, {"num": "21.", "text": "Исповјемсја Тебје, јако услишал мја јеси, и бил јеси мње во спасеније."}, {"num": "22.", "text": "Камен јегоже небрегоша зиждушчији, сеј бист во главу угла."}, {"num": "23.", "text": "От Господа бист сеј, и јест дивен во очесјех наших."}, {"num": "24.", "text": "Сеј ден јегоже сотвори Господ, возрадујемсја и возвеселимсја в оњ."}, {"num": "25.", "text": "О Господи спаси же, о Господи поспјеши же."}, {"num": "26.", "text": "Благословен грјадиј во имја Господње, благословихом ви из дому Господња."}, {"num": "27.", "text": "Благ Господ, и јависја нам, составите праздник во учашчајушчих до рог олтаревих."}, {"num": "28.", "text": "Бог мој јеси Ти, и исповјемсја Тебје: Бог мој јеси Ти, и вознесу Тја, исповјемсја Тебје, јако услишал мја јеси, и бил јеси мње во спасеније."}, {"num": "29.", "text": "Исповједајтесја Господеви, јако благ, јако во вјек милост Јего. Слава:"}]}, "118": {"number": 118, "title": "Псалом 118. (118)", "subtitle": "", "verses": [{"num": "1.", "text": "Блажени непорочнији в пут, ходјашчији в закоње Господњи."}, {"num": "2.", "text": "Блажени испитајушчији свидјенија Јего, всјем сердцем взишчут Јего."}, {"num": "3.", "text": "Не дјелајушчији бо безаконија, в путех Јего ходиша."}, {"num": "4.", "text": "Ти заповједал јеси заповједи Твоја сохранити зјело."}, {"num": "5.", "text": "Да би исправилсја путије моји, сохранити оправданија Твоја."}, {"num": "6.", "text": "Тогда непостижусја, внегда призрјети ми на всја заповједи Твоја."}, {"num": "7.", "text": "Исповјемсја Тебје в правости сердца, внегда научитимисја судбам правди Твојеја."}, {"num": "8.", "text": "Оправданија Твоја сохрању, не остави мене до зјела."}, {"num": "9.", "text": "В чесом исправит јуњејшиј пут свој, внегда сохранити словеса Твоја."}, {"num": "10.", "text": "Всјем сердцем мојим взисках Тебе, не отрини мене от заповједеј Твојих."}, {"num": "11.", "text": "В сердце мојем скрих словеса Твоја, јако да не согрјешу Тебје."}, {"num": "12.", "text": "Благословен јеси Господи, научи мја оправданијем Твојим."}, {"num": "13.", "text": "Устнама мојима возвјестих всја судби уст мојих."}, {"num": "14.", "text": "На пути свидјениј Твојих насладихсја, јако о всјаком богатствје."}, {"num": "15.", "text": "В заповједех Твојих поглумљусја и уразумјеју пути Твоја."}, {"num": "16.", "text": "Во оправданијих Твојих поучусја, не забуду словес Твојих."}, {"num": "17.", "text": "Воздажд рабу Твојему, живи мја, и сохрању словеса Твоја."}, {"num": "18.", "text": "Откриј очи моји, и уразумјеју чудеса от закона Твојего."}, {"num": "19.", "text": "Пришлец аз јесам на земљи, не скриј от мене заповједи Твоја."}, {"num": "20.", "text": "Возљуби душа моја возжелати судби Твоја на всјакоје времја."}, {"num": "21.", "text": "Запретил јеси гордим, прокљати уклоњајушчијисја от заповједеј Твојих."}, {"num": "22.", "text": "Отими от мене понос и уничиженије, јако свидјениј Твојих взисках."}, {"num": "23.", "text": "Ибо сједоша књази, и на мја клеветаху, раб же Твој глумљашесја во оправданијих Твојих."}, {"num": "24.", "text": "Ибо свидјенија Твоја поученије моје јест, и совјети моји, оправданија Твоја."}, {"num": "25.", "text": "Прилпе земљи душа моја, живи мја по словеси Твојему."}, {"num": "26.", "text": "Пути Твоја возвјестих, и услишал мја јеси, научи мја оправданијем Твојим."}, {"num": "27.", "text": "Пут оправданиј Твојих вразуми ми, и поглумљусја в чудесјех Твојих."}, {"num": "28.", "text": "Воздрема душа моја от унинија, утверди мја в словесјех Твојих."}, {"num": "29.", "text": "Пут неправди остави от мене, и законом Твојим помилуј мја."}, {"num": "30.", "text": "Пут истини изволих, и судби Твоја не забих."}, {"num": "31.", "text": "Приљепихсја свидјенијем Твојим Господи, непосрами мене."}, {"num": "32.", "text": "Пут заповједеј Твојих текох, јегда разширил јеси сердце моје."}, {"num": "33.", "text": "Законоположи мње Господи пут оправданиј Твојих, и взишчу и вину."}, {"num": "34.", "text": "Вразуми мја, и испитају закон Твој, и сохрању их всјем сердцем мојим."}, {"num": "35.", "text": "Настави мја па стезју заповједеј Твојих, јако тују восхотјех."}, {"num": "36.", "text": "Приклони сердце моје во свидјенија Твоја, а не в лихоимство."}, {"num": "37.", "text": "Отврати очи моји јеже не видјети сујети, в пути Твојем живи мја."}, {"num": "38.", "text": "Постави рабу Твојему слово Твоје в страх Твој."}, {"num": "39.", "text": "Отими поношеније моје, јеже непшчевах, јако судби Твоја благи."}, {"num": "40.", "text": "Се возжелах заповједи Твоја, в правдје Твојеј живи мја."}, {"num": "41.", "text": "И да пријидет на мја милост Твоја Господи, спасеније Твоје по словеси Твојему."}, {"num": "42.", "text": "И отвјешчају поношајушчим ми слово, јако уповах на словеса Твоја."}, {"num": "43.", "text": "И не отими от уст мојих словесе истина до зјела, јако на судби Твоја уповах."}, {"num": "44.", "text": "И сохрању закон Твој вину, во вјек и во вјек вјека."}, {"num": "45.", "text": "И хождах в широтје, јако заповједи Твоја взисках."}, {"num": "46.", "text": "И глагољах о свидјенијих Твојих пред цари, и не стидјатсја."}, {"num": "47.", "text": "И поучахсја в заповједех Твојих јаже возљубих зјело."}, {"num": "48.", "text": "И воздвигох руцје моји к заповједем Твојим, јаже возљубих, и глумљахсја во оправданијих Твојих."}, {"num": "49.", "text": "Помјани словеса Твоја рабу Твојему, ихже упованије дал ми јеси."}, {"num": "50.", "text": "То мја утјеши во смиренији мојем, јако слово Твоје живи мја."}, {"num": "51.", "text": "Гордији законопреступоваху до зјела, от закона же Твојего не уклонихсја."}, {"num": "52.", "text": "Помјанух судби Твоја от вјека Господи, и утјешихсја."}, {"num": "53.", "text": "Печал пријат мја от грјешник остављајушчих закон Твој."}, {"num": "54.", "text": "Пјета бјаху мње оправданија Твоја, на мјестје пришелствија мојего."}, {"num": "55.", "text": "Помјанух в ношчи имја Твоје Господи, и сохраних закон Твој."}, {"num": "56.", "text": "Сеј бист мње, јако оправданији Твојих взисках."}, {"num": "57.", "text": "Част моја јеси Господи, рјех сохранити закон Твој."}, {"num": "58.", "text": "Помолихсја лицу Твојему всјем сердцем мојим, помилуј мја мо словеси Твојему."}, {"num": "59.", "text": "Помислих пути Твоја, и возвратих нозје моји во свидјенија Твоја."}, {"num": "60.", "text": "Уготовихсја и не смутихсја, сохранити заповједи Твоја."}, {"num": "61.", "text": "Ужја грјешник објазашасја мње, и закона Твојего не забих."}, {"num": "62.", "text": "Полуношчи востах, исповједатисја Тебје о судбах правди Твојеја."}, {"num": "63.", "text": "Причастник аз јесам всјем бојашчимсја Тебе, и храњашчим заповједи Твоја."}, {"num": "64.", "text": "Милости Твојеја Господи исполн земља, оправданијем Твојим научи мја."}, {"num": "65.", "text": "Благост сотворил јеси с рабом Твојим Господи по словеси Твојему."}, {"num": "66.", "text": "Благости и наказанију и разуму научи мја, јако заповједем Твојим вјеровах."}, {"num": "67.", "text": "Прежде даже не смиритимисја, аз прегрјеших, сего ради слово Твоје сохраних."}, {"num": "68.", "text": "Благ јеси Ти Господи, и благостију Твојеју научи мја оправданијем Твојим."}, {"num": "69.", "text": "Умножисја на мја неправда гордих, аз же всјем сердцем мојим испитају заповједи Твоја."}, {"num": "70.", "text": "Усирисја јако млеко сердце их, аз жс закону Твојему поучихсја."}, {"num": "71.", "text": "Благо мње, јако смирил мја јеси, јако да научусја оправданијем Твојим."}, {"num": "72.", "text": "Благ мње закон уст Твојих, паче тисјашч злата и сребра. Слава:"}, {"num": "73.", "text": "Руцје Твоји сотвористје мја и создастје мја, вразуми мја, и научусја заповједем Твојим."}, {"num": "74.", "text": "Бојашчијисја Тебе узрјат мја и возвесељатсја, јако на словеса Твоја уповах."}, {"num": "75.", "text": "Разумјех Господи, јако правда судби Твоја, и воистину смирил мја јеси."}, {"num": "76.", "text": "Буди же милост Твоја, да утјешит мја по словеси Твојему, рабу Твојему."}, {"num": "77.", "text": "Да пријидут мње шчедроти Твоја, и жив буду, јако закон Твој поученије моје јест."}, {"num": "78.", "text": "Да постидјатсја гордији, јако неправедно безаконоваша на мја, аз же поглумљусја в заповједех Твојих."}, {"num": "79.", "text": "Да обратјат мја бојашчијисја Тебе, и вједјашчији свидјенија Твоја."}, {"num": "80.", "text": "Буди сердце моје непорочно во оправданијих Твојих, јако да не постижусја."}, {"num": "81.", "text": "Изчезајет во спасеније Твоје душа моја, на словеса Твоја уповах."}, {"num": "82.", "text": "Исчезоша очи моји в слово Твоје, глагољушче: Когда утјешиши мја."}, {"num": "83.", "text": "Зане бих јако мјех на слање, оправданиј Твојих не забих."}, {"num": "84.", "text": "Колико јест днеј раба Твојего, когда сотвориши ми от гоњашчих мја суд."}, {"num": "85.", "text": "Повједаша мње законопреступници глумљенија, но не јако закон Твој Господи."}, {"num": "86.", "text": "Всја заповједи Твоја истина, неправедно прогнаша мја, помози ми."}, {"num": "87.", "text": "Вмаље не скончаша мене на земљи, аз же не оставих заповједеј Твојих."}, {"num": "88.", "text": "По милости Твојеј живи мја, и сохрању свидјенија уст Твојих."}, {"num": "89.", "text": "Во вјек Господ слово Твоје пребивајет на небеси."}, {"num": "90.", "text": "В род и род истина Твоја, основал јеси земљу, и пребивајет."}, {"num": "91.", "text": "Учиненијем Твојим пребивајет ден, јако всјаческаја работна Тебје."}, {"num": "92.", "text": "Јако ашче би не закон Твој поученије моје бил, тогда убо погибал бих во смиренији мојем."}, {"num": "93.", "text": "Во вјек не забуду оправданиј Твојих, јако в њих оживил мја јеси. СРЕДА"}, {"num": "94.", "text": "Твој јесам аз, спаси мја, јако оправданиј Твојих взисках."}, {"num": "95.", "text": "Мене ждаша грјешници погубити мја, свидјенија Твоја разумјех."}, {"num": "96.", "text": "Всјакија кончини видјех конец, широка заповјед Твоја зјело."}, {"num": "97.", "text": "Кољ возљубих закон Твој Господи, вес ден поученије моје јест."}, {"num": "98.", "text": "Паче враг мојих умудрил мја јеси заповједију Твојеју, јако во вјек моја јест."}, {"num": "99.", "text": "Паче всјех учашчих мја разумјех, јако свидјенија Твоја поученије моје јест."}, {"num": "100.", "text": "Паче старец разумјех, јако заповједи Твоја взисках."}, {"num": "101.", "text": "От всјакаго пути лукава возбраних ногам мојим, јако да сохрању словеса Твоја."}, {"num": "102.", "text": "От судеб Твојих не уклонихсја, јако Ти законоположил ми јеси."}, {"num": "103.", "text": "Кољ сладка гортани мојему словеса Твоја, паче меда устом мојим."}, {"num": "104.", "text": "От заповједи Твојих разумјех, сего ради возненавидјех всјак пут неправди."}, {"num": "105.", "text": "Свјетилник ногама мојима закон Твој, и свјет стезјам мојим."}, {"num": "106.", "text": "Кљахсја, и поставих сохранити судби правди Твојеја."}, {"num": "107.", "text": "Смирихсја до зјела, Господи, живи мја по словеси Твојему."}, {"num": "108.", "text": "Вољнаја уст мојих, благоволи же Господи, и судбам Твојим научи мја."}, {"num": "109.", "text": "Душа моја в руку Твојеју вину, и закона Твојего не забих."}, {"num": "110.", "text": "Положиша грјешници сјет мње, и от заповједеј Твојих не заблудих."}, {"num": "111.", "text": "Насљедовах свидјенија Твоја во вјек, јако радованије сердца мојего сут."}, {"num": "112.", "text": "Приклоних сердце моје, сотворити оправданија Твоја во вјек за воздајаније."}, {"num": "113.", "text": "Законопреступнија вознснавидјех, закон же Твој возљубих."}, {"num": "114.", "text": "Помошчник мој и заступник мој јеси Ти, на словеса Твоја уповах."}, {"num": "115.", "text": "Уклонитесја от мене лукавнујушчији, и испитају заповједи Бога мојего."}, {"num": "116.", "text": "Заступи мја по словеси Твојему, и жив буду, и не посрами мене от чајанија мојего."}, {"num": "117.", "text": "Помози ми, и спасусја, и поучусја во оправданијих Твојих вину."}, {"num": "118.", "text": "Уничижил јеси всја отступајушчија от оправданиј Твојих, јако неправедно помишљеније их."}, {"num": "119.", "text": "Преступајушчија непшчевах всја грјешнија земљи, сего ради возљубих свидјенија Твоја."}, {"num": "120.", "text": "Пригвозди сграху Твојему плоти моја, от судеб бо Твојих убојахсја."}, {"num": "121.", "text": "Сотворих суд и правду, не предажд мене обидјашчим мја."}, {"num": "122.", "text": "Восприми раба Твојего во благо, да не оклеветајут мене гордији."}, {"num": "123.", "text": "Оче моји исчезостје во спасеније Твоје, и в слово правди Твојеја."}, {"num": "124.", "text": "Сотвори с рабом Твојим по милости Твојеј, и оправданијем Твојим научи мја."}, {"num": "125.", "text": "Раб Твој јесам аз, вразуми мја, и увјем свидјенија Твоја."}, {"num": "126.", "text": "Времја сотворити Господеви, разориша закон Твој."}, {"num": "127.", "text": "Сего ради возљубих заповједи Твоја паче злата и топазија."}, {"num": "128.", "text": "Сего ради ко всјем заповједем Твојим направљахусја, всјак пут неправди возненавидјех."}, {"num": "129.", "text": "Дивна свидјенија Твоја, сего ради испита ја душа моја."}, {"num": "130.", "text": "Јављеније словес Твојих просвјешчајет и вразумљајет младенци."}, {"num": "131.", "text": "Уста моја отверзох, и привлекох дух, јако заповједеј Твојих жељах. Слава:"}, {"num": "132.", "text": "Призри на мја и помилуј мја, по суду љубјашчих имја Твоје."}, {"num": "133.", "text": "Стопи моја направи по словеси Твојему, и да не обладајет мноју всјакоје безаконије."}, {"num": "134.", "text": "Избави мја от клевети человјеческија, и сохрању заповједи Твоја."}, {"num": "135.", "text": "Лице Твоје просвјети на раба Твојего, и научи мја оправданијем Твојим."}, {"num": "136.", "text": "Исходишча воднаја изведостје очи моји, понеже не сохраних закона Твојего."}, {"num": "137.", "text": "Праведен јеси Господи, и прави суди Твоји."}, {"num": "138.", "text": "Заповједал јеси правду свидјенија Твоја, и истину зјело."}, {"num": "139.", "text": "Истајала мја јест ревност Твоја, јако забиша словеса Твоја врази моји."}, {"num": "140.", "text": "Разжежено слово Твоје зјело, и раб Твој возљуби је."}, {"num": "141.", "text": "Јуњејшиј аз јесам и уничижен, оправданиј Твојих не забих."}, {"num": "142.", "text": "Правда Твоја правда во вјек, и закон Твој истина."}, {"num": "143.", "text": "Скорби и нужди обрјетоша мја, заповједи Твоја поученије моје."}, {"num": "144.", "text": "Правда свидјенија Твоја во вјек, вразуми мја, и жив буду."}, {"num": "145.", "text": "Возвах всјем сердцем мојим, услиши мја Господи, оправданија Твоја взишчу."}, {"num": "146.", "text": "Возвах Ти, спаси мја, и сохрању свидјенија Твоја."}, {"num": "147.", "text": "Предварих в безгодији, и возвах, на словеса Твоја уповах."}, {"num": "148.", "text": "Предваристје очи моји ко јутру, поучитисја словесем Твојим."}, {"num": "149.", "text": "Глас мој услиши Господи по милости Твојеј, по судбје Твојеј живи мја."}, {"num": "150.", "text": "Приближишасја гоњашчији мја безаконијем, от закона же Твојего удаљишасја."}, {"num": "151.", "text": "Близ јеси Ти Господи, и вси путије Твоји истина."}, {"num": "152.", "text": "Исперва познах от свидјениј Твојих, јако во вјек основал ја јеси."}, {"num": "153.", "text": "Вижд смиреније моје, и изми мја, јако закона Твојего не забих."}, {"num": "154.", "text": "Суди суд мој, и избави мја, словесе ради Твојего живи мја."}, {"num": "155.", "text": "Далече от грјешник спасеније, јако оправданиј Твојих не взискаша."}, {"num": "156.", "text": "Шчедроти Твоја многи Господи, по судбје Твојеј живи мја."}, {"num": "157.", "text": "Мнози изгоњашчији мја и стужајушчији ми, от свидјениј Твојих не уклонихсја."}, {"num": "158.", "text": "Видјех неразумјевајушчија, и истајах, јако словес Твојих не сохраниша."}, {"num": "159.", "text": "Вижд, јако заповједи Твоја возљубих, Господи по милости Твојеј живи мја."}, {"num": "160.", "text": "Начало словес Твојих истина, и во вјек веја судби правди Твојеја."}, {"num": "161.", "text": "Књази погнаша мја туне, и от словес Твојих убојасја сердце моје."}, {"num": "162.", "text": "Возрадујусја аз о словесјех Твојих, јако обрјетајај корист многу."}, {"num": "163.", "text": "Неправду возненавидјех и омерзих, закон же Твој возљубих."}, {"num": "164.", "text": "Седмерицеју днем хвалих Тја о судбах правди Твојеја."}, {"num": "165.", "text": "Мир многи љубјашчим закон Твој, и њест им соблазна."}, {"num": "166.", "text": "Чајах спасенија Твојего Господи, и заповједи Твоја возљубих."}, {"num": "167.", "text": "Сохрани душа моја свидјенија Твоја, и возљуби ја зјело."}, {"num": "168.", "text": "Сохраних заповједи Твоја и свидјенија Твоја, јако вси путије моји пред Тобоју Господи."}, {"num": "169.", "text": "Да приближитсја мољеније моје пред Тја, Господи, по словеси Твојему вразуми мја."}, {"num": "170.", "text": "Да внидет прошеније моје пред Тја, Господи по словеси Твојему избави мја."}, {"num": "171.", "text": "Отригнут устње моји пјеније, јегда научиши мја оправданијем Твојим."}, {"num": "172.", "text": "Провјешчајет јазик мој словеса Твоја, јако всја заповједи Твоја правда."}, {"num": "173.", "text": "Да будет рука Твоја јеже спасти мја, јако заповједи Твоја изволих."}, {"num": "174.", "text": "Возжељах спасеније Твоје Господи, и закон Твој поученије моје јест."}, {"num": "175.", "text": "Жива будет душа моја, и восхвалит Тја, и судби Твоја помогут мње."}, {"num": "176.", "text": "Заблудих јако овча погибшеје, взишчи раба Твојего, јако заповједеј Твојих не забих. Слава:"}]}, "119": {"number": 119, "title": "Псалом 119. (119)", "subtitle": "", "verses": [{"num": "1.", "text": "Ко Господу, внегда скорбјети ми, возвах, и услиша мја."}, {"num": "2.", "text": "Господи, избави душу моју от устен неправедних, и от јазика лестива."}, {"num": "3.", "text": "Что дастсја тебје, или что приложитсја тебје к јазику лестиву."}, {"num": "4.", "text": "Стрјели силнаго изошчрени, со угљими пустиними."}, {"num": "5.", "text": "Уви мње, јако пришелствије моје продолжисја, вселихсја со сељенији Кидарскими."}, {"num": "6.", "text": "Много пришелствова душа моја, со ненавидјашчими мира бјех мирен."}, {"num": "7.", "text": "Јегда глагољах им, борјаху мја туне."}]}, "120": {"number": 120, "title": "Псалом 120. (120)", "subtitle": "", "verses": [{"num": "1.", "text": "Возведох очи моји в гори, отњудуже пријидет помошч моја."}, {"num": "2.", "text": "Помошч моја от Господа, сотворшаго небо и земљу."}, {"num": "3.", "text": "Не дажд во смјатеније ноги твојеја, ниже воздремљет храњај тја."}, {"num": "4.", "text": "Се не воздремљет, ниже уснет храњај Израиља."}, {"num": "5.", "text": "Господ сохранит тја, Господ покров твој на руку деснују твоју."}, {"num": "6.", "text": "Во дни солнце не ожежет тебе, ниже луна ношчију."}, {"num": "7.", "text": "Господ сохранит тја от всјакаго зла, сохранит душу твоју Господ."}, {"num": "8.", "text": "Господ сохранит вхожденије твоје, и исхожденије твоје от ниње и до вјека."}]}, "121": {"number": 121, "title": "Псалом 121. (121)", "subtitle": "", "verses": [{"num": "1.", "text": "Возвеселихсја о рекших мње: В дом Господен појдем."}, {"num": "2.", "text": "Стојашче бјаху ноги нашја во дворјех твојих Јерусалиме."}, {"num": "3.", "text": "Јерусалим зиждемиј јако град, јемуже причастије јего вкупје."}, {"num": "4.", "text": "Тамо бо взидоша кољена, кољена Господња, свидјеније Израиљево, исповједатисја имени Господњу."}, {"num": "5.", "text": "Јако тамо сједоша престоли на суд, престоли в дому Давидовје."}, {"num": "6.", "text": "Вопросите же јаже о мирје Јерусалима, и обилије љубјашчим тја."}, {"num": "7.", "text": "Буди же мир в сиље твојеј и обилије во столпостјенах твојих."}, {"num": "8.", "text": "Ради братији мојих и ближњих мојих, глагољах убо мир о тебје."}, {"num": "9.", "text": "Дому ради Господа Бога нашего взисках благаја тебје."}]}, "122": {"number": 122, "title": "Псалом 122. (122)", "subtitle": "", "verses": [{"num": "1.", "text": "К Тебје возведох очи моји, живушчему на небеси."}, {"num": "2.", "text": "Се јако очи раб в руку господиј својих, јако очи рабини в руку госпожи својеја, тако очи наши ко Господу Богу нашему, дондеже ушчедрит ни."}, {"num": "3.", "text": "Помилуј нас Господи, помилуј нас, јако помногу исполнихомсја уничиженија."}, {"num": "4.", "text": "Најпаче наполнисја душа наша поношенија гобзујушчих, и уничиженија горких."}]}, "123": {"number": 123, "title": "Псалом 123. (123)", "subtitle": "", "verses": [{"num": "1.", "text": "Јако ашче не Господ би бил в нас, да речeт убо Израиљ."}, {"num": "2.", "text": "Јако ашче не Господ би бил в нас, внегда востати человјеком на ни, убо живих пожерли биша нас."}, {"num": "3.", "text": "Внегда прогњеватисја јарости их на ни, убо вода потопила би нас."}, {"num": "4.", "text": "Поток прејде душа наша."}, {"num": "5.", "text": "Убо прејде душа наша воду непостојанују."}, {"num": "6.", "text": "Благословен Господ, иже не даде нас в ловитву зубом их."}, {"num": "7.", "text": "Душа наша јако птица избависја от сјети ловјашчих, сјет сокрушисја, и ми избављени бихом."}, {"num": "8.", "text": "Помошч наша во имја Господа, сотворшаго небо и земљу. Слава:"}]}, "124": {"number": 124, "title": "Псалом 124. (124)", "subtitle": "", "verses": [{"num": "1.", "text": "Надјејушчијисја на Господа, јако гора Сион, не подвижитсја во вјек, живиј во Јерусалимје."}, {"num": "2.", "text": "Гори окрест јего, и Господ окрест људеј својих, от ниње и до вјека."}, {"num": "3.", "text": "Јако не оставит Господ жезла грјешних на жребиј праведних, јако да не прострут праведнији во безаконија рук својих."}, {"num": "4.", "text": "Ублажи Господи благија и правија сердцем."}, {"num": "5.", "text": "Уклоњајушчијасја же в разврашченија отведет Господ с дјелајушчими безаконије, мир на Израиља."}]}, "125": {"number": 125, "title": "Псалом 125. (125)", "subtitle": "", "verses": [{"num": "1.", "text": "Внегда возвратити Господу пљен Сион, бихом јако утјешени."}, {"num": "2.", "text": "Тогда исполнишасја радости уста наша, и јазик наш веселија, тогда рекут во јазицјех: Возвеличил јест Господ сотворити с њими."}, {"num": "3.", "text": "Возвеличил јест Господ сотворити с нами, бихом весељашчесја."}, {"num": "4.", "text": "Возврати Господи пљененије наше, јако потоки југом."}, {"num": "5.", "text": "Сјејушчији слезами, радостију пожнут."}, {"num": "6.", "text": "Ходјашчији хождаху и плакахусја, метајушче сјемена своја, грјадушче же пријидут радостију, вземљушче рукојати своја."}]}, "126": {"number": 126, "title": "Псалом 126. (126)", "subtitle": "", "verses": [{"num": "1.", "text": "Ашче не Господ созиждет дом, всује трудишасја зиждушчији, ашче не Господ сохранит град, всује бдје стрегиј."}, {"num": "2.", "text": "Всује вам јест јутрењевати, востанете по сједјенији, јадушчији хљеб бољезни, јегда даст возљубљеним својим сон."}, {"num": "3.", "text": "Се достојаније Господње синове, мазда плода чревнаго."}, {"num": "4.", "text": "Јако стрјели в рупје силнаго, тако синове отрјасених."}, {"num": "5.", "text": "Блажен, иже исполнит желаније своје от њих, не постидјатсја, јегда глагољут врагом својим во вратјех."}]}, "127": {"number": 127, "title": "Псалом 127. (127)", "subtitle": "", "verses": [{"num": "1.", "text": "Блажени вси бојашчијисја Господа, ходјашчији в путех Јего."}, {"num": "2.", "text": "Труди плодов твојих сњеси, блажен јеси, и добро тебје будет."}, {"num": "3.", "text": "Жена твоја јако лоза плодовита в странах дому твојего."}, {"num": "4.", "text": "Синове твоји јако новосажденија масличнаја окрест трапези твојеја."}, {"num": "5.", "text": "Се тако благословитсја человјек бојајсја Господа."}, {"num": "6.", "text": "Благословит тја Господ от Сиона, и узриши благаја Јерусалима всја дни живота твојего."}, {"num": "7.", "text": "И узриши сини синов твојих, мир на Израиља."}]}, "128": {"number": 128, "title": "Псалом 128. (128)", "subtitle": "", "verses": [{"num": "1.", "text": "Множицеју брашасја со мноју от јуности мојеја, да речет убо Израиљ."}, {"num": "2.", "text": "Множицеју брашасја со мноју от јуности мојеја, ибо не премогоша мја."}, {"num": "3.", "text": "На хребтје мојем дјелаша грјешници, продолжиша безаконије своје."}, {"num": "4.", "text": "Господ праведен сосјече вија грјешников."}, {"num": "5.", "text": "Да постидјатсја и возвратјатсја вспјат вси ненавидјашчији Сиона."}, {"num": "6.", "text": "Да будут јако трава на здјех, јаже прежде восторженија изсуше."}, {"num": "7.", "text": "Јејуже не исполни руки својеја жњај, и њедра свјего рукојати собирајај."}, {"num": "8.", "text": "И не рјеша мимоходјашчији, благословеније Господње на ви, благословихом ви во имја Господње. Слава:"}]}, "129": {"number": 129, "title": "Псалом 129. (129)", "subtitle": "", "verses": [{"num": "1.", "text": "Из глубини возвах к Тебје Господи, Господи услиши глас мој."}, {"num": "2.", "text": "Да будут уши Твоји внемљушчје гласу мољенија мојего."}, {"num": "3.", "text": "Ашче безаконија назриши Господи, Господи кто постојит, јако у Тебе очишченије јест."}, {"num": "4.", "text": "Имене ради Твојего потерпјех Тја, Господи, потерпје душа моја в слово Твоје, упова душа моја на Господа."}, {"num": "5.", "text": "От стражи јутренија до ношчи, от стражи јутренија, да уповајет Израиљ на Господа."}, {"num": "6.", "text": "Јако у Господа милост, и многоје у Њего избављеније, и Тој избавит Израиља от всјех безакониј јего."}]}, "130": {"number": 130, "title": "Псалом 130. (130)", "subtitle": "", "verses": [{"num": "1.", "text": "Господи, не вознесесја сердце моје, ниже вознесостјесја очи моји, ниже ходих во великих, ниже во дивних паче мене."}, {"num": "2.", "text": "Ашче не смиреномудрствовах, но вознесох душу моју, јако отдојеноје на матер своју, тако воздаси на душу моју."}, {"num": "3.", "text": "Да уповајет Израиљ на Господа, от ниње и до вјека."}]}, "131": {"number": 131, "title": "Псалом 131. (131)", "subtitle": "", "verses": [{"num": "1.", "text": "Помјани Господи Давида и всју кротост јего."}, {"num": "2.", "text": "Јако кљатсја Господеви, објешчасја Богу Јаковљу."}, {"num": "3.", "text": "Ашче вниду в сељеније дому мојего, или взиду на одар постељи мојеја."}, {"num": "4.", "text": "Ашче дам сон очима мојима, и вјеждома мојима дреманије, и покој скранијама мојима."}, {"num": "5.", "text": "Дондеже обрјашчу мјесто Господеви, сељеније Богу Јаковљу."}, {"num": "6.", "text": "Се слишахом ја во Евфратје, обрјетохом ја в пољах дубрави."}, {"num": "7.", "text": "Внидем во сељенија Јего, поклонимсја на мјесто, идјеже стојастје нозје Јего."}, {"num": "8.", "text": "Воскресни Господи в покој Твој, Ти и кивот свјатињи Твојеја."}, {"num": "9.", "text": "Свјашченици Твоји облекутсја правдоју, и преподобнији Твоји возрадујутсја."}, {"num": "10.", "text": "Давида ради раба Твојего, не отврати лице помазанаго Твојего."}, {"num": "11.", "text": "Кљатсја Господ Давиду истиноју, и не отвержетсја јеја: От плода чрева твојего посажду на престоље твојем."}, {"num": "12.", "text": "Ашче сохрањат синове твоји завјет Мој, и свидјенија Моја сија, имже научу ја, и синове их до вјека сјадут на престоље твојем."}, {"num": "13.", "text": "Јако избра Господ Сиона, изволи их в жизишче себје."}, {"num": "14.", "text": "Сеј покој мој во вјек вјека, здје всељусја, јако изволих их."}, {"num": "15.", "text": "Ловитву јего благословљајај благословљу, нишчија јего насишчу хљеби."}, {"num": "16.", "text": "Свјашченики јего облеку во спасеније, и преподобнији јего радостију возрадујутсја."}, {"num": "17.", "text": "Тамо возврашчу рог Давидови, уготовах свјетилник помазаному мојему."}, {"num": "18.", "text": "Враги јего облеку студом, на њемже процвјетет свјатиња Моја."}]}, "132": {"number": 132, "title": "Псалом 132. (132)", "subtitle": "", "verses": [{"num": "1.", "text": "Се что добро или что красно, но јеже жити братији вкупје."}, {"num": "2.", "text": "Јако миро на главје, сходјашчеје на браду, браду Ароњу, сходјашчеје на омети одежди јего."}, {"num": "3.", "text": "Јако роса Аермонскаја сходјашчаја на гори Сионскија, јако тамо заповједа Господ благословеније и живот до вјека."}]}, "133": {"number": 133, "title": "Псалом 133. (133)", "subtitle": "", "verses": [{"num": "1.", "text": "Се ниње благословите Господа вси раби Господи, стојашчији во храмје Господњи, во дворјех дому Бога нашего."}, {"num": "2.", "text": "В ношчех воздјежите руки вашја во свјатаја, и благословите Господа."}, {"num": "3.", "text": "Благословит тја Господ от Сиона, сотворивиј небо и земљу. Слава:"}]}, "134": {"number": 134, "title": "Псалом 134. (134)", "subtitle": "", "verses": [{"num": "1.", "text": "Хвалите имја Господње, хвалите раби Господа."}, {"num": "2.", "text": "Стојашчији во храмје Господњи, во дворјех дому Бога нашего."}, {"num": "3.", "text": "Хвалите Господа, јако благ Господ, појте имени Јего, јако добро."}, {"num": "4.", "text": "Јако Јакова избра себје Господ, Израиља в достојаније себје."}, {"num": "5.", "text": "Јако аз познах, јако велиј Господ, и Господ наш над свјеми боги."}, {"num": "6.", "text": "Всја јелика восхотје Господ сотвори на небеси и на земљи, в морјах и во всјех безднах."}, {"num": "7.", "text": "Возводја облаки от посљедних земљи, молнији в дожд сотвори, изводјај вјетри от сокровишч својих."}, {"num": "8.", "text": "Иже порази первенци Египетскија, от человјека до скота."}, {"num": "9.", "text": "Посла знаменија и чудеса посредје тебе Египте, на фараона и на всја раби јего."}, {"num": "10.", "text": "Иже норази јазики многи, и изби цари крјепки."}, {"num": "11.", "text": "Сиона царја Аморејска, и Ога царја Васанска, и всја царствија Хананска."}, {"num": "12.", "text": "И даде земљу их достојаније, достојаније Израиљу, људем својим."}, {"num": "13.", "text": "Господи, имја Твоје во вјек, и памјат Твоја в род и род."}, {"num": "14.", "text": "Јако судити имат Господ људем својим, и о рабјех својих умолитсја."}, {"num": "15.", "text": "Идоли јазик сребро и злато, дјела рук человјеческих."}, {"num": "16.", "text": "Уста имут и не возглагољут, очи имут и не узрјат."}, {"num": "17.", "text": "Уши имут и не услишат, ниже бо јест дух во устјех их."}, {"num": "18.", "text": "Подобни им да будут творјашчији ја, и вси надјејушчијисја на ња."}, {"num": "19.", "text": "Доме Израиљев, благословите Господа, доме Арон благословите Господа, доме Левијин благословите Господа."}, {"num": "20.", "text": "Бојашчијисја Господа, благословите Господа."}, {"num": "21.", "text": "Благословен Господ от Сиона, живиј во Јерусалимје."}]}, "135": {"number": 135, "title": "Псалом 135. (135)", "subtitle": "", "verses": [{"num": "1.", "text": "Исповједајтесја Господеви, јако благ, јако во вјек милост Јего."}, {"num": "2.", "text": "Исповједајтесја Богу богов, јако во вјек милост Јего."}, {"num": "3.", "text": "Исповједајтесја Господеви господеј, јако во вјек милост Јего."}, {"num": "4.", "text": "Сотворшему чудеса велија јединому, јако во вјек милост Јего."}, {"num": "5.", "text": "Сотворшему Небеса разумом, јако во вјек милост Јего."}, {"num": "6.", "text": "Утвердившему Земљу на водах, јако во вјек милост Јего."}, {"num": "7.", "text": "Сотворшему свјетила велија јединому, јако во вјек милост Јего."}, {"num": "8.", "text": "Солнце во област дне, јако во вјек милост Јего."}, {"num": "9.", "text": "Луну и звјезди во област ношчи, јако во вјек милост Јего."}, {"num": "10.", "text": "Поразившему Египта с первенци јего, јако во вјек милост Јего."}, {"num": "11.", "text": "И изведшему Израиља от среди их, јако во вјек милост Јего."}, {"num": "12.", "text": "Рукоју крјепкоју и мишцеју високоју, јако во вјек милост Јего."}, {"num": "13.", "text": "Раздјелшему Чермноје море в раздјељенија, јако во вјек милост Јего."}, {"num": "14.", "text": "И проведшему Израиља посредје јего, јако во вјек милост Јего."}, {"num": "15.", "text": "И истрјасшему фараона и силу јего в море Чермноје, јако во вјек милост Јего."}, {"num": "16.", "text": "Проведшему људи своја в пустињи, јако во вјек милост Јего."}, {"num": "17.", "text": "Поразившему цари велија, јако во вјек милост Јего."}, {"num": "18.", "text": "И убившему цари крјепкија, јако во вјек милост Јего."}, {"num": "19.", "text": "Сиона царја Аморејска, јако во вјек милост Јего."}, {"num": "20.", "text": "И Ога царја Васанска, јако во вјек милост Јего."}, {"num": "21.", "text": "И давшему земљу их достојаније, јако во вјек милост Јего."}, {"num": "22.", "text": "Достојаније Израиљу рабу својему, јако во вјек милост Јего."}, {"num": "23.", "text": "Јако во смиренији нашем помјану ни Господ, јако во вјек милост Јего."}, {"num": "24.", "text": "И избавил ни јест од врагов наших, јако во вјек милост Јего."}, {"num": "25.", "text": "Дајај пишчу всјакој плоти, јако во вјек милост Јего."}, {"num": "26.", "text": "Исповједајтесја Богу Небесному, јако во вјек милост Јего."}]}, "136": {"number": 136, "title": "Псалом 136. (136)", "subtitle": "", "verses": [{"num": "1.", "text": "На рјеках Вавилонских, тамо сједохом и плакахом, внегда помјанути нам Сиона."}, {"num": "2.", "text": "На вербијих посредје јего објесихом органи нашја."}, {"num": "3.", "text": "Јако тамо вопросиша ни, пљеншији нас, о словесјех пјеснеј, и ведшији нас о пјенији, воспојте нам от пјеснеј Сионских."}, {"num": "4.", "text": "Како воспојем пјесан Господњу на земљи чуждеј."}, {"num": "5.", "text": "Ашче забуду тебе Јерусалиме, забвена буди десница моја."}, {"num": "6.", "text": "Прилпни јазик мој гортани мојему, ашче не помјану тебе, ашче не предложу Јерусалима, јако в начаље веселија мојего."}, {"num": "7.", "text": "Помјани Господи сини Едомскија в ден Јерусалимл глагољушчија: Истошчајте, истошчајте до основанији јего."}, {"num": "8.", "text": "Дшчи Вавилоња окајанаја, блажен иже воздаст тебје воздајаније твоје, јеже воздала јеси нам."}, {"num": "9.", "text": "Блажен иже имет и разбијет младенци твоја о камен. Слава:"}]}, "137": {"number": 137, "title": "Псалом 137. (137)", "subtitle": "", "verses": [{"num": "1.", "text": "Исповјемсја Тебје Господи всјем сердцем мојим, и пред ангели воспоју Тебје, јако услишал јеси всја глаголи уст мојих."}, {"num": "2.", "text": "Поклоњусја ко храму свјатому Твојему, и исповјемсја имени Твојему о милости Твојеј и истиње Твојеј. Јако возвеличил јеси над всјем имја Твоје свјатоје."}, {"num": "3.", "text": "В оњже ашче ден призову Тја, скоро услиши мја, умножиши мја в души мојеј силоју Твојеју."}, {"num": "4.", "text": "Да исповједјатсја Тебје Господи вси царије земстији, јако услишаша всја глаголи уст Твојих."}, {"num": "5.", "text": "И воспојут в путех Господњих, јако велија слава Господња."}, {"num": "6.", "text": "Јако висок Господ, и смиренија призирајет, и високаја издалеча вјест."}, {"num": "7.", "text": "Ашче појду посредје скорби, живиши мја, на гњев враг мојих простерл јеси руку Твоју, и спасе мја десница Твоја."}, {"num": "8.", "text": "Господ воздаст за мја, Господи милост Твоја во вјек, дјел руку Твојеју не презри."}]}, "138": {"number": 138, "title": "Псалом 138. (138)", "subtitle": "", "verses": [{"num": "1.", "text": "Господи, искусил мја јеси, и познал мја јеси, Ти познал јеси сједаније моје и востаније моје."}, {"num": "2.", "text": "Ти разумјел јеси помишљенија моја издалеча."}, {"num": "3.", "text": "Стезју моју и уже моје Ти јеси изсљедовал, и всја пути моја провидјел јеси."}, {"num": "4.", "text": "Јако њест лести в јазицје мојем, се Господи Ти познал јеси."}, {"num": "5.", "text": "Всја посљедњаја и древнаја, Ти создал јеси мја, и положил јеси на мње руку Твоју."}, {"num": "6.", "text": "Удивисја разум Твој от мене, утвердисја, не возмогу к њему."}, {"num": "7.", "text": "Камо појду от Духа Твојего, и от лица Твојего камо бјежу."}, {"num": "8.", "text": "Ашче взиду на небо, Ти тамо јеси, ашче сниду во ад, тамо јеси."}, {"num": "9.", "text": "Ашче возму криље моји рано, и всељусја в посљедних морја:"}, {"num": "10.", "text": "И тамо бо рука Твоја наставит мја, и удержит мја десница Твоја."}, {"num": "11.", "text": "И рјех: Еда тама поперет мја, и ношч просвјешченије в сладости мојеј."}, {"num": "12.", "text": "Јако тама не помрачитсја от Тебе, и ношч јако ден просвјетитсја, јако тама јеја, тако и свјет јеја."}, {"num": "13.", "text": "Јако Ти создал јеси утроби моја, воспријал мја јеси из чрева матере мојеја."}, {"num": "14.", "text": "Исповјемсја Тебје, јако страшно удивилсја јеси: чудна дјела Твоја, и душа моја знајет зјело."}, {"num": "15.", "text": "Не утајисја кост моја от Тебе, јуже сотворил јеси в тајње, и состав мој в преисподњих земљи."}, {"num": "16.", "text": "Несодјеланоје моје видјестје очи Твоји, и в књизје Твојеј вси напишутсја, в днех созиждутсја, и никтоже в њих."}, {"num": "17.", "text": "Мње же зјело честни биша друзи Твоји Боже, зјело утвердишасја владичествија их."}, {"num": "18.", "text": "Изочту их, и паче песка умножатсја, востах, и јешче јесам с Тобоју."}, {"num": "19.", "text": "Ашче избијеши грјешники Боже, мужије кровеј уклонитесја от мене."}, {"num": "20.", "text": "Јако ревниви јесте в помишљенијих, пријимут в сујету гради Твоја."}, {"num": "21.", "text": "Не ненавидјашчија ли Тја Господи возненавидјех, и о вразјех Твојих истајах."}, {"num": "22.", "text": "Совершеноју ненавистију возненавидјех ја, во враги биша ми."}, {"num": "23.", "text": "Искуси мја Боже, и увјежд сердце моје, истјажи мја, и разумјеј стези моја."}, {"num": "24.", "text": "И вижд, ашче пут безаконија во мње, и настави мја на пут вјечен."}]}, "139": {"number": 139, "title": "Псалом 139. (139)", "subtitle": "", "verses": [{"num": "1.", "text": "Изми мја Господи от человјека лукава, от мужа неправедна избави мја."}, {"num": "2.", "text": "Иже помислиша неправду в сердцје, вес ден ополчаху брани."}, {"num": "3.", "text": "Изостриша јазик свој јако змијин, јад аспидов под устнами их."}, {"num": "4.", "text": "Сохрани мја Господи из руки грјешничи, от человјек неправедних изми мја, иже помислиша запјати стопи моја."}, {"num": "5.", "text": "Скриша гордији сјет мње, и ужи препјаша сјет ногама мојима."}, {"num": "6.", "text": "При стези соблазни положиша ми."}, {"num": "7.", "text": "Рјех Господеви: Бог мој јеси Ти, внуши Господи глас мољенија мојего."}, {"num": "8.", "text": "Господи Господи, сило спасенија мојего, осјенил јеси над главоју мојеју в ден брани."}, {"num": "9.", "text": "Не предажд мене Господи от желанија мојего грјешнику, помислиша на мја, не остави мене, да не когда вознесутсја."}, {"num": "10.", "text": "Глава окруженија их, труд устен их покријет ја."}, {"num": "11.", "text": "Падут на њих угљија огњенаја, низложиши ја в страстех, и не постојат."}, {"num": "12.", "text": "Муж јазичен не исправитсја на земљи, мужа неправедна злаја уловјат во истљеније."}, {"num": "13.", "text": "Познах, јако сотворит Господ суд нишчим, и мест убогим."}, {"num": "14.", "text": "Обаче праведнији исповједјатсја имени Твојему, и всељатсја правији с лицем Твојим. Слава:"}]}, "140": {"number": 140, "title": "Псалом 140. (140)", "subtitle": "", "verses": [{"num": "1.", "text": "Господи возвах к Тебје услиши мја, вонми гласу мољенија мојего, внегда возвати ми к Тебје."}, {"num": "2.", "text": "Да исправитсја молитва моја, јако кадило пред Тобоју, воздјејаније руку мојеју жертва вечерњаја."}, {"num": "3.", "text": "Положи Господи храњеније устом мојим, и двер огражденија о устнах мојих."}, {"num": "4.", "text": "Не уклони сердце моје в словеса лукавстија, непшчевати вини о грјесјех, с человјеки дјелајушчими безаконије, и не сочтусја со избраними их."}, {"num": "5.", "text": "Накажет мја праведник милостију и обличит мја, јелеј же грјешнаго да не намастит глави мојеја, јако јешче и молитва моја во благовољенијих их."}, {"num": "6.", "text": "Пожерти биша при камени судији их, услишатсја глаголи моји, јако возмогоша."}, {"num": "7.", "text": "Јако толшча земљи просједесја на земљи, расточишасја кости их при адје."}, {"num": "8.", "text": "Јако к Тебје, Господи, Господи, очи моји, на Тја уповах, не отими душу моју."}, {"num": "9.", "text": "Сохрани мја от сјети, јуже составиша ми, и от соблазан дјелајушчијих безаконије."}, {"num": "10.", "text": "Падут во мрежу своју грјешници, једин јесам аз, дондеже прејду."}]}, "141": {"number": 141, "title": "Псалом 141. (141)", "subtitle": "", "verses": [{"num": "1.", "text": "Гласом мојим ко Господу возвах, гласом мојим ко Господу помолихсја."}, {"num": "2.", "text": "Пролију пред Њим мољеније моје, печал моју пред Њим возвјешчу."}, {"num": "3.", "text": "Внегда исчезати от мене духу мојему, и Ти познал јеси стези моја, на пути сем, по њемуже хождах, скриша сјет мње."}, {"num": "4.", "text": "Смотрјах одеснују и возгљадах, и не бје знајај мене. Погибе бјегство от мене, и њест взискајај душу моју."}, {"num": "5.", "text": "Возвах к Тебје Господи, рјех: Ти јеси упованије моје, част моја јеси на земљи живих."}, {"num": "6.", "text": "Вонми мољенију мојему, јако смирихсја зјело, избави мја от гоњашчих мја, јако укрјепишасја паче мене."}, {"num": "7.", "text": "Изведи из темници душу моју, исповједатисја имени Твојему. Мене ждут праведници, дондеже воздаси мње."}]}, "142": {"number": 142, "title": "Псалом 142. (142)", "subtitle": "", "verses": [{"num": "1.", "text": "Господи услиши молитву моју, внуши мољеније моје во истиње Твојеј, услиши мја в правдје Твојеј."}, {"num": "2.", "text": "И не вниди в суд с рабом Твојим, јако не оправдитсја пред Тобоју всјак живиј."}, {"num": "3.", "text": "Јако погна враг душу моју, смирил јест в земљу живот мој, посадил мја јест в темних, јако мертвија от вјека."}, {"num": "4.", "text": "И уни во мње дух мој, во мње смјатесја сердце моје."}, {"num": "5.", "text": "Помјанух дни древнија, поучихсја во всјех дјељех Твојих, во творенијих руку Твојеју поучахсја."}, {"num": "6.", "text": "Воздјех к Тебје руцје моји, душа моја јако земља безводнаја Тебје."}, {"num": "7.", "text": "Скоро услиши мја Господи, исчезе дух мој, не отврати лица Твојего от мене, и уподобљусја низходјашчим в ров."}, {"num": "8.", "text": "Слишану сотвори мње зајутра милост Твоју, јако на Тја уповах, скажи мње Господи пут, в оњже појду, јако к Тебје взјах душу моју."}, {"num": "9.", "text": "Изми мја от враг мојих Господи, к Тебје прибјегох."}, {"num": "10.", "text": "Научи мја творити вољу Твоју, јако Ти јеси Бог мој. Дух Твој благиј наставит мја на земљу праву."}, {"num": "11.", "text": "Имене Твојего ради Господи живиши мја, правдоју Твојеју изведеши от печали душу моју."}, {"num": "12.", "text": "И милостију Твојеју потребиши враги моја, и погубиши всја стужајушчија души мојеј, јако аз раб Твој јесам. Слава:"}]}, "143": {"number": 143, "title": "Псалом 143. (143)", "subtitle": "", "verses": [{"num": "1.", "text": "Благословен Господ Бог мој, научајај руцје моји на ополченије, персти моја на бран."}, {"num": "2.", "text": "Милост моја и прибјежишче моје, заступник мој и избавитељ мој, зашчититељ мој, и на Њего уповах, повинујај људи моја под мја."}, {"num": "3.", "text": "Господи, что јест человјек, јако позналсја јеси јему, или син человјеч, јако вмјењајеши јего."}, {"num": "4.", "text": "Человјек сујетје уподобисја, дније јего јако сјен преходјат."}, {"num": "5.", "text": "Господи приклони небеса, и сниди, коснисја горам, и воздимјатсја."}, {"num": "6.", "text": "Бљесни молнију, и разженеши ја, посли стрјели Твоја, и смјатеши ја."}, {"num": "7.", "text": "Посли руку Твоју с висоти, изми мја и избави мја от вода многих, из руки синов чуждих."}, {"num": "8.", "text": "Ихже уста глагољаша сујету, и десница их десница неправди."}, {"num": "9.", "text": "Боже пјесан нову воспоју Тебје, во псалтири десјатоструњем поју Тебје."}, {"num": "10.", "text": "Дајушчему спасеније царем, избављајушчему Давида раба својего от меча љута."}, {"num": "11.", "text": "Избави мја и изми мја из руки синов чуждих, ихже уста глагољаша сујету, и десница их десница неправди."}, {"num": "12.", "text": "Ихже синове их јако новосажденија, водруженаја в јуности својеј, дшчери их удобрени, преукрашени јако подобије храма."}, {"num": "13.", "text": "Хранилишча их исполњена, отригајушчија от сего в сије, овци их многоплодни, множашчијасја во исходишчах својих, волове их толсти."}, {"num": "14.", "text": "Њест паденија оплоту, ниже прохода, ниже вопља в стогнах их."}, {"num": "15.", "text": "Ублажиша људи, имже сија сут, блажени људије, имже Господ Бог их."}]}, "144": {"number": 144, "title": "Псалом 144. (144)", "subtitle": "", "verses": [{"num": "1.", "text": "Вознесу Тја Боже мој, Царју мој, и благословљу имја Твоје во вјек и во вјек вјека."}, {"num": "2.", "text": "На всјак ден благословљу Тја, и восхваљу имја Твоје во вјек и во вјек вјека."}, {"num": "3.", "text": "Велиј Господ и хваљен зјело, и величију Јего њест конца."}, {"num": "4.", "text": "Род и род восхваљат дјела Твоја, и силу Твоју возвјестјат."}, {"num": "5.", "text": "Великољепије слави свјатињи Твојеја возглагољут, и чудеса Твоја повједјат."}, {"num": "6.", "text": "И силу страшних Твојих рекут, и величије Твоје повједјат."}, {"num": "7.", "text": "Памјат множества благости Твојеја отригнут, и правдоју Твојеју возрадујутсја."}, {"num": "8.", "text": "Шчедар и милостив Господ, долготерпјељив и многомилостив."}, {"num": "9.", "text": "Благ Господ всјаческим, и шчедроти Јего на всјех дјељех Јего."}, {"num": "10.", "text": "Да исповједјатсја Тебје Господи всја дјела Твоја, и преподобнији Твоји да благословљат Тја."}, {"num": "11.", "text": "Славу царствија Твојего рекут, и силу Твоју возглагољут."}, {"num": "12.", "text": "Сказати синовом человјеческим силу Твоју, и славу великољепија царствија Твојего."}, {"num": "13.", "text": "Царство Твоје царство всјех вјеков, и владичество Твоје во всјаком родје и родје. Вјерен Господ во всјех словесјех својих, и преподобен во всјех дјељех својих."}, {"num": "14.", "text": "Утверждајет Господ всја низпадајушчија, и возстављајет всја низверженија."}, {"num": "15.", "text": "Очи всјех на Тја уповајут, и Ти дајеши им пишчу во благовременији."}, {"num": "16.", "text": "Отверзајеши Ти руку Твоју, и исполњајеши всјакоје животно благовољенија"}, {"num": "17.", "text": "Праведен Господ во всјех путех својих, и преподобен во всјех дјељех својих."}, {"num": "18.", "text": "Близ Господ всјем призивајушчим Јего, всјем призивајушчим Јего во истиње."}, {"num": "19.", "text": "Вољу бојашчихсја Јего сотворит, и молитву их услишит, и спасет ја."}, {"num": "20.", "text": "Хранит Господ всја љубјашчија Јего, и всја грјешники потребит."}, {"num": "21.", "text": "Хвалу Господњу возглагољут уста моја, и да благословит всјака плот имја свјатоје Јего, во вјек и во вјек вјека. Слава:"}]}, "145": {"number": 145, "title": "Псалом 145. (145)", "subtitle": "", "verses": [{"num": "1.", "text": "Хвали душе моја Господа."}, {"num": "2.", "text": "Восхваљу Господа в животје мојем, поју Богу мојему дондеже јесам."}, {"num": "3.", "text": "Не надјејтесја на књази, на сини человјеческија, в њихже њест спасенија."}, {"num": "4.", "text": "Изидет дух јего, и возвратитсја в земљу своју: в тој ден погибнут всја помишљенија јего."}, {"num": "5.", "text": "Блажен, јемуже Бог Јаковаљ помошчник јего, упованије јего на Господа Бога својего."}, {"num": "6.", "text": "Сотворшаго Небо и Земљу, море и всја јаже в њих: храњашчаго истину во вјек:"}, {"num": "7.", "text": "Творјашчаго суд обидимим, дајушчаго пишчу алчушчим. Господ рјешит окованија:"}, {"num": "8.", "text": "Господ умудрјајет сљепци, Господ возводит низверженија: Господ љубит праведники."}, {"num": "9.", "text": "Господ хранит пришелци: сира и вдову пријимет, и пут грјешних погубит."}, {"num": "10.", "text": "Воцаритсја Господ во вјек. Бог Твој Сионе в род и род."}]}, "146": {"number": 146, "title": "Псалом 146. (146)", "subtitle": "", "verses": [{"num": "1.", "text": "Хвалите Господа, јако благ псалом, Богови нашему да усладитсја хваљеније."}, {"num": "2.", "text": "Зиждај Јерусалима Господ, разсјејанија Израиљева соберет."}, {"num": "3.", "text": "Исцјељајај сокрушенија сердцем, и објазујај сокрушенија их."}, {"num": "4.", "text": "Исчитајај множество звјезд, и всјем им имена нарицајај."}, {"num": "5.", "text": "Велиј Господ наш, и велија крјепост Јего, и разума Јего њест числа."}, {"num": "6.", "text": "Пријемљај кроткија Господ, смирјајај же грјешники до земљи."}, {"num": "7.", "text": "Начните Господеви во исповједанији, појте Богови нашему в гуслех."}, {"num": "8.", "text": "Одјевајушчему небо облаки, уготовљајушчему земљи дожд, прозјабајушчему на горах траву, и злак на службу человјеком."}, {"num": "9.", "text": "Дајушчему скотом пишчу их, и птенцем врановим призивајушчим Јего."}, {"num": "10.", "text": "Не в сиље коњстјеј восхошчет, ниже в листјех мужеских благоволит."}, {"num": "11.", "text": "Благоволит Господ в бојашчихсја Јего, и во уповајушчих на милост Јего."}]}, "147": {"number": 147, "title": "Псалом 147. (147)", "subtitle": "", "verses": [{"num": "1.", "text": "Похвали Јерусалиме Господа, хвали Бога твојего Сионе."}, {"num": "2.", "text": "Јако укрјепи вереј врат твојих, благослови сини твоја в тебје."}, {"num": "3.", "text": "Полагајај предјели твоја мир, и тука пшенична насишчајај тја."}, {"num": "4.", "text": "Посилајај слово своје земљи, до скорости течет слово Јего."}, {"num": "5.", "text": "Дајушчаго сњег свој јако волну, маглу јако пепел посипајушчаго."}, {"num": "6.", "text": "Метајушчаго голот свој јако хљеби, противу лица мраза Јего кто постојит."}, {"num": "7.", "text": "Послет слово своје, и истајет ја, дахнет Духа Јего, и потекут води."}, {"num": "8.", "text": "Возвјешчајај слово своје Јакову, оправданија и судби своја Израиљеви."}, {"num": "9.", "text": "Не сотвори тако всјакому јазику, и судби своја не јави им. Слава:"}]}, "148": {"number": 148, "title": "Псалом 148. (148)", "subtitle": "", "verses": [{"num": "1.", "text": "Хвалите Господа с Небес, хвалите Јего во вишњих."}, {"num": "2.", "text": "Хвалите Јего вси ангели Јего, хвалите Јего всја сили Јего."}, {"num": "3.", "text": "Хвалите Јего солнце и луна, хвалите Јего всја звјезди и свјет."}, {"num": "4.", "text": "Хвалите Јего небеса небес, и вода јаже превише небес."}, {"num": "5.", "text": "Да восхваљат имја Господње, јако Тој рече, и биша, Тој повеље, и создашасја."}, {"num": "6.", "text": "Постави ја во вјек, и во вјек вјека, повељеније положи, и не мимо идет."}, {"num": "7.", "text": "Хвалите Господа от земљи змијеве и всја бездни."}, {"num": "8.", "text": "Огањ, град, сњег, голот, дух бурен, творјашчаја слово Јего."}, {"num": "9.", "text": "Гори и вси холми, древа плодоносна и вси кедри."}, {"num": "10.", "text": "Звјерије и вси скоти, гади и птици пернати."}, {"num": "11.", "text": "Царије земстији и вси људије, књази и вси судији земстији."}, {"num": "12.", "text": "Јуноши и дјеви, старци с јунотами."}, {"num": "13.", "text": "Да восхваљат имја Господње, јако вознесесја имја Того јединаго, исповједаније Јего на земљи и на небеси."}, {"num": "14.", "text": "И вознесет рог људеј својих, пјесан всјем преподобним Јего, синовом Израиљевим, људем приближајушчимсја Јего."}]}, "149": {"number": 149, "title": "Псалом 149. (149)", "subtitle": "", "verses": [{"num": "1.", "text": "Воспојте Господеви пјесан нову, хваљеније Јего в церкви преподобних."}, {"num": "2.", "text": "Да возвеселитсја Израиљ о сотворшем јего, и синове Сиони возрадујутсја о Царје својем."}, {"num": "3.", "text": "Да восхваљат имја Јего в лицје, в тимпање и псалтири да појут Јему."}, {"num": "4.", "text": "Јако благоволит Господ в људех својих, и вознесет кроткија во спасеније."}, {"num": "5.", "text": "Восхваљатсја преподобнији во славје, и возрадујутсја на ложах својих."}, {"num": "6.", "text": "Возношенија Божија в гортани их, и мечи обојуду остри в руках их."}, {"num": "7.", "text": "Сотворити отмишченије во јазицјех, обличенија в људех."}, {"num": "8.", "text": "Свјазати цари их пути, и славнија их ручними окови жељезними."}, {"num": "9.", "text": "Сотворити в њих суд написан, слава сија будет всјем преподобним Јего."}]}, "150": {"number": 150, "title": "Псалом 150. (150)", "subtitle": "", "verses": [{"num": "1.", "text": "Хвалите Бога во свјатих Јего, хвалите Јего во утверженији сили Јего."}, {"num": "2.", "text": "Хвалите Јего на силах Јего, хвалите Јего по множеству величествија Јего."}, {"num": "3.", "text": "Хвалите Јего во гласје трубњем, хвалите Јего во псалтири и гуслех."}, {"num": "4.", "text": "Хвалите Јего во тимпање и лицје, хвалите Јего во струнах и оргање."}, {"num": "5.", "text": "Хвалите Јего в кимваљех доброгласних, хвалите Јего в кимваљех восклицанија."}, {"num": "6.", "text": "Всјакоје диханије да хвалит Господа. Слава: и ниње: Алилуја."}]}, "151": {"number": 151, "title": "Псалом 151. (151)", "subtitle": "Сеј псалом особ писан Давидов, и вне числа 150 псалмов", "verses": [{"num": "1.", "text": "Мал бјех в братији мојеј, и јуншиј в дому отца мојего, пасох овци отца мојего:"}, {"num": "2.", "text": "Руцје моји сотвористје орган, и персти моји составиша псалтир."}, {"num": "3.", "text": "И кто возвјестит Господеви мојему? Сам Господ, Сам услишит."}, {"num": "4.", "text": "Сам посла ангела својего, и взјат мја от овец отца мојего, и помаза мја јелејем помазанија својего."}, {"num": "5.", "text": "Братија моја добри и велици: и не благоволи в них Господ."}, {"num": "6.", "text": "Изидох в срјетеније иноплеменику, и прокљат мја идоли својими."}, {"num": "7.", "text": "Аз же исторгнув меч от њего, обезглавих јего, и отјах поношеније от синов Израиљевих. Слава:"}]}};
